		["confirmDelete"] = "Dieses Skript löschen?",
		["confirmRevert"] = "Ungespeicherte Änderungen verwerfen und den zuletzt gespeicherten Stand wiederherstellen?",
		["copyOutputAction"] = "Kopieren",
		["copyOutputHint"] = "Text markieren, dann mit Strg+C kopieren.",
		["cursorPosition"] = "Ln %d, Col %d",
		["customEventHelp"] = "WoW-Eventnamen eingeben und mit Enter oder + hinzufügen. Jedes Event lässt sich einzeln aktivieren oder entfernen. Ungültige Events werden abgelehnt. Im Skript enthält event den Namen und ... die Argumente. Beim Addon-Start werden die ADDON_LOADED-Argumente übergeben. Vor automatischer Ausführung das Skript speichern.",
		["customEvents"] = "Eigene Events",
		["customize"] = "Anpassen…",
		["debugBreakpoint"] = "Haltepunkt umschalten (F9)",
		["debugCallbackHelp"] = "Für einen OnEvent-Handler im Code nutze :SetScript(\"OnEvent\", ...) oder :HookScript(\"OnEvent\", ...), setze einen Haltepunkt im Callback und starte einmal Aktuelles Skript debuggen. Nach der Registrierung führen eintreffende Events den Callback im Debugger aus. CreateFrame und _G.CreateFrame funktionieren beide. Während einer Pause warten bis zu 50 Events; bei voller Warteschlange werden neue Events verworfen. nil-Argumente bleiben erhalten. Beim Beenden wird der vorherige SetScript-Handler wiederhergestellt, sofern noch der Debug-Handler gesetzt ist. HookScript-Hooks lassen sich nicht entfernen und werden beim Beenden inaktiv.",
		["debugClearBreakpoints"] = "Haltepunkte löschen",
		["debugContinue"] = "Fortsetzen (F5)",
		["debugDrawer"] = "Debug-Konsole ein- oder ausblenden",
		["debugEvents"] = "Konfigurierte Events debuggen",
		["debugEventsHelp"] = "Event-Debugging wartet auf aktivierte benutzerdefinierte Events und auf PLAYER_LOGIN, falls konfiguriert. Startup und Login werden nicht erneut ausgelöst. Mit Aktuelles Skript debuggen testest du den Code sofort.",
		["debugHelp"] = "Klicke auf eine Zeilennummer, um einen Haltepunkt zu setzen oder zu entfernen. Starte über den Debugger neben Ausführen oder wähle die konfigurierten Events. F5 setzt fort, F10 führt den nächsten Schritt aus, F11 springt in Skriptfunktionen, Shift+F5 beendet. In der Konsole kannst du lokale Variablen an der Haltestelle lesen und ändern. Fahre im Editor über eine Variable, um ihren Wert zu sehen. Neue Events warten in einer begrenzten Warteschlange, während WoW weiterläuft. Haltepunkte werden je Skript über Reloads hinweg gespeichert und folgen ihren Zeilen beim Einfügen oder Entfernen von Text. Markierungen auf nicht ausführbaren Zeilen bleiben erhalten, halten aber nicht an; beim Löschen einer ganzen Codezeile kann ihr Haltepunkt entfallen.",
		["debugHelperHelp"] = "F10 überspringt Helper-Aufrufe; F11 springt in gespeicherte Helper-Module, die über requireHelper geladen werden. Stimmt der Editor mit dem ausgeführten Code überein, nutzt der Debugger den normalen Editor. Bei einem abweichenden ungespeicherten Entwurf öffnet er eine schreibgeschützte Momentaufnahme und erhält den Entwurf. Speichere Helper-Änderungen vor einer neuen Debug-Sitzung.",
		["debugInspectUnavailable"] = "Kein Wert im aktuellen Gültigkeitsbereich",
		["debugLimits"] = "Der Debugger verwendet Code-Momentaufnahmen. Bearbeiten des aktiven Skripts beendet das Debugging; Haltepunkte bleiben erhalten und werden an die geänderten Zeilen angepasst. Nur über :SetScript oder :HookScript registrierte OnEvent-Callbacks werden eingereiht. Direkte pcall/xpcall-Aufrufe laufen ohne Einzelschritte. In native Funktionen kann nicht hineingesprungen werden. Callbacks, die synchron an eine native Funktion zurückkehren müssen, etwa beim Sortieren, können nicht pausieren. Nicht unterstützte Pausen verursachen Fehler. Instrumentierte Rückgaben erhalten die Lua-Endaufrufoptimierung nicht.",
		["debugNoEvents"] = "Füge zuerst ein Event in den Skripteinstellungen hinzu.",
		["debugPaused"] = "Haltepunkt erreicht",
		["debugProbeBindingsError"] = "Ungültige Debugger-Variablenbindung.",
		["debugProbeBindingsHelp"] = "Für diesen Test macht das optionale dritte Argument von breakpoint() echte lokale Variablen zugänglich: { amount = { get = function() return amount end, set = function(value) amount = value end } }. Die Konsole liest über get und ruft bei Zuweisungen set auf. Ohne set ist die Variable schreibgeschützt. Diese Bindungen gelten nur für den aktuellen Haltepunkt und Event-Aufruf; eingereihte Events behalten eigene lokale Variablen. Automatische Bereichserfassung und Code-Instrumentierung sind noch nicht eingebaut.",
		["debugProbeError"] = "Fehler im Debugger-Test",
		["debugProbeEvaluate"] = "Auswerten",
		["debugProbeFinished"] = "Durchlauf beendet",
		["debugProbeHelp"] = "/lwdebug EVENT aktiviert den aktuellen Code; /lwdebug fire reiht ein Testevent ein; /lwdebug step setzt fort; /lwdebug stop bricht ab und leert die Warteschlange. Mit breakpoint(\"Name\", {wert=wert}) erfasst du Variablen. F10 geht zum nächsten Haltepunkt, wenn dieses Fenster oder der Editor aktiv ist. Maximal 50 Events warten in Reihenfolge. WoW läuft weiter; Tabellen bleiben lebende Referenzen. Automatische Zeilenschritte, F11 und Helper-Importe werden nicht unterstützt. Haltepunkte innerhalb von pcall/xpcall werden nicht unterstützt. Secret-Werte sind in der Liste maskiert; Secret-Strings können direkt im Tooltip erscheinen.",
		["debugProbeInput"] = "Ausdruck oder Lua-Code",
		["debugProbeNotPaused"] = "Halte zuerst an einem Haltepunkt an, um Code auszuwerten.",
		["debugProbeOverflow"] = "%d verworfen",
		["debugProbePaused"] = "Haltepunkt erreicht",
		["debugProbeQueue"] = "Warteschlange: %d",
		["debugProbeReadOnly"] = "Diese Variable ist schreibgeschützt.",
		["debugProbeShow"] = "Code anzeigen",
		["debugProbeSnapshot"] = "Erfasster Code (schreibgeschützt)",
		["debugProbeStep"] = "Nächster Haltepunkt (F10)",
		["debugProbeStop"] = "Test beenden",
		["debugProbeTerminal"] = "Debug-Konsole",
		["debugProbeTerminalHelp"] = "Die Testkonsole liest an breakpoint() übergebene Variablen und die Skriptumgebung. Ausdrückliche Bindungen ändern echte lokale Variablen; andere einfache Zuweisungen bleiben in der Konsole. Tabellenänderungen und Funktionsaufrufe wirken auf das Skript.\n\nEnter: auswerten und Eingabe leeren.\nAlt+Pfeil hoch/runter: bis zu 100 Befehle aufrufen.\n/lwdebug eval AUSDRUCK wertet ebenfalls Code aus. Neue Ausgabe scrollt ans Ende; 100 Ausgabezeilen bleiben erhalten.\n\nBei Fehlern bleibt das Skript pausiert. Secret-Werte bleiben maskiert.",
		["debugProbeTitle"] = "Debugger-Test",
		["debugProbeVariables"] = "Erfasste Variablen",
		["debugProbeWaiting"] = "Warte auf Event",
		["debugReadOnly"] = "Code beim Debuggen schreibschützen",
		["debugScheduleAlways"] = "Bei jedem Login/Reload",
		["debugScheduleCancel"] = "Vorgemerktes Debugging abbrechen",
		["debugScheduleHelp"] = "Über das Käfer-Menü kannst du ein gespeichertes Script für den nächsten Login/Reload vormerken: standardmäßig einmalig oder bei jedem Start. ADDON_LOADED bezeichnet das Laden von LuaWorkbench selbst; PLAYER_LOGIN den Login. Gespeicherter Code, Helper und Breakpoints werden verwendet; Entwürfe bleiben erhalten. Der Editor startet minimiert ohne Fokusübernahme. Die normale automatische Ausführung dieses Scripts wird unterdrückt, solange der Start-Debugger es verwaltet, auch bei einem Kompilierungsfehler. Stopp gibt diese Ausführung wieder frei. Stopp löscht keine dauerhafte Vormerkung; nutze dafür Vorgemerktes Debugging abbrechen. WoW läuft weiter; vorher geladene Addons lassen sich nicht rückwirkend debuggen.",
		["debugScheduleMenu"] = "Nach Login/Reload debuggen (gespeicherter Code)",
		["debugScheduleOnce"] = "Einmalig",
		["debugShow"] = "Zur angehaltenen Zeile",
		["debugSnapshot"] = "Ausgeführter Debug-Code",
		["debugSnapshotHelp"] = "Diese schreibgeschützte Ansicht zeigt den vom Debugger ausgeführten Code. Ungespeicherte Editorentwürfe bleiben erhalten.",
		["debugSourceChanged"] = "Debugging beendet, weil das Skript geändert wurde.",
		["debugStart"] = "Aktuelles Skript debuggen",
		["debugStepInto"] = "In Funktion springen (F11)",
		["debugStepOver"] = "Nächster Schritt (F10)",
		["debugStop"] = "Debugging beenden (Shift+F5)",
		["debugTerminal"] = "Debug-Konsole",
		["debugTerminalHelp"] = "Werte während einer Pause Ausdrücke oder Lua-Code aus. Zuweisungen ändern zugängliche lokale Variablen; Tabellenänderungen und Funktionsaufrufe wirken auf das laufende Skript.\n\nEnter: auswerten und Eingabe leeren.\nAlt+Pfeil hoch/runter: vorherige Befehle aufrufen.\nNeue Ausgabe scrollt ans Ende.\n\nBei Fehlern bleibt das Skript pausiert. Secret-Werte bleiben in der Konsole maskiert; Secret-Strings können im Hover-Tooltip erscheinen.",
		["debugTitle"] = "Debugger",
		["debugUnsupportedYield"] = "Dieser geschützte oder native Aufruf kann nicht pausieren; Debugging beendet.",
		["debugVariables"] = "Variablen",
		["debugWaitingCallbacks"] = "Warte auf Skript-Events",
		["debugWriteProtected"] = "Schreibgeschützt beim Debuggen",
		["debuggerBudgetExceeded"] = "Debug-Ausführung nach zu vielen Schritten beendet.",
		["delete"] = "Löschen",
		["developerToolUnavailable"] = "Dieses Blizzard-Entwicklerwerkzeug konnte nicht geladen werden.",
		["dirtyText"] = "Text statt Ungespeichert-Punkt",
		["errorDetails"] = "Fehlerdetails",
		["errorHistoryHelp"] = "Speichert bis zu 100 aktuelle Skriptfehler dieser Sitzung, auch aus automatischen Läufen. Wiederholte Fehler werden mit Anzahl und letzter Uhrzeit zusammengefasst. Ein Reload leert den Speicher. Das Leeren der Ausgabe löscht diese Liste nicht.",
		["eventAlreadyAdded"] = "Dieses Event steht bereits in der Liste.",
		["eventName"] = "Eventnamen eingeben…",
		["eventTraceTool"] = "Event Trace ein- oder ausblenden (/etrace). Grün: Fenster geöffnet.",
		["findCode"] = "Im Code suchen",
		["font"] = "Schriftart",
		["fontChat"] = "Chat",
		["fontNumbers"] = "Zahlen",
		["fontSize"] = "Schriftgröße",
		["fontStyle"] = "Schriftstil",
		["fontUI"] = "Oberfläche",
		["frameStackTool"] = "Frame Stack umschalten (/fstack). Grün: aktiv.",
		["fullscreen"] = "Fenster-Vollbild umschalten",
		["goToDefinition"] = "Zur Definition",
		["help"] = "Hilfe",
		["helpDebug"] = "print(...) schreibt in den Output. addon und editor verweisen auf LuaWorkbench. Fehler bleiben im Output; der Ausführungsstatus wird separat angezeigt. Output kopieren markiert den Text für Strg+C. Die Zeilenzahl ist einstellbar; zusätzlich gilt ein Limit von 64.000 Zeichen. Code formatieren erfolgt nur auf Wunsch. Optionen steuern Schrift, Einrückung, Klammern, LF/CRLF und Minimap-Button. Nach manuellem Leeren lässt sich die Ausgabe 10 Sekunden lang wiederherstellen. Später hinzugekommene Ausgabe bleibt dabei erhalten; das eingestellte Output-Limit gilt weiterhin.",
		["helpDump"] = "dump(...) schreibt jedes Argument einzeln in den Output, einschließlich nil zwischen Argumenten und am Ende. dump({...}) gibt stattdessen eine Tabelle aus. Beispiel: dump(\"Wert\", nil, false). DevTools_Dump(value, startKey) behält seine ursprüngliche Signatur; das optionale zweite Argument benennt den ausgegebenen Wert. Das gilt für manuelle und automatische Läufe, Helper-Module und das Debug-Terminal. Diese Funktionen gelten nur in der Skriptumgebung; globale Funktionen bleiben unverändert. Mehrere Argumente werden mit arg[1], arg[2] usw. beschriftet; ein einzelnes Argument bleibt ohne Nummer. Tabelleninhalte stehen unter dem jeweiligen Argumentnamen. Verwende dump(...), um nil-Argumente zu erhalten: Eine mit {...} erzeugte Tabelle bewahrt nicht die vollständige Argumentanzahl. Große Dumps erweitern den Output-Puffer bis zum Leeren. Das Tabellenlimit von 30 Einträgen entfällt; Blizzards Tiefen- und Zeichenkettenlimits gelten weiterhin.",
		["helpEditing"] = "Mit Fokus im Code oder einem Suchfeld: Strg+Enter führt aus, Strg+S speichert, Strg+F durchsucht diesen Code, Strg+Umschalt+F durchsucht alle Skript-Namen und deren Code. F5 führt aus, wenn der Editor den Fokus hat oder die Maus darüber liegt; in den Optionen abschaltbar. Im Code: Tab fügt Leerzeichen ein, Umschalt+Tab entfernt führende Einrückung. In der Suche: Enter / Umschalt+Enter wählt den nächsten / vorherigen Treffer; Escape schließt die Codesuche. Beim Umbenennen: Enter bestätigt, Escape bricht ab. Rechtsklick im bearbeitbaren Code: gesamten Code formatieren oder einen gespeicherten Textbaustein beziehungsweise Helper-Import an der aktuellen Cursorposition einfügen. Navigation zu Definitionen gibt es nur im Haupteditor. Umschalt+Alt+F formatiert den fokussierten Codeeditor, auch den Textbaustein-Editor. Im Haupteditor: Strg+Leertaste öffnet Vorschläge, Hoch/Runter wählt aus, Enter / Tab fügt ein und Esc schließt sie. Die API-Parameterhilfe markiert das aktuelle Argument. Alt+Hoch/Runter verschiebt die aktuelle Zeile; Alt+Shift+Hoch/Runter dupliziert sie. Ohne Auswahl kopiert/schneidet Strg+C/X die Zeile; Strg+V fügt kopierte Zeilen über der aktuellen Zeile ein. Gespeicherte Zeilenumbrüche folgen den Optionen. (macOS: ⌘C / ⌘X / ⌘V). Mac: Strg+Backspace löscht ein Zeichen, Option+Backspace das vorherige Wort und Cmd+Backspace bis zum Zeilenanfang. Mac: Option+Links/Rechts springt wortweise, Cmd+Links/Rechts zum Zeilenanfang/-ende. Mit Shift wird die Auswahl erweitert. Cmd+Hoch/Runter springt zum Codeanfang/-ende; mit Shift wird bis dorthin markiert.",
		["helpSecretDump"] = "Secret-Dumps im Blizzard-Chat ist standardmäßig aus. Wenn aktiviert, geben dump() und DevTools_Dump() den gesamten Dump zusätzlich über Blizzards normale Ausgabe aus, sobald der Wert oder eine formatierte Zeile geheim ist. Im Editor bleibt der grüne <secret>-Marker. Normale Dumps und print() werden nicht weitergeleitet. Gilt auch für automatische Runs; was Blizzard anzeigen kann, hängt vom Client und dessen Secret-Beschränkungen ab.",
		["helpShortcuts"] = "Tastenkürzel",
		["helpStorage"] = "Neue Skripte direkt in der Liste benennen. Rechtsklick auf ein Skript: umbenennen, verschieben, löschen oder gespeicherten Stand wiederherstellen. Der Punkt zeigt ungespeicherte Änderungen. Strg+S ersetzt den gespeicherten Stand. Entwürfe werden standardmäßig nach einem Reload wiederhergestellt; in den Optionen abschaltbar. Zurücksetzen verwirft Änderungen nach Bestätigung. Ordnerpfeile klappen Skripte ein oder aus.",
		["helpTabDebug"] = "Fehlersuche",
		["helpTabEditor"] = "Editor",
		["helpTabScripts"] = "Skripte & Helper",
		["helpTabShortcuts"] = "Tastenkürzel",
		["helperConsumerHelp"] = "In einem anderen Skript den Helper unter einem lokalen Namen importieren. Eine eigene lokale Funktion kann denselben Funktionsnamen tragen, ohne den Helper zu ersetzen:",
		["helperCycle"] = "Zirkuläre Helper-Abhängigkeit:",
		["helperDuplicate"] = "Dieser Modulname wird bereits verwendet:",
		["helperEnabled"] = "Als Helper-Modul bereitstellen",
		["helperHelp"] = "Ein Skript speichern, seine Einstellungen öffnen und es unter einem eindeutigen Namen wie MyTools als Helper-Modul bereitstellen. Der Modulname ist vom Anzeigetitel unabhängig; Namen mit unterschiedlicher Groß-/Kleinschreibung gelten als gleich. Ein Helper gibt eine Tabelle mit Funktionen oder Werten zurück und läuft erst beim Aufruf von requireHelper. Jeder manuelle oder automatische Lauf erhält einen neuen Modulcache; wiederholte und verschachtelte Imports im selben Lauf teilen dieselbe Tabelle. Fehlende Module, doppelte Namen, Zyklen und Rückgaben ohne Tabelle erzeugen Fehler. Helper-Variablen bleiben in der internen Umgebung; Schreiben nach _G erfolgt nur ausdrücklich. Beispiel für einen Helper:",
		["helperInlineHelp"] = "Ein Helper muss am Ende return tools (oder eine andere Tabelle) zurückgeben. In diese Tabelle gehören die Funktionen, die du teilen möchtest. requireHelper liefert genau diese Tabelle, über die ein anderes Skript die Funktionen aufruft. Ohne Tabellenrückgabe schlägt der Import fehl. Nur gespeicherter Code wird bei Bedarf ausgeführt; das Aktivieren startet ihn nicht.",
		["helperInvalidName"] = "Mit einem Buchstaben oder Unterstrich beginnen; danach Buchstaben, Zahlen, _, . oder - verwenden (maximal 80 Zeichen).",
		["helperLoadError"] = "Helper-Modul konnte nicht geladen werden",
		["helperMissing"] = "Kein aktiviertes, gespeichertes Helper-Modul:",
		["helperModule"] = "Helper-Module",
		["helperMustReturnTable"] = "Das Helper-Modul muss eine Tabelle zurückgeben:",
		["helperName"] = "Eindeutiger Modulname",
		["helperNameHelp"] = "Unabhängig vom Skripttitel. Modulnamen müssen eindeutig sein; Groß-/Kleinschreibung zählt dabei nicht. Einen geänderten Namen mit Enter übernehmen.",
