		["confirmDelete"] = "¿Eliminar este script?",
		["confirmRevert"] = "¿Descartar cambios sin guardar y restaurar la última versión guardada?",
		["copyOutputAction"] = "Copiar",
		["copyOutputHint"] = "Seleccionar texto y pulsar Ctrl+C para copiar.",
		["cursorPosition"] = "Lín %d, Col %d",
		["customEventHelp"] = "Introduce un evento de WoW y pulsa Intro o + para añadirlo. Cada evento se puede activar o eliminar por separado. Los eventos no válidos se rechazan. En el script, event contiene el nombre y ... los argumentos. El inicio pasa los argumentos de ADDON_LOADED. Guarda el script antes de usar la ejecución automática.",
		["customEvents"] = "Eventos personalizados",
		["customize"] = "Personalizar…",
		["debugBreakpoint"] = "Alternar punto de interrupción (F9)",
		["debugCallbackHelp"] = "Para depurar un manejador OnEvent definido en el código, usa :SetScript(\"OnEvent\", ...) o :HookScript(\"OnEvent\", ...), coloca un punto de interrupción dentro y ejecuta Depurar el script actual una vez. Tras el registro, los eventos entrantes ejecutan el manejador en el depurador. Funcionan CreateFrame y _G.CreateFrame. Durante la pausa esperan hasta 50 eventos; con la cola llena se descartan los nuevos y se conservan los argumentos nil. Al detener, se restaura el manejador SetScript anterior si aún está instalado el de depuración. Los hooks de HookScript no se pueden quitar y quedan inactivos al detener.",
		["debugClearBreakpoints"] = "Borrar puntos de interrupción",
		["debugContinue"] = "Continuar (F5)",
		["debugDrawer"] = "Mostrar u ocultar la consola de depuración",
		["debugEvents"] = "Depurar los eventos configurados",
		["debugEventsHelp"] = "La depuración de eventos espera los eventos personalizados activados y PLAYER_LOGIN, si está configurado. No repite el inicio ni la conexión. Usa Depurar el script actual para probar el código inmediatamente.",
		["debugHelp"] = "Haz clic en un número de línea para alternar un punto de interrupción. Inicia la depuración con el botón junto a Ejecutar o elige los eventos configurados. F5 continúa, F10 avanza sin entrar, F11 entra en funciones del script y Shift+F5 detiene. La consola permite leer y cambiar variables locales en la línea pausada. Pasa el cursor sobre una variable para verla. Los eventos nuevos esperan en una cola limitada mientras WoW sigue funcionando. Los puntos de interrupción se guardan por script entre recargas y siguen sus líneas al insertar o quitar texto. Los marcadores en líneas no ejecutables se conservan, pero no pausan; borrar una línea completa puede eliminar su punto.",
		["debugHelperHelp"] = "F10 pasa por encima de las llamadas a módulos; F11 entra en módulos guardados cargados mediante requireHelper. Si el editor coincide con el código ejecutado, se usa el editor normal. Si un borrador sin guardar difiere, se abre una copia de solo lectura y se conserva el borrador. Guarda los cambios del módulo antes de otra sesión.",
		["debugInspectUnavailable"] = "Sin valor en el ámbito actual",
		["debugLimits"] = "El depurador usa copias del código. Editar el script activo detiene la depuración; los puntos de interrupción se conservan y se ajustan a las líneas modificadas. Solo se encolan manejadores OnEvent registrados con :SetScript o :HookScript. Las llamadas directas a pcall/xpcall se ejecutan sin pasos. No se puede entrar en funciones nativas; los callbacks que deben regresar de forma síncrona a una función nativa, como los de ordenación, no pueden pausarse. Las pausas no admitidas causan errores. Los retornos instrumentados no conservan la optimización de llamadas de cola de Lua.",
		["debugNoEvents"] = "Añade primero un evento en los ajustes del script.",
		["debugPaused"] = "Punto de interrupción alcanzado",
		["debugProbeBindingsError"] = "Vinculación de variable de depuración no válida.",
		["debugProbeBindingsHelp"] = "En esta prueba, el tercer argumento opcional de breakpoint() expone variables locales reales: { amount = { get = function() return amount end, set = function(value) amount = value end } }. La consola lee mediante get y asigna mediante set. Sin set, la variable es de solo lectura. Las vinculaciones solo sirven para el punto y evento actuales; los eventos en cola conservan sus propias variables. La captura automática del ámbito y la instrumentación aún no están implementadas.",
		["debugProbeError"] = "Error de prueba del depurador",
		["debugProbeEvaluate"] = "Evaluar",
		["debugProbeFinished"] = "Ejecución completada",
		["debugProbeHelp"] = "/lwdebug EVENT activa el código actual; /lwdebug fire añade un evento de prueba; /lwdebug step avanza; /lwdebug stop cancela y vacía la cola. Usa breakpoint(\"nombre\", {valor=valor}) para capturar variables. F10 avanza al siguiente punto con este panel o el editor activo. Esperan hasta 50 eventos en orden. WoW sigue funcionando y las tablas mantienen referencias activas. No se admiten pasos automáticos por línea, F11, importaciones de módulos ni puntos dentro de pcall/xpcall. Los valores secretos se ocultan en la lista; las cadenas secretas pueden mostrarse directamente en la descripción emergente.",
		["debugProbeInput"] = "Expresión o código Lua",
		["debugProbeNotPaused"] = "Detente en un punto de interrupción antes de evaluar código.",
		["debugProbeOverflow"] = "%d descartados",
		["debugProbePaused"] = "Punto de interrupción alcanzado",
		["debugProbeQueue"] = "En cola: %d",
		["debugProbeReadOnly"] = "Esta variable es de solo lectura.",
		["debugProbeShow"] = "Mostrar código",
		["debugProbeSnapshot"] = "Código capturado (solo lectura)",
		["debugProbeStep"] = "Siguiente punto (F10)",
		["debugProbeStop"] = "Detener prueba",
		["debugProbeTerminal"] = "Consola de depuración",
		["debugProbeTerminalHelp"] = "La consola de prueba lee las variables pasadas a breakpoint() y el entorno del script. Las vinculaciones explícitas cambian variables locales reales; otras asignaciones simples quedan en la consola. Modificar tablas y llamar a funciones afecta al script.\n\nIntro: evaluar y vaciar la entrada.\nAlt+Arriba/Abajo: recuperar hasta 100 comandos.\n/lwdebug eval EXPRESIÓN también evalúa código. La salida nueva desplaza la vista al final; se conservan 100 líneas.\n\nLos errores mantienen la pausa. Los valores secretos se ocultan.",
		["debugProbeTitle"] = "Prueba del depurador",
		["debugProbeVariables"] = "Variables capturadas",
		["debugProbeWaiting"] = "Esperando evento",
		["debugReadOnly"] = "Proteger el código al depurar",
		["debugScheduleAlways"] = "Cada inicio de sesión/recarga",
		["debugScheduleCancel"] = "Cancelar depuración programada",
		["debugScheduleHelp"] = "Programa un script guardado desde el menú del depurador, una vez o en cada inicio. ADDON_LOADED corresponde a LuaWorkbench; PLAYER_LOGIN al inicio de sesión. Se usan código, módulos y puntos de interrupción guardados, conservando los borradores. El editor se abre minimizado sin tomar el foco. La ejecución automática normal se omite mientras el depurador controla el script, incluso si falla la compilación. Detener libera el script, pero no cancela la programación recurrente. WoW sigue funcionando; los addons cargados antes no se pueden depurar retroactivamente.",
		["debugScheduleMenu"] = "Depurar tras iniciar sesión/recargar (código guardado)",
		["debugScheduleOnce"] = "Una vez",
		["debugShow"] = "Ir a la línea pausada",
		["debugSnapshot"] = "Código ejecutado en depuración",
		["debugSnapshotHelp"] = "Esta vista de solo lectura muestra el código usado por el depurador. Se conservan los borradores sin guardar del editor.",
		["debugSourceChanged"] = "La depuración se detuvo porque cambió el script.",
		["debugStart"] = "Depurar el script actual",
		["debugStepInto"] = "Paso hacia dentro (F11)",
		["debugStepOver"] = "Paso por encima (F10)",
		["debugStop"] = "Detener depuración (Shift+F5)",
		["debugTerminal"] = "Consola de depuración",
		["debugTerminalHelp"] = "Durante una pausa, evalúa expresiones o código Lua. Las asignaciones cambian variables locales accesibles; modificar tablas y llamar a funciones afecta al script.\n\nIntro: evaluar y vaciar la entrada.\nAlt+Arriba/Abajo: recuperar comandos anteriores.\nLa salida nueva desplaza la vista al final.\n\nLos errores mantienen la pausa. Los valores secretos se ocultan en la consola; las cadenas secretas pueden aparecer al pasar el cursor.",
		["debugTitle"] = "Depurador",
		["debugUnsupportedYield"] = "Esta llamada protegida o nativa no puede pausarse; se detuvo la depuración.",
		["debugVariables"] = "Variables",
		["debugWaitingCallbacks"] = "Esperando eventos del script",
		["debugWriteProtected"] = "Solo lectura al depurar",
		["debuggerBudgetExceeded"] = "La depuración se detuvo tras demasiados pasos.",
		["delete"] = "Eliminar",
		["developerToolUnavailable"] = "No se ha podido cargar esta herramienta de desarrollo de Blizzard.",
		["dirtyText"] = "Texto en lugar del punto sin guardar",
		["errorDetails"] = "Detalles del error",
		["errorHistoryHelp"] = "Conserva hasta 100 errores recientes de scripts durante esta sesión, incluidas ejecuciones automáticas. Los repetidos se agrupan con un contador y la última hora. Recargar borra el historial. Vaciar la salida no borra esta lista.",
		["eventAlreadyAdded"] = "Este evento ya está en la lista.",
		["eventName"] = "Nombre del evento…",
		["eventTraceTool"] = "Mostrar u ocultar Event Trace (/etrace). Verde: ventana abierta.",
		["findCode"] = "Buscar en el código",
		["font"] = "Fuente",
		["fontChat"] = "Chat",
		["fontNumbers"] = "Números",
		["fontSize"] = "Tamaño de fuente",
		["fontStyle"] = "Estilo de fuente",
		["fontUI"] = "Interfaz",
		["frameStackTool"] = "Activar o desactivar Frame Stack (/fstack). Verde: activo.",
		["fullscreen"] = "Alternar pantalla completa",
		["goToDefinition"] = "Ir a la definición",
		["help"] = "Ayuda",
		["helpDebug"] = "print(...) escribe en Salida. addon y editor hacen referencia a LuaWorkbench. Los errores permanecen en Salida; el estado se muestra aparte. Copiar salida selecciona el texto para Ctrl+C. El límite de líneas es configurable, con un máximo adicional de 64.000 caracteres. Formatear código solo actúa al solicitarlo. Opciones controla fuentes, sangría, cierre de paréntesis, LF/CRLF y el botón del minimapa. Tras vaciar la salida manualmente, puedes deshacerlo durante 10 segundos. La salida posterior se conserva al restaurar; se sigue aplicando el límite de salida configurado.",
		["helpDump"] = "dump(...) muestra cada argumento por separado en Salida, incluidos los valores nil intermedios y finales. dump({...}) muestra una sola tabla. Ejemplo: dump(\"valor\", nil, false). DevTools_Dump(value, startKey) conserva su firma original; el segundo argumento opcional nombra el valor mostrado. Se aplica a ejecuciones manuales y automáticas, módulos auxiliares y la consola de depuración. Estas funciones solo existen en el entorno del script; las funciones globales no cambian. Varios argumentos se etiquetan como arg[1], arg[2], etc.; un solo argumento queda sin número. El contenido de cada tabla aparece bajo su etiqueta. Usa dump(...) para conservar argumentos nil: una tabla creada con {...} no conserva el número total de argumentos. Los volcados grandes amplían el búfer de salida hasta que se vacía. No se aplica el límite de 30 entradas por tabla; siguen vigentes los límites de profundidad y cadenas de Blizzard.",
		["helpEditing"] = "Con el foco en el código o la búsqueda: Ctrl+Enter ejecuta, Ctrl+S guarda, Ctrl+F busca en este código y Ctrl+Mayús+F busca en todos los nombres y códigos. F5 ejecuta con el foco o el puntero en el editor; se desactiva en Opciones. Tab inserta espacios y Mayús+Tab quita sangría inicial. En la búsqueda: Enter / Mayús+Enter selecciona la coincidencia siguiente / anterior; Escape cierra la búsqueda de código. Al renombrar: Enter confirma, Escape cancela. Haz clic derecho en el código editable para formatearlo entero o insertar un fragmento guardado o una importación de módulo en el cursor actual. La navegación a definiciones solo está disponible en el editor principal. Mayús+Alt+F formatea el editor de código enfocado, incluido el de fragmentos. En el editor principal: Ctrl+Espacio abre sugerencias, Arriba/Abajo selecciona, Enter / Tab inserta y Esc cierra. La ayuda de parámetros marca el argumento actual. Alt+Arriba/Abajo mueve la línea; Alt+Mayús+Arriba/Abajo la duplica. Sin selección, Ctrl+C/X copia/corta la línea y Ctrl+V la inserta encima de la actual. Los saltos de línea guardados siguen las opciones. (macOS: ⌘C / ⌘X / ⌘V). Mac: Ctrl+Backspace borra un carácter, Option+Backspace la palabra anterior y Cmd+Backspace hasta el inicio de la línea. Mac: Option+Izquierda/Derecha salta por palabras; Cmd+Izquierda/Derecha va al inicio/final de línea. Añade Shift para ampliar la selección. Cmd+Arriba/Abajo va al inicio/final del código; añade Shift para seleccionar.",
		["helpSecretDump"] = "Dumps secretos en el chat está desactivado por defecto. Al activarlo, dump() y DevTools_Dump() también envían el dump completo a la salida normal de Blizzard si el valor o una línea formateada es secreto. El editor conserva el marcador verde <secret>. Los dumps normales y print() no se reenvían. También se aplica a las ejecuciones automáticas; lo que Blizzard puede mostrar depende del cliente y de sus restricciones de valores secretos.",
		["helpShortcuts"] = "Atajos de teclado",
		["helpStorage"] = "Nombra los scripts nuevos directamente en la lista. Clic derecho para renombrar, mover, eliminar o restaurar la versión guardada. El punto indica cambios sin guardar. Ctrl+S reemplaza la versión guardada. La recuperación de borradores tras recargar está activada por defecto y puede desactivarse en Opciones. Restaurar descarta cambios tras confirmar. Las flechas de carpeta contraen o expanden su contenido.",
		["helpTabDebug"] = "Depuración",
		["helpTabEditor"] = "Editor",
		["helpTabScripts"] = "Scripts y módulos",
		["helpTabShortcuts"] = "Atajos",
		["helperConsumerHelp"] = "En otro script, importa el módulo con un nombre local. Una función local propia puede tener el mismo nombre sin reemplazar la del módulo:",
		["helperCycle"] = "Dependencia circular entre módulos:",
		["helperDuplicate"] = "Este nombre de módulo ya está en uso:",
		["helperEnabled"] = "Ofrecer como módulo auxiliar",
		["helperHelp"] = "Guarda un script y actívalo como módulo auxiliar en sus ajustes con un nombre único, como MyTools. El nombre del módulo es independiente del título; las mayúsculas no distinguen nombres. Devuelve una tabla de funciones o valores y solo se ejecuta cuando requireHelper lo solicita. Cada ejecución manual o automática tiene una caché nueva; las importaciones repetidas o anidadas comparten la tabla. Los módulos ausentes, nombres duplicados, ciclos y resultados que no sean tablas generan errores. Las variables permanecen en el entorno interno; escribir en _G requiere hacerlo explícitamente. Ejemplo de módulo:",
		["helperInlineHelp"] = "Un módulo auxiliar debe terminar con return tools (u otra tabla). Pon en esa tabla las funciones que quieras compartir. requireHelper devuelve esa tabla para que otro script pueda llamar a sus funciones. Sin una tabla de retorno, la importación falla. Solo se ejecuta el código guardado cuando se solicita; activar esta opción no lo ejecuta.",
		["helperInvalidName"] = "Empieza con una letra o _; después usa letras, números, _, . o - (máximo 80 caracteres).",
		["helperLoadError"] = "No se pudo cargar el módulo auxiliar",
		["helperMissing"] = "No hay ningún módulo auxiliar activado y guardado:",
		["helperModule"] = "Módulos auxiliares",
		["helperMustReturnTable"] = "El módulo auxiliar debe devolver una tabla:",
		["helperName"] = "Nombre de módulo único",
		["helperNameHelp"] = "Independiente del título del script. Los nombres son únicos sin distinguir mayúsculas. Pulsa Intro para aplicar un cambio.",
		["helperUsageExample"] = "En otro script:",
		["hexColor"] = "Color con seis dígitos hexadecimales (RRGGBB); Intro para aplicar.",
		["indentWidth"] = "Sangría (espacios)",
		["inspectorCopyPath"] = "Copiar ruta de acceso",
		["inspectorCopyValue"] = "Copiar valor",
		["inspectorInsert"] = "Insertar en el código",
		["inspectorLimit"] = "Límite: primeros 500 campos",
		["inspectorLocal"] = "Insertar como variable local",
		["inspectorOpen"] = "Abrir objeto",
		["inspectorParent"] = "Ir al objeto padre",
		["inspectorPick"] = "Elegir marco",
		["inspectorPickHelp"] = "Alt izq.: siguiente · Alt der.: anterior · Ctrl: inspeccionar · Esc: cancelar",
		["inspectorRefresh"] = "Actualizar",
		["inspectorSearch"] = "Buscar campos y valores expandidos",
		["inspectorSession"] = "Las referencias duran hasta recargar. Clic derecho en una fila para ver acciones.",
		["inspectorTitle"] = "Inspector de objetos",
