		["apiFunctions"] = "Fonctions / méthodes",
		["apiHelp"] = "Aide et coloration de l’API Blizzard",
		["apiIndexing"] = "Préparation de la recherche intégrale : %d / %d · recherche par nom disponible",
		["apiOptional"] = "facultatif",
