		["apiTypes"] = "Types",
		["apiUnavailable"] = "Impossible de charger la documentation de l’API Blizzard. Rouvrez l’éditeur pour réessayer.",
		["autoIndent"] = "Indentation automatique",
		["autoPairs"] = "Fermer les parenthèses et guillemets",
		["autoRunHelp"] = "Les exécutions automatiques utilisent le code enregistré, jamais les modifications non enregistrées. Le démarrage intervient une fois au chargement de LuaWorkbench (ADDON_LOADED), la connexion une fois à PLAYER_LOGIN, même après un rechargement. Si les deux sont activés, le script tourne aux deux étapes. Un événement personnalisé le lance à chaque occurrence, même éditeur fermé. Tout est désactivé par défaut ; activer une option ne lance rien immédiatement.",
		["autocomplete"] = "Complétion du code et aide aux paramètres",
		["autocompleteHelp"] = "Enter / Tab : insérer · Échap : fermer · Ctrl+Espace : suggestions",
		["automaticRun"] = "Exécution automatique",
		["clearErrors"] = "Effacer les erreurs",
		["clearOnRun"] = "Vider à chaque exécution",
		["clearOutputAction"] = "Effacer",
		["clearSearch"] = "Effacer la recherche",
