		["colorIdentifier"] = "Noms / identifiants",
		["colorKeyword"] = "Mots-clés",
		["colorLiteral"] = "true / false / nil",
		["colorLocalVariable"] = "Variables locales",
		["colorNumber"] = "Nombres",
		["colorOperator"] = "Opérateurs",
		["colorParameter"] = "Paramètres de fonction",
		["colorPunctuation"] = "Parenthèses et ponctuation",
		["colorString"] = "Chaînes de caractères",
		["confirmDelete"] = "Supprimer cet script ?",
		["confirmRevert"] = "Abandonner les modifications et restaurer la dernière version enregistrée ?",
		["copyOutputAction"] = "Copier",
		["copyOutputHint"] = "Sélectionner le texte, puis appuyer sur Ctrl+C pour copier.",
		["cursorPosition"] = "Lig %d, Col %d",
		["customEventHelp"] = "Saisissez un événement WoW, puis appuyez sur Entrée ou + pour l’ajouter. Chaque événement peut être activé ou retiré séparément. Les événements invalides sont refusés. Dans le script, event contient son nom et ... ses arguments. Le démarrage transmet les arguments de ADDON_LOADED. Enregistrez le script avant toute exécution automatique.",
		["customEvents"] = "Événements personnalisés",
		["customize"] = "Personnaliser…",
		["debugBreakpoint"] = "Activer ou désactiver un point d’arrêt (F9)",
		["debugCallbackHelp"] = "Pour déboguer un gestionnaire OnEvent défini dans le code, utilisez :SetScript(\"OnEvent\", ...) ou :HookScript(\"OnEvent\", ...), placez un point d’arrêt dans le rappel et lancez une fois Déboguer le script actuel. Après son inscription, les événements reçus exécutent le rappel dans le débogueur. CreateFrame et _G.CreateFrame fonctionnent tous deux. Jusqu’à 50 événements attendent pendant une pause ; les nouveaux sont ignorés si la file est pleine et les arguments nil sont conservés. À l’arrêt, le gestionnaire SetScript précédent est rétabli si celui du débogueur est toujours installé. Les hooks HookScript ne peuvent pas être retirés et deviennent inactifs à l’arrêt.",
		["debugClearBreakpoints"] = "Effacer les points d’arrêt",
		["debugContinue"] = "Continuer (F5)",
		["debugDrawer"] = "Afficher ou masquer la console de débogage",
		["debugEvents"] = "Déboguer les événements configurés",
		["debugEventsHelp"] = "Le débogage des événements attend les événements personnalisés activés et PLAYER_LOGIN si configuré. Il ne rejoue ni le démarrage ni la connexion. Utilisez Déboguer le script actuel pour tester le code immédiatement.",
		["debugHelp"] = "Cliquez sur un numéro de ligne pour activer ou désactiver un point d’arrêt. Lancez le débogage avec le bouton à côté d’Exécuter, ou choisissez les événements configurés. F5 continue, F10 passe à l’instruction suivante, F11 entre dans les fonctions du script et Shift+F5 arrête. La console peut lire et modifier les variables locales à la ligne en pause. Survolez une variable dans l’éditeur pour l’inspecter. Les nouveaux événements attendent dans une file limitée pendant que WoW continue. Les points d’arrêt sont enregistrés par script entre les rechargements et suivent leurs lignes lors de l’ajout ou de la suppression de texte. Les marqueurs sur des lignes non exécutables restent visibles sans provoquer de pause ; supprimer une ligne entière peut retirer son point d’arrêt.",
		["debugHelperHelp"] = "F10 passe les appels de modules ; F11 entre dans les modules enregistrés chargés par requireHelper. Si l’éditeur correspond au code exécuté, le débogueur utilise l’éditeur normal. Si un brouillon non enregistré diffère, il ouvre une copie en lecture seule et conserve le brouillon. Enregistrez les changements du module avant une nouvelle session.",
		["debugInspectUnavailable"] = "Aucune valeur dans la portée actuelle",
		["debugLimits"] = "Le débogueur utilise des copies du code. Modifier le script actif arrête le débogage ; les points d’arrêt sont conservés et adaptés aux lignes modifiées. Seuls les rappels OnEvent inscrits via :SetScript ou :HookScript sont mis en file. Les appels directs à pcall/xpcall s’exécutent sans pas à pas. Il est impossible d’entrer dans les fonctions natives ; les rappels devant revenir de manière synchrone à une fonction native, comme ceux du tri, ne peuvent pas être suspendus. Les pauses non prises en charge provoquent des erreurs. Les retours instrumentés ne préservent pas l’optimisation des appels terminaux de Lua.",
		["debugNoEvents"] = "Ajoutez d’abord un événement dans les paramètres du script.",
		["debugPaused"] = "Point d’arrêt atteint",
		["debugProbeBindingsError"] = "Liaison de variable de débogage invalide.",
		["debugProbeBindingsHelp"] = "Pour ce test, le troisième argument facultatif de breakpoint() expose de vraies variables locales : { amount = { get = function() return amount end, set = function(value) amount = value end } }. La console lit via get et affecte via set. Sans set, la variable est en lecture seule. Ces liaisons concernent uniquement le point et l’événement actuels ; les événements en attente gardent leurs propres variables. La capture automatique de portée et l’instrumentation ne sont pas encore implémentées.",
		["debugProbeError"] = "Erreur du test de débogage",
		["debugProbeEvaluate"] = "Évaluer",
		["debugProbeFinished"] = "Exécution terminée",
		["debugProbeHelp"] = "/lwdebug EVENT active le code actuel ; /lwdebug fire ajoute un événement de test ; /lwdebug step avance ; /lwdebug stop annule et vide la file. Utilisez breakpoint(\"nom\", {valeur=valeur}) pour capturer des variables. F10 avance au point suivant lorsque ce panneau ou l’éditeur est actif. Jusqu’à 50 événements attendent dans l’ordre. WoW continue ; les tables restent des références actives. Les pas automatiques par ligne, F11, les imports de modules et les points dans pcall/xpcall ne sont pas pris en charge. Les valeurs secrètes sont masquées dans la liste ; les chaînes secrètes peuvent apparaître directement dans l’infobulle.",
		["debugProbeInput"] = "Expression ou code Lua",
		["debugProbeNotPaused"] = "Arrêtez-vous à un point d’arrêt avant d’évaluer du code.",
		["debugProbeOverflow"] = "%d ignorés",
		["debugProbePaused"] = "Point d’arrêt atteint",
		["debugProbeQueue"] = "En attente : %d",
		["debugProbeReadOnly"] = "Cette variable est en lecture seule.",
