		["debugShow"] = "Ir à linha pausada",
		["debugSnapshot"] = "Código executado na depuração",
		["debugSnapshotHelp"] = "Esta visualização somente leitura mostra o código usado pelo depurador. Rascunhos não salvos no editor são preservados.",
