		["debuggerBudgetExceeded"] = "A execução de depuração parou após passos demais.",
		["delete"] = "Excluir",
		["developerToolUnavailable"] = "Não foi possível carregar esta ferramenta de desenvolvimento da Blizzard.",
		["dirtyText"] = "Texto em vez do ponto não salvo",
		["errorDetails"] = "Detalhes do erro",
		["errorHistoryHelp"] = "Guarda até 100 erros recentes de scripts nesta sessão, incluindo execuções automáticas. Erros repetidos são agrupados com contagem e último horário. Recarregar apaga o histórico. Limpar a saída não apaga esta lista.",
		["eventAlreadyAdded"] = "Este evento já está na lista.",
		["eventName"] = "Nome do evento…",
		["eventTraceTool"] = "Mostrar ou ocultar Event Trace (/etrace). Verde: janela aberta.",
		["findCode"] = "Localizar no código",
		["font"] = "Fonte",
		["fontChat"] = "Bate-papo",
