rm.LuaWorkbenchModules.LuaConsole=function(_,addon)
local L = addon.L
addon.Query = addon.Query or {}
local Console = { lines = {}, characters = 0, source = "" }
addon.Query.Console = Console

local function pack(...)
	return { n = select("#", ...), ... }
end

function Console:Format(value, colorSecrets)
 local hidden = colorSecrets and "|cff88ff88<secret>|r" or "<secret>"
	if _G.issecretvalue and _G.issecretvalue(value) then return hidden end
	local ok, text = pcall(tostring, value)
	if not ok then return "<unprintable>" end
	if _G.issecretvalue and _G.issecretvalue(text) then return hidden end
	return (text:sub(1, 4000):gsub("\t", "    "))
end

function Console:SetStatus(text, failed)
 self.statusText, self.statusFailed = text, failed
 if addon.Workspace then addon.Workspace:UpdateStatus() end
end

function Console:OutputLimit()
 local db = addon.Workspace and addon.Workspace.db
 local value = db and tonumber(db.options.outputLimit) or 500
 if not value or value ~= value then value = 500 end
 return math.max(50, math.min(5000, math.floor(value)))
end

function Console:TrimOutput()
 if self.dumpBatch then return end
 local limit = math.max(self:OutputLimit(), self.dumpLineLimit or 0)
 while #self.lines > limit or self.characters > math.max(64000, self.dumpCharacterLimit or 0) do
  self.characters = self.characters - #self.lines[1] - 1
  table.remove(self.lines, 1)
 end
end

function Console:AutoScrollEnabled()
 local db = addon.Workspace and addon.Workspace.db
 return not db or db.options.outputAutoScroll ~= false
end

function Console:SetAutoScroll(enabled)
 addon.Workspace.db.options.outputAutoScroll = enabled == true
 if enabled and self.output then
  local scroll = self.output.scrollFrame
  scroll:UpdateScrollChildRect(); scroll:SetVerticalScroll(scroll:GetVerticalScrollRange())
 end
end

function Console:Refresh()
 self:TrimOutput()
	if self.output then
  self.output.label:SetText(L.queryLuaOutput .. " (" .. self:OutputLimit() .. ")")
  local scroll = self.output.scrollFrame
  local offset = scroll:GetVerticalScroll()
  local follow = self:AutoScrollEnabled()
  self.output:SetText(table.concat(self.lines, "\n"))
  scroll:UpdateScrollChildRect()
  scroll:SetVerticalScroll(follow and scroll:GetVerticalScrollRange() or math.min(offset, scroll:GetVerticalScrollRange()))
 end
end

function Console:Write(...)
	local values = {}
	for i = 1, select("#", ...) do
		values[i] = self:Format(select(i, ...), true)
	end
	local text = table.concat(values, "  "):sub(1, 8000)
 if addon.Diagnostics then addon.Diagnostics:QueueOutput(text) end
	-- Bound both multiline messages and the entire session's retained output.
	for line in (text .. "\n"):gmatch("(.-)\n") do
		self.lines[#self.lines + 1] = line
		self.characters = self.characters + #line + 1
		self:TrimOutput()
	end
	if not self.refreshPending then
		self.refreshPending = true
		C_Timer.After(0, function()
			self.refreshPending = nil
			self:Refresh()
		end)
	end
end

function Console:Clear(undoable)
 self.undoLines = undoable and #self.lines > 0 and self.lines or nil
 self.undoDumpLineLimit, self.undoDumpCharacterLimit = self.dumpLineLimit, self.dumpCharacterLimit
 self.lines, self.characters = {}, 0
 self.dumpLineLimit, self.dumpCharacterLimit = nil, nil
 local workspace = addon.Workspace
 if workspace and workspace.undoOutput then workspace.undoOutput:SetShown(self.undoLines ~= nil) end
 self:Refresh()
 if undoable and self.undoLines then
  self:SetStatus(L.outputCleared)
  local snapshot = self.undoLines
  C_Timer.After(10, function()
   if self.undoLines == snapshot then
    self.undoLines = nil
    if workspace and workspace.undoOutput then workspace.undoOutput:Hide() end
   end
  end)
 end
end

function Console:UndoClear()
 if not self.undoLines then return end
 self.dumpLineLimit = math.max(self.dumpLineLimit or 0, self.undoDumpLineLimit or 0)
 self.dumpCharacterLimit = math.max(self.dumpCharacterLimit or 0, self.undoDumpCharacterLimit or 0)
 local restored = self.undoLines
 self.undoLines = nil
 for _, line in ipairs(self.lines) do restored[#restored + 1] = line end
 self.lines, self.characters = restored, 0
 for _, line in ipairs(restored) do self.characters = self.characters + #line + 1 end
 if addon.Workspace.undoOutput then addon.Workspace.undoOutput:Hide() end
 self:Refresh()
 self:SetStatus(nil)
end

function Console:GetLinePosition(source, cursor)
 local cache = self.linePositionCache
 if not cache or cache.source ~= source then
  cache = {source=source, starts={0}}
  local position = source:find("\n", 1, true)
  while position do
   cache.starts[#cache.starts+1] = position
   position = source:find("\n", position+1, true)
  end
  self.linePositionCache = cache
 end
 local low, high = 1, #cache.starts
 while low < high do
  local middle = math.floor((low+high+1)/2)
  if cache.starts[middle] <= cursor then low=middle else high=middle-1 end
 end
 return low, #cache.starts, cache.starts[low]
end

function Console:UpdateEditorLabel()
	if not self.input then return end
	local line = self.lastError and self.lastError.line
	local position = ""
	if self.input.editBox then
		local cursor = self.input.editBox:GetCursorPosition()
  local current, _, lineStart = self:GetLinePosition(self.source or "", cursor)
  local prefix = (self.source or ""):sub(lineStart+1, cursor)
  local _, characters = prefix:gsub("[^\128-\191]", "")
  position = " - " .. string.format(L["cursorPosition"], current, characters + 1)
	end
 local workspace = addon.Workspace
 local dirty = workspace and workspace.dirty
 local showText = dirty and workspace.db.options.dirtyText
 self.input.label:SetPoint('TOPLEFT', self.input.frame, 'TOPLEFT', 12, -34)
 -- Keep the dirty state alongside the code position, away from the window footer.
	self.input.label:SetText(L["queryLuaCode"] .. (addon.Query.Editor:IsReadOnly(self.input) and (" - " .. L.debugWriteProtected) or "") .. position .. (showText and (" - " .. L.unsaved) or "") .. (line and (" - " .. string.format(L["queryLuaErrorLine"], line)) or ""))
	self.input.label:SetTextColor(1, line and 0.3 or 0.8, line and 0.3 or 0.9)
end

function Console:ShowError()
	if not self.input then return end
	self:UpdateEditorLabel()
	local line = self.lastError and self.lastError.line
	if not line then return end
	local source = self.source or ""
	local start = 1
	for _ = 2, line do
		local newline = source:find("\n", start, true)
		if not newline then break end
		start = newline + 1
	end
	local finish = source:find("\n", start, true) or (#source + 1)
	self.input:SetFocus()
	self.input:SetCursorPosition(start - 1)
	self.input:HighlightText(start - 1, finish - 1)
	local state = self.input.queryLineNumbers
	if state and state.cursorY then
		local scroll = self.input.scrollFrame
		local offset = math.max(0, -state.cursorY - scroll:GetHeight() * 0.25)
		scroll:SetVerticalScroll(math.min(offset, scroll:GetVerticalScrollRange()))
	end
	self:UpdateLineNumbers()
end

function Console:ReportError(value, stack)
	local message = self:Format(value)
 if addon.Diagnostics then
  local workspace = addon.Workspace
  addon.Diagnostics:Record(message, stack, workspace.current, workspace.currentName)
 end
	local location = message:match("LuaWorkbench:(%d+):") or (stack and stack:match("LuaWorkbench:(%d+):"))
	self.lastError = { line = tonumber(location), message = message }
 self:SetStatus(L["queryLuaError"] .. " " .. message, true)
	self:Write(L["queryLuaError"], message)
	if stack then self:Write(stack) end
	self:ShowError()
	local input, source = self.input, self.source
	-- Apply focus after the button's click handling and pending frame layout have finished.
	if input then
		C_Timer.After(0, function()
			if self.input == input and self.source == source and self.lastError then self:ShowError() end
		end)
	end
end

function Console:UpdateLineNumbers()
	local input = self.input
	local state = input and input.queryLineNumbers
	if not state then return end
	local editBox, scroll = input.editBox, input.scrollFrame
	local source = self.source or ""
	local width = editBox:GetWidth()
	local font, size, flags = editBox:GetFont()
	local spacing = editBox:GetSpacing()
	if state.source ~= source or state.width ~= width or state.font ~= font or state.size ~= size or state.flags ~= flags or state.spacing ~= spacing then
		local previousHeights = state.width == width and state.font == font and state.size == size and state.flags == flags and state.spacing == spacing and state.lineHeights or {}
		local heights = {}
		state.lineHeights = heights
		state.source, state.width, state.font, state.size, state.flags, state.spacing = source, width, font, size, flags, spacing
		state.measure:SetFont(font, size, flags)
		state.measure:SetSpacing(spacing)
		state.measure:SetWidth(math.max(1, width))
		state.positions = state.positions or {}
		local offset, sourceStart, line = 0, 1, 0
		for text in (source .. "\n"):gmatch("(.-)\n") do
			local height = heights[text] or previousHeights[text]
			if not height then
				state.measure:SetText(text ~= "" and text or " ")
				height = math.max(size + spacing, state.measure:GetStringHeight())
			end
			heights[text] = height
			line = line + 1
			local position = state.positions[line] or {}
			state.positions[line] = position
			position.offset, position.height = offset, height
			position.sourceStart, position.sourceEnd = sourceStart, sourceStart+#text
			sourceStart=sourceStart+#text+1
			offset = offset + height
		end
		for index = #state.positions, line+1, -1 do state.positions[index] = nil end
	end
	local current = self:GetLinePosition(source, editBox:GetCursorPosition())
	local errorLine = self.lastError and self.lastError.line
	local scrollOffset, viewport = scroll:GetVerticalScroll(), scroll:GetHeight()
	state.measure:SetText(tostring(#state.positions))
	state.numberWidth = state.measure:GetStringWidth()
	local used, visible = 0, {}
 -- Positions are ordered by vertical offset. Cursor and scroll callbacks only
 -- need the visible rows, not a traversal of the entire document.
 local first, high = 1, #state.positions+1
 while first < high do
  local middle = math.floor((first+high)/2)
  local position = state.positions[middle]
  if position.offset+position.height < scrollOffset then first=middle+1 else high=middle end
 end
 for line = first, #state.positions do
  local position = state.positions[line]
  if position.offset >= scrollOffset+viewport then break end
		if position.offset + position.height >= scrollOffset and position.offset < scrollOffset + viewport then
			used = used + 1
			local row = state.rows[used]
			if not row then
				row = state.gutter:CreateFontString(nil, "OVERLAY")
				row:SetJustifyH("RIGHT")
				row:SetJustifyV("TOP")
				state.rows[used] = row
			end
			row:SetFont(font, size, flags)
			row:ClearAllPoints()
			row:SetPoint("TOPLEFT", state.gutter, "TOPLEFT", 0, scrollOffset - position.offset)
			row:SetWidth(state.gutter:GetWidth() - 2)
			row:SetHeight(size + spacing + 2)
			row:SetText(line)
   visible[#visible + 1] = { line = line, y = scrollOffset - position.offset, height = position.height, textHeight = row:GetStringHeight() }
			if line == errorLine then
				row:SetTextColor(1, 0.25, 0.25)
			elseif line == current then
				row:SetTextColor(1, 0.82, 0)
			else
				row:SetTextColor(0.6, 0.6, 0.6)
			end
			row:Show()
		end
	end
	for index = used + 1, #state.rows do state.rows[index]:Hide() end
 if addon.DebugUI then addon.DebugUI:UpdateGutter(state, visible) end
	self:UpdateEditorLabel()
end

function Console:AttachLineNumbers(input)
	local scroll, editBox = input.scrollFrame, input.editBox
	local state = input.queryLineNumberCache or { rows = {} }
	input.queryLineNumberCache = state
	state.scripts, state.scrollPoint, state.source = {}, { scroll:GetPoint(1) }, nil
	state.cursorY = nil
	input.queryLineNumbers = state
	if not state.gutter then
		state.gutter = CreateFrame("Frame", nil, input.scrollBG)
		state.gutter:SetPoint("TOPLEFT", input.scrollBG, "TOPLEFT", 4, -6)
		state.gutter:SetPoint("BOTTOMLEFT", input.scrollBG, "BOTTOMLEFT", 4, 4)
		state.gutter:SetWidth(54)
		state.gutter:SetClipsChildren(true)
		state.measure = state.gutter:CreateFontString(nil, "OVERLAY")
		state.measure:SetWordWrap(true)
		state.measure:SetNonSpaceWrap(true)
		state.measure:Hide()
	end
	state.gutter:Show()
	local function wrap(frame, event)
		local original = frame:GetScript(event)
		state.scripts[#state.scripts + 1] = { frame = frame, event = event, original = original }
		frame:SetScript(event, function(...)
			if event == "OnCursorChanged" then state.cursorY = select(3, ...) end
			if original then original(...) end
			if self.input == input then self:UpdateLineNumbers() end
		end)
	end
	wrap(editBox, "OnCursorChanged")
	wrap(scroll, "OnVerticalScroll")
	wrap(scroll, "OnSizeChanged")
	scroll:SetPoint("TOPLEFT", input.scrollBG, "TOPLEFT", 61, -6)
	self:UpdateLineNumbers()
end

function Console:DetachLineNumbers()
	local input = self.input
	local state = input and input.queryLineNumbers
	if not state then return end
	for _, script in ipairs(state.scripts) do script.frame:SetScript(script.event, script.original) end
	state.gutter:Hide()
	input.scrollFrame:SetPoint(unpack(state.scrollPoint))
	input.queryLineNumbers = nil
end

-- A fresh Blizzard dump context keeps routing local to this invocation.
function Console:Dump(value, startKey, prefix, writer)
 if type(_G.DevTools_CreateDumpContext) ~= "function" or type(_G.DevTools_RunDump) ~= "function" then
  error(L.queryLuaUnavailable, 2)
 end
 local context = _G.DevTools_CreateDumpContext(startKey)
 local hasSecret = _G.issecretvalue and _G.issecretvalue(value)
 context.Write = function(_, text)
  if _G.issecretvalue and _G.issecretvalue(text) then hasSecret = true end
  if writer then writer(text)
  elseif prefix then self:Write(prefix, text) else self:Write(text) end
 end
 -- Dump traversal is synchronous. Restore the shared cutoff even on errors.
 local cutoff = _G.DEVTOOLS_MAX_ENTRY_CUTOFF
 local previousBatch = self.dumpBatch
 local firstLine, firstCharacter = #self.lines, self.characters
 self.dumpBatch = true
 _G.DEVTOOLS_MAX_ENTRY_CUTOFF = 0
 local ok, failure = pcall(_G.DevTools_RunDump, value, context)
 _G.DEVTOOLS_MAX_ENTRY_CUTOFF = cutoff
 self.dumpBatch = previousBatch
 -- Keep enough room for a complete dump until Output is cleared. Ordinary
 -- output still uses a bounded buffer, including after a failed dump.
 self.dumpLineLimit = math.max(self.dumpLineLimit or 0, #self.lines - firstLine)
 self.dumpCharacterLimit = math.max(self.dumpCharacterLimit or 0, self.characters - firstCharacter)
 self:TrimOutput()
 if not ok then error(failure, 0) end
 local db = addon.Workspace and addon.Workspace.db
 if hasSecret and db and db.options.secretDumpChat and type(_G.DevTools_Dump) == "function" then
  -- Use Blizzard's own message dispatch, once for the whole dump, without inspecting secret text.
  _G.DevTools_Dump(value, startKey)
 end
end

function Console:DumpArguments(prefix, ...)
 local count = select('#', ...)
 for index = 1, count do
  local value = select(index, ...)
  self:Dump(value, count > 1 and ('arg[' .. index .. ']') or nil, prefix)
 end
end

function Console:Run(source)
	self.source = source
	self.lastError = nil
	self:ShowError()
	if not source or not source:find("%S") then self:SetStatus(nil); return end
	if not _G.loadstring or not _G.setfenv then
		self:SetStatus(L["queryLuaUnavailable"], true)
		self:Write(L["queryLuaUnavailable"])
		return
	end
	local chunk, compileError = _G.loadstring(source, "=LuaWorkbench")
	if not chunk then
		self:ReportError(compileError)
		return
	end
	-- Keep snippet globals and callback closures for this session without replacing global print.
	if not self.environment then
		self.environment = setmetatable({
			addon = addon,
			editor = addon,
			print = function(...) self:Write(...) end,
			DevTools_Dump = function(value, startKey) self:Dump(value, startKey) end,
		}, { __index = _G })
		self.environment.dump = function(...) self:DumpArguments(nil, ...) end
	end
	self.environment.requireHelper = addon.Helpers:Loader({ print = self.environment.print, dump = self.environment.dump, DevTools_Dump = self.environment.DevTools_Dump })
	_G.setfenv(chunk, self.environment)
	local stackTrace
	local results = pack(xpcall(chunk, function(value)
		if type(_G.debugstack) == "function" then
			local ok, stack = pcall(_G.debugstack, 2, 20, 20)
			if ok then stackTrace = self:Format(stack) end
		end
		return value
	end))
	if not results[1] then
		self:ReportError(results[2], stackTrace)
	else
		if results.n > 1 then self:Write("return", unpack(results, 2, results.n)) end
		self:SetStatus(L["queryLuaComplete"], false)
	end
end

end
rm.LuaWorkbenchModules.UI=function(_,addon)
local UI = {}
addon.UI = UI
UI.colors = { background = { 0.055, 0.065, 0.085, 1 }, panel = { 0.085, 0.095, 0.12, 1 }, hover = { 0.16, 0.19, 0.24, 1 }, accent = { 0.22, 0.56, 0.96, 1 } }

function UI:PrimaryModifier()
 if _G.IsMacClient and _G.IsMacClient() then return _G.IsMetaKeyDown and _G.IsMetaKeyDown() or false end
 return _G.IsControlKeyDown and _G.IsControlKeyDown() or false
end

function UI:InCombat()
 return _G.InCombatLockdown and _G.InCombatLockdown() or false
end

function UI:KeyboardPropagation(frame, propagate, initialize)
 if self:InCombat() then
  self.keyboardPending = self.keyboardPending or {}
  self.keyboardPending[frame] = initialize or self.keyboardPending[frame] or false
  if not self.keyboardRecovery then
   self.keyboardRecovery = CreateFrame('Frame')
   self.keyboardRecovery:SetScript('OnEvent', function()
    if self:InCombat() then return end
    self.keyboardRecovery:UnregisterEvent('PLAYER_REGEN_ENABLED')
    local pending = self.keyboardPending
    self.keyboardPending = {}
    for owner, enable in pairs(pending) do self:KeyboardPropagation(owner, true, enable) end
   end)
  end
  self.keyboardRecovery:RegisterEvent('PLAYER_REGEN_ENABLED')
  return false
 end
 if initialize then frame:EnableKeyboard(true) end
 frame:SetPropagateKeyboardInput(propagate)
 return true
end

function UI:Background(frame, color)
 local texture = frame:CreateTexture(nil, "BACKGROUND")
 texture:SetAllPoints()
 texture:SetColorTexture(unpack(color or self.colors.panel))
 return texture
end

function UI:Text(parent, text, size)
 local label = parent:CreateFontString(nil, "OVERLAY")
 label:SetFontObject(GameFontHighlightSmall)
 if size then local font, _, flags = label:GetFont(); label:SetFont(font, size, flags) end
 label:SetJustifyH("LEFT")
 label:SetText(text)
 label:SetTextColor(0.78, 0.82, 0.9)
 return label
end

function UI:Tooltip(frame, text)
 frame:SetScript("OnEnter", function()
  GameTooltip:SetOwner(frame, "ANCHOR_RIGHT")
  GameTooltip:ClearLines()
  GameTooltip:AddLine(text, 0.85, 0.9, 1, true)
  GameTooltip:Show()
 end)
 frame:SetScript("OnLeave", function() GameTooltip:Hide() end)
end

function UI:SearchClear(box, refresh)
 if box.clearButton then return box.clearButton end
 local left, right, top, bottom = box:GetTextInsets()
 box:SetTextInsets(left, math.max(right, 28), top, bottom)
 local button = self:Button(box, 'close', addon.L.clearSearch, function()
  box:SetText('')
  if refresh then refresh() end
  box:SetFocus()
 end)
 box.clearButton = button
 button:SetSize(24, 24); button:SetPoint('RIGHT', -2, 0)
 local function update() button:SetShown(box:GetText() ~= '') end
 box:HookScript('OnTextChanged', update)
 update()
 return button
end

function UI:Button(parent, icon, tooltip, callback, color, borderHover)
 local button = CreateFrame("Button", nil, parent)
 button:SetSize(30, 28)
 local highlight
 if borderHover then
  highlight = CreateFrame("Frame", nil, button)
  highlight:SetAllPoints()
  for _, edge in ipairs({ "TOP", "BOTTOM", "LEFT", "RIGHT" }) do
   local stroke = highlight:CreateTexture(nil, "ARTWORK")
   stroke:SetColorTexture(0.76, 0.81, 0.9, 1)
   if edge == "TOP" or edge == "BOTTOM" then
    stroke:SetHeight(1)
    stroke:SetPoint(edge .. "LEFT"); stroke:SetPoint(edge .. "RIGHT")
   else
    stroke:SetWidth(1)
    stroke:SetPoint("TOP" .. edge); stroke:SetPoint("BOTTOM" .. edge)
   end
  end
 else
  highlight = button:CreateTexture(nil, "BACKGROUND", nil, 1)
  highlight:SetAllPoints()
  highlight:SetColorTexture(unpack(self.colors.hover))
 end
 highlight:Hide()
 button.iconStrokes = {}
 local function line(x1, y1, x2, y2)
  -- Axis-aligned strokes need a nonzero rectangular area on every client.
  if x1 == x2 or y1 == y2 then
   local stroke = button:CreateTexture(nil, "ARTWORK")
   stroke:SetColorTexture(unpack(color or { 0.76, 0.81, 0.9, 1 }))
   button.iconStrokes[#button.iconStrokes + 1] = stroke
   stroke:SetSize(math.max(1.5, math.abs(x2 - x1)), math.max(1.5, math.abs(y2 - y1)))
   stroke:SetPoint("CENTER", button, "CENTER", (x1 + x2) / 2, (y1 + y2) / 2)
   return
  end
  local stroke = button:CreateLine(nil, "ARTWORK")
  button.iconStrokes[#button.iconStrokes + 1] = stroke
  stroke:SetThickness(1.5)
  stroke:SetColorTexture(unpack(color or { 0.76, 0.81, 0.9, 1 }))
  stroke:SetStartPoint("CENTER", button, x1, y1)
  stroke:SetEndPoint("CENTER", button, x2, y2)
 end
 if icon == "search" or icon == "options" then
  local texture = button:CreateTexture(nil, "ARTWORK")
  texture:SetSize(18, 18); texture:SetPoint("CENTER")
  texture:SetTexture(icon == "search" and "Interface\\Common\\UI-Searchbox-Icon" or "Interface\\Buttons\\UI-OptionsButton")
  if icon == "options" then texture:SetDesaturated(true); texture:SetVertexColor(0.78, 0.82, 0.9, 1) end
 elseif icon == "frameStack" or icon == "inspector" then
  line(-7, 3, 3, 3); line(3, 3, 3, -7); line(3, -7, -7, -7); line(-7, -7, -7, 3)
  line(-3, 7, 7, 7); line(7, 7, 7, -3); line(5, -3, 7, -3)
 elseif icon == "refresh" then
  line(5, 4, 1, 7); line(1, 7, -5, 5); line(-5, 5, -7, 0)
  line(-7, 0, -4, -6); line(-4, -6, 3, -6); line(3, -6, 7, -2)
  line(5, 8, 5, 3); line(5, 3, 0, 3)
 elseif icon == "tableInspect" then
  line(-7, 7, 7, 7); line(7, 7, 7, -7); line(7, -7, -7, -7); line(-7, -7, -7, 7)
  line(-7, 2, 7, 2); line(-7, -3, 7, -3); line(-2, 7, -2, -7)
 elseif icon == "eventTrace" then
  line(-8, 0, -4, 0); line(-4, 0, -1, 6); line(-1, 6, 2, -6); line(2, -6, 5, 0); line(5, 0, 8, 0)
 elseif icon == "debug" then
  line(-4, 5, 4, 5); line(-4, 5, -4, -5); line(4, 5, 4, -5); line(-4, -5, 4, -5)
  line(0, 4, 0, -4); line(-2, 7, 2, 7)
  line(-6, 8, -3, 5); line(6, 8, 3, 5)
  for _, y in ipairs({ 3, 0, -3 }) do line(-8, y, -4, y); line(4, y, 8, y) end
 elseif icon == "stepInto" then
  line(0, 8, 0, -3); line(-4, 1, 0, -3); line(0, -3, 4, 1); line(-5, -7, 5, -7)
 elseif icon == "windowOptions" then
  line(-8, 7, 6, 7); line(-8, 7, -8, -6); line(-8, -6, -2, -6)
  line(-8, 3, 6, 3); line(6, 7, 6, 1)
  local gear = button:CreateTexture(nil, "ARTWORK")
  gear:SetTexture("Interface\\Buttons\\UI-OptionsButton")
  gear:SetSize(14, 14); gear:SetPoint("CENTER", 4, -4)
  gear:SetDesaturated(true); gear:SetVertexColor(0.78, 0.82, 0.9, 1)
 elseif icon == "fragment" then
  line(-7, 8, 4, 8); line(4, 8, 7, 5); line(7, 5, 7, -8)
  line(7, -8, -7, -8); line(-7, -8, -7, 8)
  line(-3, 3, -5, 0); line(-5, 0, -3, -3)
  line(3, 3, 5, 0); line(5, 0, 3, -3)
 elseif icon == "folder" then
  line(-7, 4, -2, 4); line(-2, 4, 0, 2); line(0, 2, 7, 2)
  line(7, 2, 7, -6); line(7, -6, -7, -6); line(-7, -6, -7, 4)
 elseif icon == "automatic" then
  -- Two opposing arrows built from opaque rectangles, without line primitives.
  line(-5, 4, 4, 4); line(-5, 0, -5, 4)
  line(-4, -4, 5, -4); line(5, -4, 5, 0)
  for step = 0, 3 do
   local upper = button:CreateTexture(nil, "ARTWORK")
   upper:SetColorTexture(unpack(color or { 0.76, 0.81, 0.9, 1 }))
   upper:SetSize(1, 1 + step * 2); upper:SetPoint("CENTER", button, "CENTER", 6 - step, 4)
   local lower = button:CreateTexture(nil, "ARTWORK")
   lower:SetColorTexture(unpack(color or { 0.76, 0.81, 0.9, 1 }))
   lower:SetSize(1, 1 + step * 2); lower:SetPoint("CENTER", button, "CENTER", -6 + step, -4)
  end
 elseif icon == "play" then
  line(-4, 6, 6, 0); line(6, 0, -4, -6); line(-4, -6, -4, 6)
 elseif icon == "stop" then
  line(-5, 5, 5, 5); line(5, 5, 5, -5); line(5, -5, -5, -5); line(-5, -5, -5, 5)
 elseif icon == "clear" then
  line(-6, 4, 6, 4); line(-3, 7, 3, 7); line(-4, 2, -3, -6); line(-3, -6, 3, -6); line(3, -6, 4, 2)
 elseif icon == "expand" then
  line(-6, 2, -6, 6); line(-6, 6, -2, 6); line(2, 6, 6, 6); line(6, 6, 6, 2)
  line(-6, -2, -6, -6); line(-6, -6, -2, -6); line(2, -6, 6, -6); line(6, -6, 6, -2)
 elseif icon == "minimize" then
  line(-5, -3, 5, -3)
 elseif icon == "copy" then
  line(-2, 3, 6, 3); line(6, 3, 6, -6); line(6, -6, -2, -6); line(-2, -6, -2, 3)
  line(-6, -2, -6, 7); line(-6, 7, 2, 7); line(2, 7, 2, 5)
 elseif icon == "search" or icon == "minimap" then
  local radius = icon == "search" and 4 or 6
  for index = 0, 11 do
   local a, b = index * math.pi / 6, (index + 1) * math.pi / 6
   line(math.cos(a) * radius - 1, math.sin(a) * radius + 1, math.cos(b) * radius - 1, math.sin(b) * radius + 1)
  end
  if icon == "search" then line(2, -2, 7, -7)
  else line(-1, 5, -3, -1); line(-3, -1, 2, 1); line(2, 1, -1, 5) end
 elseif icon == "previous" then
  line(3, 5, -2, 0); line(-2, 0, 3, -5)
 elseif icon == "next" then
  line(-3, 5, 2, 0); line(2, 0, -3, -5)
 elseif icon == "close" then
  line(-4, 4, 4, -4); line(-4, -4, 4, 4)
 elseif icon == "new" then
  line(-5, 0, 5, 0); line(0, -5, 0, 5)
 elseif icon == "saveAll" then
  line(-3, 8, 7, 8); line(7, 8, 7, -3); line(5, -3, 7, -3)
  line(-3, 6, -3, 8); line(0, 8, 0, 5); line(0, 5, 4, 5); line(4, 5, 4, 8)
  line(-7, 3, 3, 3); line(3, 3, 3, -8); line(3, -8, -7, -8); line(-7, -8, -7, 3)
  line(-4, 3, -4, -1); line(-4, -1, 0, -1); line(0, -1, 0, 3)
 elseif icon == "save" then
  line(-6, 6, 4, 6); line(4, 6, 6, 4); line(6, 4, 6, -6); line(6, -6, -6, -6); line(-6, -6, -6, 6)
  line(-3, 6, -3, 1); line(-3, 1, 3, 1); line(3, 1, 3, 6)
 else
  local label = self:Text(button, icon, 12); label:SetPoint("CENTER")
 end
 self:Tooltip(button, tooltip)
 button:HookScript("OnEnter", function() highlight:Show() end)
 button:HookScript("OnLeave", function() highlight:Hide() end)
 button:HookScript("OnHide", function() highlight:Hide() end)
 button:SetScript("OnClick", function() GameTooltip:Hide(); callback() end)
 return button
end

function UI:ButtonColor(button, color)
 for _, stroke in ipairs(button.iconStrokes or {}) do stroke:SetColorTexture(unpack(color)) end
end

function UI:Scroll(parent)
 local scroll = CreateFrame("ScrollFrame", nil, parent)
 local bar = CreateFrame("Slider", nil, parent)
 bar:SetWidth(7)
 bar:SetPoint("TOPRIGHT", scroll, "TOPRIGHT", 10, 0)
 bar:SetPoint("BOTTOMRIGHT", scroll, "BOTTOMRIGHT", 10, 0)
 bar:SetOrientation("VERTICAL")
 bar:SetMinMaxValues(0, 0)
 bar:SetValueStep(18)
 bar:SetObeyStepOnDrag(false)
 self:Background(bar, { 0.08, 0.09, 0.11, 1 })
 bar:SetThumbTexture("Interface\\Buttons\\WHITE8x8")
 bar:GetThumbTexture():SetVertexColor(0.3, 0.35, 0.43, 1)
 bar:GetThumbTexture():SetSize(7, 35)
 bar:SetScript("OnValueChanged", function(_, value) scroll:SetVerticalScroll(value) end)
 scroll:EnableMouseWheel(true)
 scroll:SetScript("OnMouseWheel", function(_, delta)
  bar:SetValue(math.max(0, math.min(scroll:GetVerticalScrollRange(), scroll:GetVerticalScroll() - delta * 48)))
 end)
 scroll:SetScript("OnScrollRangeChanged", function(_, _, range)
  bar:SetMinMaxValues(0, range)
  local offset = math.max(0, math.min(range, scroll:GetVerticalScroll()))
  bar:SetValue(offset)
  -- A clamped slider may already have this value and emit no value change.
  scroll:SetVerticalScroll(offset)
  bar:SetShown(range > 0)
 end)
 scroll:SetScript("OnVerticalScroll", function(_, value)
  if bar:GetValue() ~= value then bar:SetValue(value) end
 end)
 scroll.bar = bar
 return scroll
end

function UI:Editor(parent, labelText, readonly)
 local panel = CreateFrame("Frame", nil, parent)
 self:Background(panel, self.colors.background)
 local label = self:Text(panel, labelText, 11)
 label:SetPoint("TOPLEFT", 12, -10)
 label:SetPoint("TOPRIGHT", panel, "TOPRIGHT", -85, -10)
 label:SetHeight(14)
 local scrollBG = CreateFrame("Frame", nil, panel)
 scrollBG:SetPoint("TOPLEFT", 6, -34)
 scrollBG:SetPoint("BOTTOMRIGHT", -16, 8)
 local scroll = self:Scroll(scrollBG)
 scroll:SetPoint("TOPLEFT", scrollBG, "TOPLEFT", 6, -6)
 scroll:SetPoint("BOTTOMRIGHT", scrollBG, "BOTTOMRIGHT", -4, 4)
 local box = CreateFrame("EditBox", nil, scroll)
 box:SetMultiLine(true)
 box:SetAutoFocus(false)
 box:SetFontObject(ChatFontNormal)
 box:SetSpacing(2)
 box:SetTextInsets(0, 0, 0, 0)
 box:SetMaxLetters(0)
 box:SetCountInvisibleLetters(true)
 box:SetTextColor(0.8, 0.84, 0.92)
 box:SetHeight(1)
 scroll:SetScrollChild(box)
 local input = { frame = panel, editBox = box, scrollFrame = scroll, scrollBG = scrollBG, label = label, readonly = readonly }
 function input:GetText()
  if addon.BufferedPaste then addon.BufferedPaste:Finish(self.editBox) end
  return self.editBox:GetText()
 end
 function input:SetText(text)
  if addon.BufferedPaste then addon.BufferedPaste:Finish(self.editBox) end
  self.rawText = text
  self.setting = true
  self.editBox:SetText(text)
  self.editBox:SetCursorPosition(0)
  self.setting = nil
 end
 function input:SetFocus() self.editBox:SetFocus() end
 function input:ClearFocus() self.editBox:ClearFocus() end
 function input:SetCursorPosition(position) self.editBox:SetCursorPosition(position) end
 function input:HighlightText(...) self.editBox:HighlightText(...) end
 scroll:SetScript("OnSizeChanged", function(_, width) box:SetWidth(math.max(1, width)) end)
 scroll:EnableMouse(true)
 scroll:SetScript("OnMouseDown", function(_, button)
  if button == "LeftButton" then box:SetFocus(); box:SetCursorPosition(#box:GetText()) end
 end)
 local function codeMenu(_, button)
  if button == 'RightButton' and input.queryEditor and not readonly and addon.Snippets then addon.Snippets:OpenCodeMenu(input) end
 end
 box:SetScript('OnMouseUp', codeMenu)
 scroll:SetScript('OnMouseUp', codeMenu)
 box:SetScript("OnEditFocusLost", function() box:HighlightText(0, 0) end)
 box:SetScript("OnCursorChanged", function(frame, x, y, _, height)
  -- Layout/scroll notifications can repeat without moving the text cursor.
  -- Only an actual caret move should override a manually chosen viewport.
  local position = frame:GetCursorPosition()
  if input.cursorPosition == position and input.cursorX == x and input.cursorY == y then return end
  input.cursorPosition, input.cursorX, input.cursorY = position, x, y
  local offset = scroll:GetVerticalScroll()
  if -y < offset then scroll:SetVerticalScroll(math.max(0, -y))
  elseif -y + height > offset + scroll:GetHeight() then
   scroll:SetVerticalScroll(math.min(scroll:GetVerticalScrollRange(), -y + height - scroll:GetHeight()))
  end
 end)
 box:SetScript("OnEscapePressed", function() box:ClearFocus() end)
 box:SetScript("OnTextChanged", function(_, user)
  if input.setting then return end
  if readonly then
   if user then input:SetText(input.rawText or "") end
  elseif input.changed then input.changed(box:GetText()) end
 end)
 return input
end

function UI:Dot(parent, size)
 local dot = parent:CreateTexture(nil, "OVERLAY")
 dot:SetSize(size or 7, size or 7)
 dot:SetColorTexture(0.82, 0.85, 0.9, 1)
 local mask = parent:CreateMaskTexture(nil, "OVERLAY")
 mask:SetAllPoints(dot)
 mask:SetTexture("Interface\\CharacterFrame\\TempPortraitAlphaMask", "CLAMPTOBLACKADDITIVE", "CLAMPTOBLACKADDITIVE")
 dot:AddMaskTexture(mask)
 return dot
end

function UI:FolderMarker(parent)
 local frame = CreateFrame('Frame', nil, parent)
 frame:SetSize(32, 24); frame:SetPoint('TOPLEFT', 0, 0)
 local function rectangle(x, y, width, height)
  local texture = frame:CreateTexture(nil, 'ARTWORK')
  texture:SetColorTexture(0.68, 0.76, 0.87, 1)
  texture:SetSize(width, height); texture:SetPoint('TOPLEFT', x, -y)
  return texture
 end
 -- Folder outline and tab, independent of glyph availability.
 rectangle(18, 8, 5, 1); rectangle(18, 8, 1, 10)
 rectangle(22, 9, 8, 1); rectangle(29, 9, 1, 9); rectangle(18, 17, 12, 1)
 frame.right, frame.down = {}, {}
 for i = 0, 3 do
  frame.right[#frame.right + 1] = rectangle(8 + i, 9 + i, 1, 2)
  frame.right[#frame.right + 1] = rectangle(8 + i, 15 - i, 1, 2)
  frame.down[#frame.down + 1] = rectangle(7 + i, 11 + i, 2, 1)
  frame.down[#frame.down + 1] = rectangle(13 - i, 11 + i, 2, 1)
 end
 function frame:SetExpanded(expanded)
  for _, texture in ipairs(self.right) do texture:SetShown(not expanded) end
  for _, texture in ipairs(self.down) do texture:SetShown(expanded) end
 end
 return frame
end

function UI:Border(frame, color)
 for _, edge in ipairs({ 'TOP', 'BOTTOM', 'LEFT', 'RIGHT' }) do
  local line = frame:CreateTexture(nil, 'BORDER')
  line:SetColorTexture(unpack(color))
  if edge == 'TOP' or edge == 'BOTTOM' then
   line:SetHeight(1); line:SetPoint(edge .. 'LEFT'); line:SetPoint(edge .. 'RIGHT')
  else
   line:SetWidth(1); line:SetPoint('TOP' .. edge); line:SetPoint('BOTTOM' .. edge)
  end
 end
end

function UI:Check(parent, text, callback)
 local button = CreateFrame('CheckButton', nil, parent)
 button:SetSize(370, 24)
 local square = button:CreateTexture(nil, 'BACKGROUND'); square:SetSize(16, 16); square:SetPoint('LEFT')
 square:SetColorTexture(0.2, 0.25, 0.32, 1)
 local check = button:CreateTexture(nil, 'ARTWORK')
 check:SetTexture('Interface\\Buttons\\UI-CheckBox-Check'); check:SetSize(20, 20); check:SetPoint('CENTER', square, 'CENTER'); check:SetDesaturated(true)
 button:SetCheckedTexture(check)
 button.label = self:Text(button, text, 11)
 button.label:SetPoint('LEFT', 24, 0); button.label:SetPoint('RIGHT', -4, 0); button.label:SetWordWrap(false)
 local hover = button:CreateTexture(nil, 'HIGHLIGHT'); hover:SetAllPoints(square); hover:SetColorTexture(1, 1, 1, 0.12)
 button:SetScript('OnClick', callback)
 return button
end

function UI:Action(parent, icon, text, tooltip, callback)
 local button = self:Button(parent, '', tooltip, callback, nil, true)
 button.label = self:Text(button, text, 11); button.label:SetPoint('LEFT', 29, 0)
 button:SetWidth(40 + button.label:GetStringWidth())
 local symbol = self:Button(button, icon, tooltip, callback)
 symbol:SetPoint('LEFT'); symbol:SetSize(26, 26); symbol:EnableMouse(false)
 return button
end

-- Keep auxiliary panels anchored to the screen while retaining editor visibility.
function UI:MovablePanel(panel, key)
 panel:SetMovable(true)
 panel:SetClampedToScreen(true)
 local function scale() return panel:GetEffectiveScale() / UIParent:GetEffectiveScale() end
 local function restore()
  local saved = addon.Workspace.db.panelPositions and addon.Workspace.db.panelPositions[key]
  local ratio = scale()
  local x, y = panel:GetCenter()
  x = x and x * ratio - UIParent:GetWidth() / 2 or 0
  y = y and y * ratio - UIParent:GetHeight() / 2 or 0
  if saved then x, y = saved.x, saved.y end
  local width, height = panel:GetSize()
  panel:ClearAllPoints()
  panel:SetSize(width, height)
  panel:SetPoint('CENTER', UIParent, 'CENTER', x / ratio, y / ratio)
 end
 local function stop()
  if not panel.dragging then return end
  panel.dragging = nil
  panel:StopMovingOrSizing()
  local x, y = panel:GetCenter()
  if not x or not y then return end
  local db, ratio = addon.Workspace.db, scale()
  db.panelPositions = db.panelPositions or {}
  db.panelPositions[key] = { x = x * ratio - UIParent:GetWidth() / 2, y = y * ratio - UIParent:GetHeight() / 2 }
  restore()
 end
 local handle = CreateFrame('Frame', nil, panel)
 handle:SetPoint('TOPLEFT'); handle:SetPoint('TOPRIGHT', -42, 0); handle:SetHeight(34)
 handle:EnableMouse(true); handle:RegisterForDrag('LeftButton')
 handle:SetScript('OnDragStart', function() panel.dragging = true; panel:StartMoving() end)
 handle:SetScript('OnDragStop', stop)
 panel:HookScript('OnHide', stop)
 panel:HookScript('OnShow', restore)
 panel.RestorePanelPosition = restore
 panel.dragHandle = handle
end

end
rm.LuaWorkbenchModules.Search=function(_,addon)
local Search = {}
addon.Search = Search

-- Plain-text matching: code punctuation is never interpreted as a pattern.
function Search:Matches(source, query, matchCase, wholeWord)
 source = source:gsub('\r\n', '\n'):gsub('\r', '\n')
 local matches = {}
 if query == '' then return matches end
 local text, needle = source, query
 if not matchCase then text, needle = text:lower(), needle:lower() end
 local offset = 1
 while offset <= #text do
  local first, last = text:find(needle, offset, true)
  if not first then break end
  local before, after = source:sub(first - 1, first - 1), source:sub(last + 1, last + 1)
  if not wholeWord or (not before:match('[%w_]') and not after:match('[%w_]')) then
   matches[#matches + 1] = { first = first, last = last }
  end
  offset = last + 1
 end
 return matches
end

function Search:SnippetRows(db, query)
 local rows, seen = {}, {}
 for _, collection in ipairs({ db.drafts, db.snippets }) do
  for id, snippet in pairs(collection) do
   if not seen[id] then
    seen[id] = true
    local matches = self:Matches(snippet.source, query, false, false)
    local named = query == '' or snippet.name:lower():find(query:lower(), 1, true)
    if named or #matches > 0 then
     rows[#rows + 1] = { id = id, name = snippet.name, matches = matches }
    end
   end
  end
 end
 table.sort(rows, function(a, b)
  if a.name == b.name then return tonumber(a.id) < tonumber(b.id) end
  return a.name:lower() < b.name:lower() or (a.name:lower() == b.name:lower() and a.id < b.id)
 end)
 return rows
end

end
rm.LuaWorkbenchModules.Organization=function(_,addon)
local W, UI, L = addon.Workspace, addon.UI, addon.L

function W:TreeRows()
 local snippets = addon.Search:SnippetRows(self.db, self.snippetSearch:GetText())
 local query = self.snippetSearch:GetText()
 local rows, folders = {}, {}
 for id, folder in pairs(self.db.folders) do folders[#folders + 1] = { id = id, name = folder.name, folder = true, matches = {} } end
 table.sort(folders, function(a, b) if a.name == b.name then return a.id < b.id end; return a.name < b.name end)
 for _, folder in ipairs(folders) do
  local children = {}
  for _, snippet in ipairs(snippets) do
   if self.db.folderBySnippet[snippet.id] == folder.id then snippet.indent = true; children[#children + 1] = snippet end
  end
  if query == '' or #children > 0 or folder.name:lower():find(query:lower(), 1, true) then
   folder.expanded = query ~= '' or not self.db.folders[folder.id].collapsed
   folder.hasChildren = #children > 0
   rows[#rows + 1] = folder
   if folder.expanded then for _, child in ipairs(children) do rows[#rows + 1] = child end end
  end
 end
 for _, snippet in ipairs(snippets) do
  if not self.db.folders[self.db.folderBySnippet[snippet.id]] then rows[#rows + 1] = snippet end
 end
 return rows
end

function W:NewFolder()
 self:EndRename(false)
 self.db.folderSerial = (self.db.folderSerial or 0) + 1
 local id = 'folder' .. self.db.folderSerial
 self.db.folders[id] = { name = L.newFolder .. ' ' .. self.db.folderSerial }
 self.selectedFolder = id
 self.snippetSearch:SetText('')
 self:RefreshTree()
 self:BeginRename(id)
 return id
end

function W:MoveSnippet(id, folder)
 self:Capture()
 self.db.folderBySnippet[id] = folder
 if folder then self.db.folders[folder].collapsed = nil end
 self:RefreshTree()
end

function W:RemoveFolder(id)
 for snippet, folder in pairs(self.db.folderBySnippet) do if folder == id then self.db.folderBySnippet[snippet] = nil end end
 self.db.folders[id] = nil
 if self.selectedFolder == id then self.selectedFolder = nil end
 self:RefreshTree()
end

function W:OpenMenu(owner, entries)
 if not self.contextMenu then
  local menu = CreateFrame('Frame', nil, self.window)
  self.contextMenu = menu
  menu:SetFrameStrata('TOOLTIP'); menu:SetClampedToScreen(true); menu:EnableMouse(true)
  UI:Background(menu, { 0.12, 0.14, 0.18, 1 })
  menu.scroll = UI:Scroll(menu)
  menu.scroll:SetPoint('TOPLEFT', 4, -4); menu.scroll:SetPoint('BOTTOMRIGHT', -15, 4)
  menu.content = CreateFrame('Frame', nil, menu.scroll); menu.content:SetWidth(220)
  menu.scroll:SetScrollChild(menu.content)
  function menu:RefreshScrollRange()
   local range = math.max(0, self.content:GetHeight() - (self:GetHeight() - 8))
   self.scrollRange = range
   self.scroll.bar:SetMinMaxValues(0, range)
   self.scroll.bar:SetValue(math.min(range, self.scroll:GetVerticalScroll()))
   self.scroll.bar:SetShown(range > 0)
  end
  menu.scroll:SetScript('OnScrollRangeChanged', function() menu:RefreshScrollRange() end)
  menu.scroll:SetScript('OnMouseWheel', function(_, delta)
   menu.scroll.bar:SetValue(math.max(0, math.min(menu.scrollRange or 0, menu.scroll:GetVerticalScroll() - delta * 48)))
  end)
  menu.measure = UI:Text(menu, '', 12)
  menu.measure:SetWordWrap(false); menu.measure:Hide()
  menu.buttons = {}
  menu:SetScript('OnUpdate', function()
   local down = IsMouseButtonDown()
   if menu.waitForMouseRelease then
    if not down then menu.waitForMouseRelease = nil end
    return
   end
   if down and not menu:IsMouseOver() then menu:Hide() end
  end)
 end
 local menu = self.contextMenu
 menu.waitForMouseRelease = IsMouseButtonDown()
 local width, measured = 242, {}
 for index, entry in ipairs(entries) do
  menu.measure:SetText(entry.text:gsub('|', '||'))
  measured[index] = menu.measure:GetStringWidth()
  width = math.max(width, math.ceil(measured[index]) + 38)
 end
 local screenWidth = UIParent:GetWidth() * UIParent:GetEffectiveScale() / menu:GetEffectiveScale()
 width = math.min(width, math.max(80, math.min(600, screenWidth - 24)))
 menu:SetSize(width, math.min(320, #entries * 28 + 8))
 menu.content:SetWidth(width - 22)
 menu.content:SetHeight(#entries * 28)
 for index, entry in ipairs(entries) do
  local button = menu.buttons[index]
  if not button then
   button = CreateFrame('Button', nil, menu.content); button:SetSize(220, 26)
   button.text = UI:Text(button, '', 12); button.text:SetPoint('LEFT', 8, 0); button.text:SetWidth(204); button.text:SetWordWrap(false)
   button.selected = UI:Background(button, { 0.12, 0.28, 0.46, 1 })
   button.selected:Hide()
   button.marker = button:CreateTexture(nil, 'ARTWORK')
   button.marker:SetColorTexture(0.4, 0.86, 1, 1)
   button.marker:SetPoint('TOPLEFT'); button.marker:SetPoint('BOTTOMLEFT'); button.marker:SetWidth(3)
   button.marker:Hide()
   local hover = button:CreateTexture(nil, 'HIGHLIGHT'); hover:SetAllPoints(); hover:SetColorTexture(1, 1, 1, 0.08); hover:Hide()
   button:SetScript('OnEnter', function()
    hover:Show()
    if button.tooltipText then
     GameTooltip:SetOwner(button, 'ANCHOR_RIGHT'); GameTooltip:ClearLines()
     GameTooltip:AddLine(button.tooltipText, 0.85, 0.9, 1, true); GameTooltip:Show()
    end
   end)
   local function leave()
    hover:Hide()
    if GameTooltip:IsOwned(button) then GameTooltip:Hide() end
   end
   button:SetScript('OnLeave', leave); button:SetScript('OnHide', leave)
   button:SetScript('OnClick', function() menu:Hide(); button.action() end)
   menu.buttons[index] = button
  end
  button:SetWidth(width - 22); button.text:SetWidth(width - 38)
  button.tooltipText = measured[index] > width - 38 and entry.text:gsub('|', '||') or nil
  button.action = entry.action
  button.selected:SetShown(entry.selected == true)
  button.marker:SetShown(entry.selected == true)
  button.text:SetTextColor(entry.selected and 0.9 or 0.78, entry.selected and 0.95 or 0.82, entry.selected and 1 or 0.9)
  button.text:SetText((entry.text:gsub('|', '||')))
  button:SetPoint('TOPLEFT', 0, -(index - 1) * 28); button:Show()
 end
 for index = #entries + 1, #menu.buttons do menu.buttons[index]:Hide() end
 menu.rename = menu.buttons[1]
 menu:ClearAllPoints(); menu:SetPoint('TOPLEFT', owner, 'TOPRIGHT', 3, 0)
 menu.scroll:SetVerticalScroll(0); menu:Show()
 menu.scroll:UpdateScrollChildRect()
 menu:RefreshScrollRange()
end

function W:ShowSnippetMenu(button)
 self:EndRename(false)
 local id = button.row.id
 local entries = { { text = L.rename, action = function() self:BeginRename(id) end } }
 if button.row.folder then
  entries[#entries + 1] = { text = L.newSnippet, action = function() self.selectedFolder = id; self:New() end }
  entries[#entries + 1] = { text = L.removeFolder, action = function() self:RemoveFolder(id) end }
 else
  if self.db.snippets[id] and self:IsSnippetDirty(id) then
   entries[#entries + 1] = { text = L.revertSaved, action = function() StaticPopup_Show('LUAWORKBENCH_REVERT', nil, nil, id) end }
  end
  local destinations, folders = {}, {}
  local currentFolder = self.db.folderBySnippet[id]
  if currentFolder then destinations[#destinations + 1] = { text = L.rootFolder, action = function() self:MoveSnippet(id, nil) end } end
  for folderID, folder in pairs(self.db.folders) do
   if folderID ~= currentFolder then folders[#folders + 1] = { id = folderID, name = folder.name } end
  end
  table.sort(folders, function(a, b) return a.name < b.name end)
  for _, folder in ipairs(folders) do
   local target = folder.id
   destinations[#destinations + 1] = { text = folder.name, action = function() self:MoveSnippet(id, target) end }
  end
  if #destinations > 0 then
   entries[#entries + 1] = { text = L.moveTo, action = function() self:OpenMenu(button, destinations) end }
  end
  entries[#entries + 1] = { text = L.delete, action = function() self:Select(id); StaticPopup_Show('LUAWORKBENCH_DELETE', nil, nil, id) end }
 end
 self:OpenMenu(button, entries)
end

function W:DiscardSessionDrafts()
 for id in pairs(self.db.drafts) do
  if not self.db.snippets[id] then
   self.db.folderBySnippet[id], self.db.clearOnRun[id], self.db.autoRun[id], self.db.helperModules[id] = nil, nil, nil, nil
  end
 end
 self.db.drafts = {}
 if not self.db.snippets[self.db.selected] then self.db.selected = nil end
end

function W:RevertSaved(id)
 local saved = self.db.snippets[id]
 if not saved then return end
 self:EndRename(false)
 self.db.drafts[id] = { name = saved.name, source = saved.source }
 if self.current == id then
  -- Do not recapture the current editor over the restored snapshot in Select.
  self.current = nil
  self:Select(id)
 else
  self:RefreshTree()
 end
end

if not addon.embedded then
StaticPopupDialogs.LUAWORKBENCH_REVERT = {
 text = L.confirmRevert,
 button1 = _G.ACCEPT, button2 = _G.CANCEL,
 OnAccept = function(_, id) W:RevertSaved(id) end,
 timeout = 0, whileDead = true, hideOnEscape = true, preferredIndex = 3,
}
end

end
rm.LuaWorkbenchModules.Helpers=function(_,addon)
local W, UI, L = addon.Workspace, addon.UI, addon.L
local H = {}
addon.Helpers = H

function H:Options(id)
 W.db.helperModules = W.db.helperModules or {}
 W.db.helperModules[id] = W.db.helperModules[id] or { name = '' }
 return W.db.helperModules[id]
end

function H:Normalize(name)
 if type(name) ~= 'string' then return nil end
 local trimmed = name:match('^%s*(.-)%s*$')
 if #trimmed > 80 or not trimmed:match('^[%a_][%w_.%-]*$') then return nil end
 return trimmed, trimmed:lower()
end

function H:Validate(id, name, enabled)
 local normalized, key = self:Normalize(name)
 if not normalized then return nil, L.helperInvalidName end
 if enabled and not W.db.snippets[id] then return nil, L.saveBeforeAutoRun end
 for other, options in pairs(W.db.helperModules or {}) do
  local _, otherKey = self:Normalize(options.name)
  if other ~= id and options.enabled and otherKey == key then return nil, L.helperDuplicate .. ' ' .. normalized end
 end
 return normalized
end

function H:Set(id, name, enabled)
 local normalized, message = self:Validate(id, name, enabled)
 if not normalized then return false, message end
 local options = self:Options(id)
 options.name, options.enabled = normalized, enabled == true
 return true
end

function H:Resolve(name)
 local _, key = self:Normalize(name)
 if not key then return nil, L.helperInvalidName end
 local found
 for id, options in pairs(W.db.helperModules or {}) do
  local _, otherKey = self:Normalize(options.name)
  if options.enabled and key == otherKey and W.db.snippets[id] then
   if found then return nil, L.helperDuplicate .. ' ' .. name end
   found = { id = id, name = options.name, source = W.db.snippets[id].source, scriptName = W.db.snippets[id].name }
  end
 end
 if not found then return nil, L.helperMissing .. ' ' .. name end
 return found
end

function H:Entries()
 local entries = {}
 for id, options in pairs(W.db.helperModules or {}) do
  if options.enabled and W.db.snippets[id] then
   local module = self:Resolve(options.name)
   if module and module.id == id then entries[#entries + 1] = module end
  end
 end
 table.sort(entries, function(a, b) return a.name:lower() < b.name:lower() end)
 return entries
end

function H:ImportText(name, source, cursor)
 local alias = name:gsub('[^%w_]', '_')
 if not alias:match('^[%a_]') then alias = 'tools_' .. alias end
 local reserved = { ['and']=true, ['break']=true, ['do']=true, ['else']=true, ['elseif']=true, ['end']=true,
  ['false']=true, ['for']=true, ['function']=true, ['if']=true, ['in']=true, ['local']=true, ['nil']=true,
  ['not']=true, ['or']=true, ['repeat']=true, ['return']=true, ['then']=true, ['true']=true, ['until']=true,
  ['while']=true, requireHelper=true }
 local used = {}
 for word in source:gmatch('[%a_][%w_]*') do used[word] = true end
 local base, suffix = alias, 1
 while reserved[alias] or used[alias] do suffix = suffix + 1; alias = base .. suffix end
 local before, after = source:sub(1, cursor), source:sub(cursor + 1)
 return (before ~= '' and before:sub(-1) ~= '\n' and '\n' or '')
  .. 'local ' .. alias .. ' = requireHelper(' .. string.format('%q', name) .. ')'
  .. (after:sub(1, 1) ~= '\n' and '\n' or '')
end

function H:Loader(context)
 local cache, loading, chain, registry = {}, {}, {}, {}
 for id, options in pairs(W.db.helperModules or {}) do
  local _, key = self:Normalize(options.name)
  local saved = W.db.snippets[id]
  if options.enabled and key and saved then
   if registry[key] ~= nil then registry[key] = false
   else registry[key] = { id = id, name = options.name, source = saved.source } end
  end
 end
 local function requireHelper(name)
  local _, key = self:Normalize(name)
  if not key then error(L.helperInvalidName, 0) end
  local module = registry[key]
  if module == false then error(L.helperDuplicate .. ' ' .. name, 0) end
  if not module then error(L.helperMissing .. ' ' .. name, 0) end
  if cache[module.id] then return cache[module.id] end
  if loading[module.id] then error(L.helperCycle .. ' ' .. table.concat(chain, ' -> ') .. ' -> ' .. module.name, 0) end
  local chunk, compileError = _G.loadstring(W:NormalizeSource(module.source), '=LuaWorkbench helper [' .. module.name .. ']')
  if not chunk then error(L.helperLoadError .. ' ' .. module.name .. ': ' .. tostring(compileError), 0) end
  local environment = setmetatable({ addon = addon, editor = addon, requireHelper = requireHelper,
   print = context.print, dump = context.dump, DevTools_Dump = context.DevTools_Dump or function(value, startKey) addon.Query.Console:Dump(value, startKey) end, event = context.event,
  }, { __index = _G })
  _G.setfenv(chunk, environment)
  loading[module.id] = true; chain[#chain + 1] = module.name
  local ok, value = pcall(chunk)
  chain[#chain] = nil; loading[module.id] = nil
  if not ok then error(L.helperLoadError .. ' ' .. module.name .. ': ' .. addon.Query.Console:Format(value), 0) end
  if (_G.issecretvalue and _G.issecretvalue(value)) or type(value) ~= 'table' then error(L.helperMustReturnTable .. ' ' .. module.name, 0) end
  cache[module.id] = value
  return value
 end
 return requireHelper
end

function H:RefreshControlLayout()
 self:UpdateControls()
 W:RefreshTree()
 if addon.Automation.panel and addon.Automation.panel:IsShown() then addon.Automation:UpdateEventRows() end
end

function H:BuildControls(parent)
 self.heading = UI:Text(parent, L.helperModule, 13)
 self.enabled = UI:Check(parent, L.helperEnabled, function(button)
  local options = self:Options(W.current)
  local checked = button:GetChecked() == true
  if not checked then
   options.enabled, self.pendingID = false, nil
   self.name:ClearFocus(); self.error:SetText('')
  else
   local ok, message = self:Set(W.current, self.name:GetText(), true)
   self.pendingID = not ok and W.current or nil
   self.error:SetText(message or '')
   if not ok then self.name:SetFocus() end
  end
  self:RefreshControlLayout()
 end)
 self.nameLabel = UI:Text(parent, L.helperName, 11)
 local box = CreateFrame('EditBox', nil, parent); self.name = box
 box:SetAutoFocus(false); box:SetFontObject(GameFontHighlightSmall); box:SetTextInsets(7, 7, 0, 0); box:SetMaxLetters(80); box:SetHeight(26)
 UI:Background(box, UI.colors.hover); UI:Tooltip(box, L.helperNameHelp)
 box:SetScript('OnEnterPressed', function()
  local desired = self.pendingID == W.current or self:Options(W.current).enabled == true
  local ok, message = self:Set(W.current, box:GetText(), desired)
  self.error:SetText(message or '')
  if ok then
   self.pendingID = nil; box:SetText(self:Options(W.current).name); box:ClearFocus()
  end
  self:RefreshControlLayout()
 end)
 box:SetScript('OnEscapePressed', function()
  self.pendingID = nil; box:ClearFocus(); self.error:SetText(''); self:RefreshControlLayout()
 end)
 self.error = UI:Text(parent, '', 11); self.error:SetTextColor(1, 0.4, 0.4); self.error:SetWordWrap(true)
 self.description = UI:Text(parent, L.helperInlineHelp, 11); self.description:SetWordWrap(true)
 self.example = UI:Text(parent, '', 12); self.example:SetWordWrap(true)
 self.usage = UI:Text(parent, L.helperUsageExample, 11)
 self.consumer = UI:Text(parent, '', 12); self.consumer:SetWordWrap(true)
end

function H:LayoutControls(y)
 local exposed = self.pendingID == W.current or self:Options(W.current).enabled == true
 self.heading:SetPoint('TOPLEFT', 0, -y)
 self.enabled:SetPoint('TOPLEFT', 0, -y - 25); self.enabled:SetPoint('TOPRIGHT', 0, -y - 25)
 self.nameLabel:SetShown(exposed); self.name:SetShown(exposed); self.error:SetShown(exposed)
 if exposed then
  self.nameLabel:SetPoint('TOPLEFT', 0, -y - 56)
  self.name:SetPoint('TOPLEFT', 0, -y - 76); self.name:SetPoint('TOPRIGHT', 0, -y - 76)
  self.error:SetPoint('TOPLEFT', 0, -y - 106); self.error:SetPoint('TOPRIGHT', 0, -y - 106); self.error:SetHeight(38)
 end
 local hasError = exposed and self.error:GetText() ~= ''
 self.error:SetShown(hasError)
 local descriptionY = y + (exposed and (hasError and 146 or 112) or 58)
 self.description:SetPoint('TOPLEFT', 0, -descriptionY); self.description:SetPoint('TOPRIGHT', 0, -descriptionY)
 local bottom = descriptionY + self.description:GetStringHeight() + 14
 self.example:SetShown(exposed); self.usage:SetShown(exposed); self.consumer:SetShown(exposed)
 if exposed then
  local name = self:Options(W.current).name
  if not name or name == '' then name = 'MyHelper' end
  self.example:SetText(addon.Query.Editor:Render('local tools = {}\nfunction tools.GiveInfo(text)\n    print(text)\nend\nreturn tools'))
  self.consumer:SetText(addon.Query.Editor:Render('local tools = requireHelper(' .. string.format('%q', name) .. ')\ntools.GiveInfo("Hello")'))
  for _, block in ipairs({ self.example, self.usage, self.consumer }) do
   block:ClearAllPoints(); block:SetPoint('TOPLEFT', 0, -bottom); block:SetPoint('TOPRIGHT', 0, -bottom); block:SetHeight(0)
   bottom = bottom + block:GetStringHeight() + 14
  end
 end
 return bottom + 6
end

function H:UpdateControls()
 if not self.enabled or not W.current then return end
 local options = self:Options(W.current)
 if self.controlID ~= W.current then
  self.pendingID = nil
  self.name:ClearFocus(); self.error:SetText(''); self.controlID = W.current
 end
 local exposed = options.enabled == true or self.pendingID == W.current
 self.enabled:SetChecked(exposed)
 self.nameLabel:SetShown(exposed); self.name:SetShown(exposed); self.error:SetShown(exposed)
 if not self.name:HasFocus() then self.name:SetText(options.name or '') end
end

end
rm.LuaWorkbenchModules.Navigation=function(_,addon)
local W, UI, L, Console = addon.Workspace, addon.UI, addon.L, addon.Query.Console
local N = { history = {} }
addon.Navigation = N

function N:CanBack() return #self.history > 0 end

function N:Remember()
 self.history[#self.history + 1] = { id = W.current, cursor = Console.input.editBox:GetCursorPosition(), scroll = Console.input.scrollFrame:GetVerticalScroll() }
 if #self.history > 40 then table.remove(self.history, 1) end
end

function N:ScrollTo(input, offset)
 local scroll = input.scrollFrame
 scroll:SetVerticalScroll(math.max(0, math.min(scroll:GetVerticalScrollRange(), offset)))
end

function N:Position(input, position, focus)
 if focus ~= false then input:SetFocus() end
 input:SetCursorPosition(position); input:HighlightText(position, position)
 if input == Console.input then
  Console:UpdateLineNumbers()
  local line = Console:GetLinePosition(Console.source, position)
  local state = input.queryLineNumbers
  local entry = state and state.positions and state.positions[line]
  if entry then self:ScrollTo(input, entry.offset - 40) end
 else
  local size = select(2, input.editBox:GetFont()) or 14
  local _, line = input:GetText():sub(1, position):gsub('\n', '')
  self:ScrollTo(input, line * (size + input.editBox:GetSpacing()) - 40)
 end
end

function N:Back()
 local target = table.remove(self.history)
 if not target then return end
 if self.snapshot then self.snapshot:Hide() end
 if not W.db.drafts[target.id] and not W.db.snippets[target.id] then Console:SetStatus(L.navigationMissingScript, true); return end
 W:Select(target.id)
 self:Position(Console.input, math.min(target.cursor, #Console.source))
 self:ScrollTo(Console.input, target.scroll)
end

function N:SavedSnapshot(module, definition)
 W:HidePanels(self.snapshot)
 if not self.snapshot then
  local panel = CreateFrame('Frame', (not addon.embedded and 'LuaWorkbenchSavedHelper' or nil), W.window); self.snapshot = panel
  panel:SetSize(math.max(320, W.window:GetWidth() - 40), math.max(300, W.window:GetHeight() - 70)); panel:SetPoint('CENTER')
  panel:SetFrameLevel(W.window:GetFrameLevel() + 55); panel:EnableMouse(true)
  UI:MovablePanel(panel, 'savedHelper'); panel:RestorePanelPosition()
 UI:Background(panel, { 0.09, 0.11, 0.15, 1 }); UI:Border(panel, { 0.28, 0.34, 0.43, 1 })
  self.snapshotTitle = UI:Text(panel, '', 13); self.snapshotTitle:SetPoint('TOPLEFT', 14, -12); self.snapshotTitle:SetPoint('RIGHT', -42, 0)
  local close = UI:Button(panel, 'close', _G.CLOSE, function() self:Back() end); close:SetPoint('TOPRIGHT', -4, -4)
  local hint = UI:Text(panel, L.navigationSavedHelp, 11); hint:SetPoint('TOPLEFT', 14, -40); hint:SetPoint('TOPRIGHT', -14, -40); hint:SetWordWrap(true)
  self.snapshotInput = UI:Editor(panel, L.savedCodeOnly, true)
  self.snapshotInput.frame:SetPoint('TOPLEFT', 8, -90); self.snapshotInput.frame:SetPoint('BOTTOMRIGHT', -8, 8)
  self.snapshotInput.editBox:HookScript('OnKeyDown', function(_, key)
   if self:IsBackKey(key) then self:Back() end
  end)
  self.snapshotInput.editBox:SetScript('OnEscapePressed', function() self:Back() end)
  panel:SetScript('OnHide', function() self.snapshotInput:ClearFocus() end)
  if not addon.embedded then _G.UISpecialFrames[#_G.UISpecialFrames + 1] = (not addon.embedded and 'LuaWorkbenchSavedHelper' or nil) end
 end
 self.snapshotTitle:SetText((module.name .. ' — ' .. L.navigationSavedVersion):gsub('|', '||'))
 self.snapshotInput:SetText(W:NormalizeSource(module.source))
 self.snapshot:Show(); self:Position(self.snapshotInput, definition.position0)
 Console:SetStatus(L.navigationSavedHelp)
end

function N:Jump(candidate)
 if candidate.module then
  local module, message = addon.Helpers:Resolve(candidate.module)
  if not module then Console:SetStatus(message, true); return end
  local result = addon.Analysis:Get(W:NormalizeSource(module.source))
  local definition = result.exports[candidate.member]
  if not definition or definition.ambiguous then Console:SetStatus(L.navigationNotFound, true); return end
  self:Remember()
  local draft = W.db.drafts[module.id]
  if draft and W:NormalizeSource(draft.source) ~= W:NormalizeSource(module.source) then
   self:SavedSnapshot(module, definition)
  else
   W:Select(module.id); self:Position(Console.input, definition.position0)
  end
 else
  if not candidate.position0 then Console:SetStatus(L.navigationNotFound, true); return end
  self:Remember(); self:Position(Console.input, candidate.position0)
 end
end

function N:Go(target)
 if not Console.input then return end
 local source, cursor = Console.source, Console.input.editBox:GetCursorPosition()
 if target then
  if target.scriptId ~= W.current or target.source ~= source then Console:SetStatus(L.textSnippetTargetChanged, true); return end
  cursor = target.cursor
 end
 local candidates = addon.Analysis:Resolve(source, cursor)
 if #candidates == 0 then
  local apiName = addon.APIHelp and addon.APIHelp:AtCursor(source, cursor)
  if apiName then addon.KnowledgeBase:Show(apiName); Console:SetStatus(nil); return end
  Console:SetStatus(L.navigationNotFound, true); return
 end
 if #candidates == 1 then self:Jump(candidates[1]); return end
 local entries = {}
 for _, candidate in ipairs(candidates) do
  local selected = candidate
  local line = candidate.position0 and Console:GetLinePosition(source, candidate.position0) or 0
  entries[#entries + 1] = { text = (candidate.name or '') .. ' · ' .. string.format(L.navigationLine, line), action = function() self:Jump(selected) end }
 end
 W:OpenMenu(Console.input.frame, entries)
end

function N:IsBackKey(key)
 return key == 'F12' and IsShiftKeyDown() and not IsControlKeyDown()
  and not (_G.IsAltKeyDown and IsAltKeyDown()) and not (_G.IsMetaKeyDown and _G.IsMetaKeyDown())
end

function N:Shortcut(key)
 if not W.window or not W.window:IsShown() or not Console.input or not Console.input.editBox:HasFocus() then return false end
 if key == 'F12' and not IsControlKeyDown() and not IsShiftKeyDown() and not (_G.IsAltKeyDown and IsAltKeyDown()) and not (_G.IsMetaKeyDown and _G.IsMetaKeyDown()) then
  if not self.held then self.held = key; self:Go() end
  return true
 elseif self:IsBackKey(key) then
  if not self.held then self.held = key; self:Back() end
  return true
 end
 return false
end

end
rm.LuaWorkbenchModules.DebugProbe=function(_,addon)
local P, W, UI, L, C = {}, addon.Workspace, addon.UI, addon.L, addon.Query.Console
addon.DebugProbe = P
P.queue, P.dropped, P.generation = {}, 0, 0

function P:Refresh()
 if not self.panel then return end
 self.panel.status:SetText((self.status or L.debugProbeWaiting) .. '\n' .. string.format(L.debugProbeQueue, #self.queue)
  .. (self.dropped > 0 and ('\n' .. string.format(L.debugProbeOverflow, self.dropped)) or ''))
 self.panel.step:SetEnabled(self.paused == true)
end

local function secret(value) return _G.issecretvalue and _G.issecretvalue(value) end
local function scalar(value)
 if secret(value) then return '<secret>' end
 local kind = type(value)
 if kind == 'string' or kind == 'number' or kind == 'boolean' or kind == 'nil' then return C:Format(value):sub(1, 180) end
 return '<' .. kind .. '>'
end
local function preview(value, full, limit)
 local seen, budget = {}, full and 128 or 32
 local remaining = limit or (full and 8192 or 2400)
 local output = {}
 local function append(text)
  local part = text:sub(1, remaining)
  output[#output+1] = part
  remaining = remaining - #part
 end
 local function atom(item)
  if secret(item) then return '<secret>' end
  local kind = type(item)
  if kind ~= 'string' and kind ~= 'number' and kind ~= 'boolean' and kind ~= 'nil' then return '<' .. kind .. '>' end
  local text = tostring(item)
  local cap = full and remaining or math.min(240, remaining)
  local truncated = #text > cap
  text = text:sub(1, cap):gsub('\t', '    ')
  if truncated then text = text:sub(1, math.max(0,cap-3)) .. '...' end
  return text
 end
 -- Iterative traversal avoids a Lua stack overflow for deeply nested tables.
 local stack = { { value = value, depth = 0 } }
 while #stack > 0 and remaining > 0 do
  local node = stack[#stack]
  if node.open then
   local ok, key, item = pcall(next, node.value, node.key)
   if not ok or secret(key) then
    append(ok and '<secret>' or '<unavailable>')
    append(' }'); table.remove(stack)
   elseif key == nil then
    append(' }'); table.remove(stack)
   elseif budget <= 0 then
    append('... }'); table.remove(stack)
   else
    node.key = key
    budget = budget - 1
    append((node.count > 0 and ',' or '') .. '\n' .. string.rep(' ', math.min(node.depth + 1, 20) * 2) .. atom(key) .. ' = ')
    node.count = node.count + 1
    stack[#stack + 1] = { value = item, depth = node.depth + 1 }
   end
  elseif secret(node.value) or type(node.value) ~= 'table' then
   append(atom(node.value)); table.remove(stack)
  elseif seen[node.value] then
   append('<reference>'); table.remove(stack)
  elseif node.depth >= (full and 8 or 3) then
   append('{ ... }'); table.remove(stack)
  else
   seen[node.value] = true; node.open, node.count = true, 0
   append('{ ')
  end
 end
 local text = table.concat(output)
 if #stack > 0 then text = text:sub(1, math.max(0,#text-4)) .. '\n...' end
 return text
end

function P:FormatPreview(value) return preview(value) end
function P:FormatScalar(value) return scalar(value) end

function P:SecretTooltip(tooltip, label, value)
 if type(value) == 'number' then
  tooltip:SetText(label, 0.85, 0.9, 1)
  -- Format only in the native text sink; never convert or inspect the secret.
  local name = tooltip:GetName()
  local line = name and _G[name .. 'TextLeft1']
  if line then pcall(line.SetFormattedText, line, '%s %s', label, value) end
 else
  local ok = pcall(function() tooltip:SetText(label .. ' ' .. value, 0.85, 0.9, 1) end)
  if not ok then tooltip:SetText(label, 0.85, 0.9, 1) end
 end
end

function P:CaptureVariables(values)
 self.variables = {}
 if not secret(values) and type(values) == 'table' then
  local key
  for _ = 1, 8 do
   local ok, nextKey, value = pcall(next, values, key)
   if not ok or secret(nextKey) then break end
   if nextKey == nil then break end
   key = nextKey
   self.variables[#self.variables + 1] = { name = scalar(key), value = scalar(value), preview = preview(value), hasSecretText = secret(value) and (type(value) == 'string' or type(value) == 'number'), secretText = value }
  end
 end
 for index, row in ipairs(self.variableRows or {}) do
  local item = self.variables[index]
  if item then
   row.text:SetText((item.name .. ' = ' .. item.value):gsub('|', '||'))
   row.preview = (item.name .. ' = ' .. item.preview):gsub('|', '||')
   row.secretLabel = item.name:gsub('|', '||') .. ' = |cff88ff88<secret>|r'
   row.hasSecretText, row.secretText = item.hasSecretText, item.secretText
  end
  if not item then row.hasSecretText, row.secretText, row.secretLabel = nil, nil, nil end
  row:SetShown(item ~= nil)
 end
end

function P:ValidateBindings()
 local source = self.checkpointBindings
 if secret(source) then error(L.debugProbeBindingsError, 0) end
 if source == nil then return {} end
 if type(source) ~= 'table' then error(L.debugProbeBindingsError, 0) end
 local bindings, key = {}, nil
 while true do
  local name, item = next(source, key)
  if secret(name) then error(L.debugProbeBindingsError, 0) end
  if name == nil then break end
  key = name
  if type(name) ~= 'string' or not name:match('^[%a_][%w_]*$') or secret(item) or type(item) ~= 'table' then error(L.debugProbeBindingsError, 0) end
  local getter, setter = rawget(item, 'get'), rawget(item, 'set')
  if secret(getter) or secret(setter) or type(getter) ~= 'function' or (setter ~= nil and type(setter) ~= 'function') then error(L.debugProbeBindingsError, 0) end
  bindings[name] = { get = getter, set = setter }
 end
 return bindings
end

function P:RefreshBoundVariables(token, bindings, overlay, written)
 local display = {}
 if not secret(self.capturedValues) and type(self.capturedValues) == 'table' then
  local key
  for _ = 1, 8 do
   local ok, name, value = pcall(next, self.capturedValues, key)
   if not ok then break end
   if secret(name) or name == nil then break end
   key = name; display[name] = value
  end
 end
 for key in pairs(written or {}) do display[key] = overlay[key] end
 local count = 0
 for name, binding in pairs(bindings) do
  if count == 8 then break end
  count = count + 1
  local ok, value = pcall(binding.get)
  if self.evalToken ~= token or not self.paused then return end
  -- Nil remains visible in the inspector even though Lua tables cannot store it.
  if not ok then display[name] = L.debugProbeError
  elseif secret(value) then display[name] = value
  elseif value == nil then display[name] = 'nil'
  else display[name] = value end
 end
 self:CaptureVariables(display)
end

function P:ClearEvaluation()
 self.capturedValues, self.invocationEnvironment, self.evaluationEnvironment, self.evalToken = nil, nil, nil, nil
 self.checkpointBindings, self.liveBindings, self.evalOverlay, self.evalWritten = nil, nil, nil, nil
end

function P:TerminalWrite(...)
 self.terminalLines = self.terminalLines or {}
 local parts, remaining = {}, 8192
 for index = 1, select('#', ...) do
  if remaining < 8 then parts[#parts+1] = '...'; break end
  local part = preview(select(index, ...), true, remaining-4)
  parts[#parts+1], remaining = part, remaining-#part-4
 end
 local text = table.concat(parts, '    '):gsub('|', '||')
 for line in (text .. '\n'):gmatch('(.-)\n') do
  self.terminalLines[#self.terminalLines + 1] = line
  if #self.terminalLines > 100 then table.remove(self.terminalLines, 1) end
 end
 -- Bound retained bytes as well as line count, including escaped pipe characters.
 local bytes = 0
 for _,line in ipairs(self.terminalLines) do bytes = bytes + #line + 1 end
 while bytes > 65536 do
  bytes = bytes - #self.terminalLines[1] - 1
  table.remove(self.terminalLines,1)
 end
 if not self.terminalBatch then self:RefreshTerminal() end
end

function P:RefreshTerminal()
 if self.terminal then
  local joined = table.concat(self.terminalLines or {}, '\n')
  self.terminal.output:SetText(joined)
  if self.terminal.output.SetCursorPosition then self.terminal.output:SetCursorPosition(#joined) end
  local scroll = self.terminal.output.scrollFrame
  if scroll then scroll:UpdateScrollChildRect(); scroll:SetVerticalScroll(scroll:GetVerticalScrollRange()) end
 end
end

function P:TerminalDump(value, startKey)
 local previousBatch = self.terminalBatch
 self.terminalBatch = true
 local ok, err = pcall(C.Dump, C, value, startKey, nil, function(text)
  if secret(text) or type(text) ~= 'string' then self:TerminalWrite(text); return end
  -- Strip native dump colors before escaping plain terminal text. Decode
  -- escaped pipes once so literal color-like strings remain literal.
  local parts, cursor = {}, 1
  while cursor <= #text do
   local at = text:find('|', cursor, true)
   if not at then parts[#parts + 1] = text:sub(cursor); break end
   parts[#parts + 1] = text:sub(cursor, at - 1)
   local pair = text:sub(at, at + 1)
   if pair == '||' then parts[#parts + 1] = '|'; cursor = at + 2
   elseif pair == '|r' then cursor = at + 2
   elseif text:sub(at, at + 9):match('^|c%x%x%x%x%x%x%x%x$') then cursor = at + 10
   else parts[#parts + 1] = '|'; cursor = at + 1 end
  end
  self:TerminalWrite(table.concat(parts))
 end)
 self.terminalBatch = previousBatch
 if not previousBatch then self:RefreshTerminal() end
 if not ok then error(err, 0) end
end

function P:ShowTerminal()
 if not self.terminal then
  local panel = CreateFrame('Frame', nil, UIParent)
  self.terminal = panel
  panel:SetSize(560, 330); panel:SetPoint('CENTER'); panel:SetFrameStrata('DIALOG'); panel:SetClampedToScreen(true)
  panel:SetMovable(true); panel:EnableMouse(true); panel:RegisterForDrag('LeftButton')
  panel:SetScript('OnDragStart', function() panel:StartMoving() end)
  panel:SetScript('OnDragStop', function() panel:StopMovingOrSizing() end)
  UI:Background(panel, UI.colors.panel)
  local title = UI:Text(panel, L.debugProbeTerminal, 14); title:SetPoint('TOPLEFT', 12, -12)
  panel.help = UI:Button(panel, '?', L.debugProbeTerminalHelp, function() end)
  panel.help:SetPoint('LEFT', title, 'RIGHT', 4, 0); panel.help:SetSize(22, 22)
  local close = UI:Button(panel, 'close', _G.CLOSE, function() panel:Hide() end); close:SetPoint('TOPRIGHT', -3, -3)
  panel.output = UI:Editor(panel, L.queryLuaOutput, true)
  panel.output.frame:SetPoint('TOPLEFT', 8, -36); panel.output.frame:SetPoint('BOTTOMRIGHT', -8, 70)
  if panel.output.scrollFrame then
   panel.output.scrollFrame:HookScript('OnScrollRangeChanged', function(scroll)
    scroll:SetVerticalScroll(scroll:GetVerticalScrollRange())
   end)
  end
  panel.input = CreateFrame('EditBox', nil, panel); panel.input:SetAutoFocus(false); panel.input:SetFontObject(ChatFontNormal)
  panel.input:SetTextInsets(8, 8, 0, 0); panel.input:SetMaxLetters(4000)
  panel.input:SetHistoryLines(100); panel.input:SetAltArrowKeyMode(true)
  panel.input:SetPoint('BOTTOMLEFT', 12, 32); panel.input:SetPoint('BOTTOMRIGHT', -12, 32); panel.input:SetHeight(28)
  UI:Background(panel.input, UI.colors.hover)
  panel.input:SetScript('OnEnterPressed', function(box)
   self:Evaluate(box:GetText())
   box:SetText('')
  end)
  panel.input:SetScript('OnEscapePressed', function(box) box:ClearFocus() end)
  local hint = UI:Text(panel, L.debugProbeInput, 11); hint:SetPoint('BOTTOMLEFT', 12, 12)
  panel:SetScript('OnHide', function() panel.input:ClearFocus(); panel:StopMovingOrSizing() end)
 end
 self.terminal.output:SetText(table.concat(self.terminalLines or {}, '\n'))
 self.terminal:Show(); self.terminal.input:SetFocus()
 local scroll = self.terminal.output.scrollFrame
 if scroll then scroll:UpdateScrollChildRect(); scroll:SetVerticalScroll(scroll:GetVerticalScrollRange()) end
end

function P:Evaluate(source)
 if self.evaluating or not self.paused or not self.thread or not self.evalToken then self:TerminalWrite(L.debugProbeNotPaused); return false end
 if type(source) ~= 'string' or not source:find('%S') then return false end
 if self.terminal then self.terminal.input:AddHistoryLine(source) end
 self:TerminalWrite('> ' .. source)
 local token, generation = self.evalToken, self.generation
 local function active() return self.paused and self.thread and self.evalToken == token and self.generation == generation end
 if not self.evaluationEnvironment then
  local ok, bindings = pcall(self.ValidateBindings, self)
  if not ok then self:TerminalWrite(L.debugProbeBindingsError); return false end
  local overlay, written = {}, {}
  self.liveBindings, self.evalOverlay, self.evalWritten = bindings, overlay, written
  local function output(...) if active() then self:TerminalWrite(...) end end
  local function dump(...)
   if not active() then return end
   local count = select('#', ...)
   for index = 1, count do local value = select(index, ...); self:TerminalDump(value, count > 1 and ('arg[' .. index .. ']') or nil) end
  end
  local builtins = { print = output, dump = dump,
   DevTools_Dump = function(value, startKey) if active() then self:TerminalDump(value, startKey) end end,
   breakpoint = function() error(L.debugProbeTerminalHelp, 0) end }
  local environment = setmetatable({}, {
   __index = function(_, key)
    if not active() then error(L.debugProbeNotPaused, 0) end
    if bindings[key] then return bindings[key].get() end
    if written[key] then return overlay[key] end
    if builtins[key] then return builtins[key] end
    if not secret(self.capturedValues) and type(self.capturedValues) == 'table' then
     local value = rawget(self.capturedValues, key)
     if secret(value) then return value end
     if value ~= nil then return value end
    end
    return self.invocationEnvironment and self.invocationEnvironment[key]
   end,
   __newindex = function(_, key, value)
    if not active() then error(L.debugProbeNotPaused, 0) end
    if bindings[key] then
     if not bindings[key].set then error(L.debugProbeReadOnly .. ': ' .. key, 0) end
     bindings[key].set(value)
    else written[key], overlay[key] = true, value end
   end,
  })
  self.evaluationEnvironment = environment
 end
 local chunk, failure = _G.loadstring('return ' .. source, '=LuaWorkbench debug terminal')
 if not chunk then chunk, failure = _G.loadstring(source, '=LuaWorkbench debug terminal') end
 if not chunk then self:TerminalWrite(L.debugProbeError, failure); return false end
 _G.setfenv(chunk, self.evaluationEnvironment)
 local function pack(...) return { n = select('#', ...), ... } end
 self.evaluating = token
 local result = pack(pcall(chunk))
 if active() then pcall(self.RefreshBoundVariables, self, token, self.liveBindings, self.evalOverlay, self.evalWritten) end
 self.evaluating = nil
 if not active() then self:TerminalWrite(L.debugProbeNotPaused); return false end
 if not result[1] then self:TerminalWrite(L.debugProbeError, result[2]); return false end
 if result.n > 1 then self:TerminalWrite(unpack(result, 2, result.n)) end
 return true
end

function P:ShowSnapshot()
 if not self.source then return end
 if not self.snapshot then
  local panel = CreateFrame('Frame', nil, UIParent)
  self.snapshot = panel
  panel:SetSize(650, 440); panel:SetPoint('CENTER'); panel:SetFrameStrata('DIALOG'); panel:SetClampedToScreen(true)
  panel:SetMovable(true); panel:EnableMouse(true); panel:RegisterForDrag('LeftButton')
  panel:SetScript('OnDragStart', function() panel:StartMoving() end)
  panel:SetScript('OnDragStop', function() panel:StopMovingOrSizing() end)
  UI:Background(panel, UI.colors.panel)
  local title = UI:Text(panel, L.debugProbeSnapshot, 11)
  title:SetPoint('TOPLEFT', 12, -10); title:SetPoint('TOPRIGHT', -36, -10); title:SetHeight(42); title:SetWordWrap(true)
  local close = UI:Button(panel, 'close', _G.CLOSE, function() panel:Hide() end); close:SetPoint('TOPRIGHT', -3, -3)
  panel.code = UI:Editor(panel, L.debugProbeShow, true)
  panel.code.frame:SetPoint('TOPLEFT', 8, -58); panel.code.frame:SetPoint('BOTTOMRIGHT', -8, 8)
 end
 self.snapshot.code:SetText(self.source)
 self.snapshot:Show()
 if self.line and self.snapshot.code.SetCursorPosition then
  local offset = 0
  for _ = 2, self.line do local stop = self.source:find('\n', offset + 1, true); if not stop then break end; offset = stop end
  self.snapshot.code:SetCursorPosition(offset)
  self.snapshot.code:HighlightText(offset, (self.source:find('\n', offset + 1, true) or (#self.source + 1)) - 1)
 end
end

function P:BuildPanel()
 if self.panel then self.panel:Show(); return end
 local panel = CreateFrame('Frame', nil, UIParent)
 self.panel = panel
 panel:SetSize(430, 450); panel:SetPoint('CENTER'); panel:SetFrameStrata('DIALOG'); panel:SetClampedToScreen(true)
 panel:SetMovable(true); panel:EnableMouse(true); panel:RegisterForDrag('LeftButton')
 panel:SetScript('OnDragStart', function() panel:StartMoving() end)
 panel:SetScript('OnDragStop', function() panel:StopMovingOrSizing() end)
 UI:Background(panel, UI.colors.panel); UI:Border(panel, { 0.35, 0.55, 0.7, 1 })
 local title = UI:Text(panel, L.debugProbeTitle, 14); title:SetPoint('TOPLEFT', 12, -12)
 panel.status = UI:Text(panel, '', 12); panel.status:SetPoint('TOPLEFT', 12, -40); panel.status:SetWidth(356); panel.status:SetHeight(80)
 panel.status:SetWordWrap(true)
 panel.step = UI:Action(panel, 'next', L.debugProbeStep, L.debugProbeHelp, function() self:Step() end)
 panel.step:SetPoint('TOPLEFT', 12, -126)
 local show = UI:Action(panel, 'copy', L.debugProbeShow, L.debugProbeHelp, function() self:ShowSnapshot() end)
 show:SetPoint('TOPLEFT', 12, -162)
 local terminal = UI:Action(panel, '{}', L.debugProbeTerminal, L.debugProbeTerminalHelp, function() self:ShowTerminal() end)
 terminal:SetPoint('LEFT', show, 'RIGHT', 8, 0)
 local stop = UI:Action(panel, 'clear', L.debugProbeStop, L.debugProbeHelp, function() self:Stop() end)
 stop:SetPoint('BOTTOMRIGHT', -12, 12)
 local variables = UI:Text(panel, L.debugProbeVariables, 12); variables:SetPoint('TOPLEFT', 12, -205)
 self.variableRows = {}
 for index = 1, 8 do
  local row = CreateFrame('Button', nil, panel)
  row:SetSize(404, 22); row:SetPoint('TOPLEFT', 12, -225 - (index - 1) * 22)
  row.text = UI:Text(row, '', 11); row.text:SetAllPoints(); row.text:SetWordWrap(false)
  row:SetScript('OnEnter', function()
   GameTooltip:SetOwner(row, 'ANCHOR_CURSOR'); GameTooltip:ClearLines()
   if row.hasSecretText then
    self:SecretTooltip(GameTooltip, row.secretLabel, row.secretText)
   else GameTooltip:AddLine((row.preview or ''):gsub('<secret>', '|cff88ff88<secret>|r'), 0.85, 0.9, 1, true) end
   GameTooltip:Show()
  end)
  row:SetScript('OnLeave', function() GameTooltip:Hide() end)
  row:Hide(); self.variableRows[index] = row
 end
 UI:KeyboardPropagation(panel, true, true)
 panel:SetScript('OnKeyDown', function(_, key)
  if UI:InCombat() then UI:KeyboardPropagation(panel, true); return end
  local input = C.input and C.input.editBox
  local focused = panel:IsMouseOver() or (W.window and W.window:IsShown() and input and input:HasFocus())
  local modified = (_G.IsControlKeyDown and _G.IsControlKeyDown()) or (_G.IsShiftKeyDown and _G.IsShiftKeyDown())
   or (_G.IsAltKeyDown and _G.IsAltKeyDown()) or (_G.IsMetaKeyDown and _G.IsMetaKeyDown())
  local consume = key == 'F10' and self.paused and focused and not modified
  UI:KeyboardPropagation(panel, not consume)
  if consume and not self.held then self.held = true; self:Step() end
 end)
 panel:SetScript('OnKeyUp', function(_, key) if key == 'F10' then self.held = nil end; UI:KeyboardPropagation(panel, true) end)
 panel:SetScript('OnHide', function() self.held = nil; UI:KeyboardPropagation(panel, true) end)
end

function P:Stop()
 self.generation = self.generation + 1
 if self.events then self.events:UnregisterAllEvents() end
 self.thread, self.paused, self.running, self.armed = nil, nil, nil, nil
 self.queue, self.held = {}, nil
 self:ClearEvaluation()
 if self.terminal then self.terminal:Hide() end
 self:CaptureVariables(nil)
 if self.panel then self.panel:Hide() end
 if self.snapshot then self.snapshot:Hide() end
end

function P:Fail(value)
 self:ClearEvaluation()
 self.status = L.debugProbeError .. ': ' .. C:Format(value)
 C:Write(self.status)
 self.thread, self.paused = nil, nil
 self:CaptureVariables(nil)
 self:Refresh()
end

function P:Resume(...)
 local thread = self.thread
 local ok, value = coroutine.resume(thread, ...)
 if self.thread ~= thread then return end
 if not ok then self:Fail(value)
 elseif coroutine.status(self.thread) == 'dead' then
  self.thread, self.paused = nil, nil
  self:CaptureVariables(nil)
  self:ClearEvaluation()
  self.status = L.debugProbeFinished
 elseif not (_G.issecretvalue and _G.issecretvalue(value)) and value == self.checkpoint then
  self.paused = true
  local valid, bindings = pcall(self.ValidateBindings, self)
  if valid then
   self.evaluating = self.evalToken
   pcall(self.RefreshBoundVariables, self, self.evalToken, bindings)
   self.evaluating = nil
  else self:TerminalWrite(L.debugProbeBindingsError) end
 else self:Fail(L.debugProbeHelp) end
 self:Refresh()
end

function P:StartInvocation(item)
 local chunk, failure = _G.loadstring(self.source, '=LuaWorkbench debugger test')
 if not chunk then self:Fail(failure); return end
 local generation = self.generation
 local function current() return self.armed and self.generation == generation and coroutine.running() == self.thread end
 local function output(...)
  if self.generation == generation and self.evaluating and self.evaluating == self.evalToken then self:TerminalWrite(...)
  elseif current() then C:Write(...) end
 end
 local function devtools(value, startKey)
  if self.generation == generation and self.evaluating and self.evaluating == self.evalToken then self:TerminalDump(value, startKey)
  elseif current() then C:Dump(value, startKey) end
 end
 local function dump(...)
  local count = select('#', ...)
  for index = 1, count do local value = select(index, ...); devtools(value, count > 1 and ('arg[' .. index .. ']') or nil) end
 end
 local environment
 environment = setmetatable({ addon = addon, editor = addon, event = item.event, print = output,
  dump = dump, DevTools_Dump = devtools,
  requireHelper = function() error(L.debugProbeHelp, 0) end,
  breakpoint = function(label, values, bindings)
   if not current() then error(L.debugProbeError, 0) end
   self.status = L.debugProbePaused .. ': ' .. C:Format(label)
   self.line = nil
   if _G.debugstack then
    local ok, stack = pcall(_G.debugstack, 2, 3, 0)
    if ok and not secret(stack) and type(stack) == 'string' then self.line = tonumber(stack:match('LuaWorkbench debugger test:(%d+)')) end
   end
   self.invocationEnvironment = environment
   self.capturedValues, self.evalToken, self.evaluationEnvironment = values, {}, nil
   self.checkpointBindings, self.liveBindings, self.evalOverlay, self.evalWritten = bindings, nil, nil, nil
   self:CaptureVariables(values)
   self:Refresh()
   return coroutine.yield(self.checkpoint)
  end,
 }, { __index = _G })
 self.invocationEnvironment = environment
 _G.setfenv(chunk, environment)
 self.thread = coroutine.create(chunk)
 self:Resume(unpack(item.args, 1, item.args.n))
end

function P:Pump()
 if self.running or self.thread or not self.armed then return end
 self.running = true
 while self.armed and not self.thread and #self.queue > 0 do
  self:StartInvocation(table.remove(self.queue, 1))
 end
 self.running = nil
 self:Refresh()
end

function P:Enqueue(event, ...)
 if not self.armed or event ~= self.event then return false end
 if #self.queue >= 50 then self.dropped = self.dropped + 1; self:Refresh(); return false end
 self.queue[#self.queue + 1] = { event = event, args = { n = select('#', ...), ... } }
 self:Pump()
 self:Refresh()
 return true
end

function P:Step()
 if self.evaluating then return false end
 if not self.paused or not self.thread then return false end
 self.paused = nil
 self:ClearEvaluation()
 self:Resume()
 self:Pump()
 return true
end

function P:Arm(event)
 self:Stop()
 self.terminalLines = {}
 if self.terminal then self.terminal.output:SetText('') end
 W:Show()
 self:BuildPanel()
 self.source = W:NormalizeSource(C.input:GetText())
 self.scriptId = W.current
 self.dropped, self.checkpoint = 0, {}
 self:CaptureVariables(nil)
 if not (_G.coroutine and coroutine.create and coroutine.resume and coroutine.yield and _G.loadstring and _G.setfenv) then
  self:Fail(L.debugProbeHelp); return false
 end
 local chunk, failure = _G.loadstring(self.source, '=LuaWorkbench debugger test')
 if not chunk then self:Fail(failure); return false end
 event = type(event) == 'string' and event:match('^%s*([%u%d_]+)%s*$') or nil
 if not event then self:Fail(L.invalidEvent); return false end
 if not self.events then
  self.events = CreateFrame('Frame')
  self.events:SetScript('OnEvent', function(_, name, ...) self:Enqueue(name, ...) end)
 end
 local ok, result = pcall(self.events.RegisterEvent, self.events, event)
 if not ok or result == false then self.events:UnregisterAllEvents(); self:Fail(L.invalidEvent); return false end
 self.event, self.armed, self.status = event, true, L.debugProbeWaiting
 self:Refresh()
 return true
end

if not addon.embedded then
_G.SLASH_LUAWORKBENCHDEBUG1 = '/lwdebug'
_G.SlashCmdList.LUAWORKBENCHDEBUG = function(message)
 local command = (message or ''):match('^%s*(.-)%s*$')
 if command == 'stop' then P:Stop()
 elseif command == 'step' then P:Step()
 elseif command:match('^eval%s') then P:ShowTerminal(); P:Evaluate(command:match('^eval%s+(.*)$'))
 elseif command == 'fire' then if P.armed then P:Enqueue(P.event) end
 elseif command == '' then C:Write(L.debugProbeHelp)
 else P:Arm(command) end
end
end

end
rm.LuaWorkbenchModules.DebugCompiler=function(_,addon)
local D, P = {}, {}
addon.DebugCompiler = D
P.__index = P
local binary = { ['or']=1, ['and']=2, ['<']=3, ['>']=3, ['<=']=3, ['>=']=3, ['~=']=3, ['==']=3, ['..']=4, ['+']=5, ['-']=5, ['*']=6, ['/']=6, ['%']=6, ['^']=8 }
local function identifier(token) return token.kind == 'identifier' or token.kind == 'call' end
function P:peek() return self.items[self.index] or self.eof end
function P:take()
 self.steps = self.steps + 1
 if self.steps > 80000 then error('Debugger compiler: source exceeds parser budget', 0) end
 local token = self:peek(); self.index = self.index + 1; self.last = token; return token
end
function P:accept(text) if self:peek().text == text then return self:take() end end
function P:expect(text)
 local token = self:accept(text)
 if not token then error('Debugger compiler: expected ' .. text .. ' at line ' .. self:peek().line, 0) end
 return token
end
function P:name()
 local token = self:take()
 if not identifier(token) then error('Debugger compiler: expected a name at line ' .. token.line, 0) end
 return token.text
end
function P:edit(start, finish, text)
 self.edits[#self.edits + 1] = { start=start, finish=finish, text=text, order=#self.edits + 1 }
 self.generated = self.generated + #text
 if self.generated > 2000000 then error('Debugger compiler: generated code exceeds size budget', 0) end
end
function P:insert(position, text) self:edit(position, position - 1, text) end
function P:scope() self.scopes[#self.scopes + 1] = {} end
function P:leave() self.scopes[#self.scopes] = nil end
function P:declare(name) self.scopes[#self.scopes][name] = true end
function P:bindings()
 local names = {}
 for _, scope in ipairs(self.scopes) do for name in pairs(scope) do names[name] = true end end
 local ordered = {}; for name in pairs(names) do ordered[#ordered + 1] = name end; table.sort(ordered)
 local parts, value = {}, self.helper .. '_value'
 for _, name in ipairs(ordered) do
  parts[#parts + 1] = '[' .. string.format('%q', name) .. ']={get=function() return ' .. name
   .. ' end,set=function(' .. value .. ') ' .. name .. '=' .. value .. ' end}'
 end
 return '{' .. table.concat(parts, ',') .. '}'
end
function P:checkpoint(token)
 self.lines[token.line] = true
 self:insert(token.start, ' ' .. self.helper .. '("step",' .. token.line .. ',' .. self:bindings() .. ',' .. self.frame .. '); ')
end
function P:functionBody(method, line)
 self:expect('('); self:scope()
 if method then self:declare('self') end
 if self:peek().text ~= ')' then
  repeat
   if self:accept('...') then break end
   self:declare(self:name())
  until not self:accept(',')
 end
 local closing = self:expect(')')
 local previous = self.frame
 self.serial = self.serial + 1; self.frame = self.helper .. '_frame' .. self.serial
 self:insert(closing.finish + 1, ' local ' .. self.frame .. '=' .. self.helper .. '("enter",' .. line .. '); ')
 self:chunk({ ['end']=true }, true)
 local ending = self:expect('end')
 self:insert(ending.start, ' ' .. self.helper .. '("leave",' .. self.frame .. '); ')
 self.frame = previous; self:leave()
end
function P:arguments()
 if self:accept('(') then
  if self:peek().text ~= ')' then self:expressions() end
  self:expect(')')
 elseif self:peek().text == '{' or self:peek().kind == 'string' then self:expression(9)
 else error('Debugger compiler: expected call arguments at line ' .. self:peek().line, 0) end
end
function P:expression(minimum)
 self.depth = self.depth + 1
 if self.depth > 70 then error('Debugger compiler: expression nesting limit', 0) end
 local token = self:take()
 local prefix, called = false, false
 if identifier(token) then prefix = true
 elseif token.text == '(' then self:expression(0); self:expect(')'); prefix = true
 elseif token.text == 'function' then self:functionBody(false, token.line)
 elseif token.text == '{' then
  while self:peek().text ~= '}' do
   if self:accept('[') then self:expression(0); self:expect(']'); self:expect('='); self:expression(0)
   elseif identifier(self:peek()) and self.items[self.index + 1] and self.items[self.index + 1].text == '=' then self:take(); self:take(); self:expression(0)
   else self:expression(0) end
   if not self:accept(',') and not self:accept(';') then break end
  end
  self:expect('}')
 elseif token.text == 'not' or token.text == '#' or token.text == '-' then self:expression(7)
 elseif token.kind ~= 'string' and token.kind ~= 'number' and token.kind ~= 'literal' and token.text ~= '...' then
  error('Debugger compiler: unsupported expression at line ' .. token.line, 0)
 end
 while prefix do
  if self:accept('.') then self:name(); called = false
  elseif self:accept('[') then self:expression(0); self:expect(']'); called = false
  elseif self:peek().text == ':' then
   local colon = self:take()
   local method = self:name()
   if method == 'SetScript' or method == 'HookScript' then
    -- A factory captures the receiver and its method before evaluating arguments,
    -- matching Lua's colon-call order without evaluating the receiver twice.
    self:insert(token.start, self.helper .. '("method",')
    self:edit(colon.start, colon.finish, ',')
    self:edit(self.last.start, self.last.finish, string.format('%q', method) .. ')')
   end
   self:arguments(); called = true
  elseif self:peek().text == '(' or self:peek().text == '{' or self:peek().kind == 'string' then self:arguments(); called = true
  else break end
 end
 while true do
  local op = self:peek().text
  local precedence = binary[op]
  if not precedence or precedence <= minimum then break end
  self:take(); self:expression((op == '^' or op == '..') and precedence - 1 or precedence)
 end
 self.depth = self.depth - 1
 return called
end
function P:expressions()
 self:expression(0)
 while self:accept(',') do self:expression(0) end
end
function P:statement()
 local token = self:peek()
 if self:accept(';') then return end
 if token.text ~= 'while' then self:checkpoint(token) end
 if self:accept('local') then
  if self:accept('function') then self:declare(self:name()); self:functionBody(false, token.line)
  else
   local names = { self:name() }
   while self:accept(',') do names[#names + 1] = self:name() end
   if self:accept('=') then self:expressions() end
   for _, name in ipairs(names) do self:declare(name) end
  end
 elseif self:accept('function') then
  self:name(); while self:accept('.') do self:name() end
  local method = self:accept(':'); if method then self:name() end
  self:functionBody(method ~= nil, token.line)
 elseif self:accept('if') then
  self:expression(0); self:expect('then'); self:scope(); self:chunk({ ['elseif']=true, ['else']=true, ['end']=true }); self:leave()
  while self:accept('elseif') do self:expression(0); self:expect('then'); self:scope(); self:chunk({ ['elseif']=true, ['else']=true, ['end']=true }); self:leave() end
  if self:accept('else') then self:scope(); self:chunk({ ['end']=true }); self:leave() end
  self:expect('end')
 elseif self:accept('while') then
  self.lines[token.line] = true
  self:edit(token.start, token.finish, 'while true do ' .. self.helper .. '("step",' .. token.line .. ',' .. self:bindings() .. ',' .. self.frame .. '); if (')
  self:expression(0)
  local opening = self:expect('do')
  self:edit(opening.start, opening.finish, ') then else break end; ')
  self:scope(); self:chunk({ ['end']=true }); self:expect('end'); self:leave()
 elseif self:accept('repeat') then
  self:scope(); self:chunk({ ['until']=true }); self:checkpoint(self:peek()); self:expect('until'); self:expression(0); self:leave()
 elseif self:accept('for') then
  local names = { self:name() }
  if self:accept('=') then self:expression(0); self:expect(','); self:expression(0); if self:accept(',') then self:expression(0) end
  else
   while self:accept(',') do names[#names + 1] = self:name() end
   self:expect('in'); self:expressions()
  end
  local opening = self:expect('do'); self:scope(); for _, name in ipairs(names) do self:declare(name) end
  self:insert(opening.finish + 1, ' ' .. self.helper .. '("step",' .. token.line .. ',' .. self:bindings() .. ',' .. self.frame .. '); ')
  self:chunk({ ['end']=true }); self:expect('end'); self:leave()
 elseif self:accept('do') then self:scope(); self:chunk({ ['end']=true }); self:expect('end'); self:leave()
 elseif self:accept('return') then
  local nextToken = self:peek()
  local empty = nextToken.kind == 'eof' or nextToken.text == ';' or nextToken.text == 'end' or nextToken.text == 'else' or nextToken.text == 'elseif' or nextToken.text == 'until'
  if not empty then self:expressions() end
  self:edit(token.start, token.finish, 'do return ' .. self.helper .. '("return",' .. self.frame .. (empty and '' or ','))
  self:insert(self.last.finish + 1, ') end')
 elseif self:accept('break') then self:edit(token.start, token.finish, 'do break end'); return
 else
  local called = self:expression(9)
  if self:accept(',') then repeat self:expression(9) until not self:accept(','); self:expect('='); self:expressions()
  elseif self:accept('=') then self:expressions()
  elseif not called then error('Debugger compiler: unsupported statement at line ' .. token.line, 0) end
 end
end
function P:chunk(stops, nonempty)
 self.blockDepth = self.blockDepth + 1
 if self.blockDepth > 60 then error('Debugger compiler: block nesting limit', 0) end
 if nonempty and stops[self:peek().text] then self:checkpoint(self:peek()) end
 while self:peek().kind ~= 'eof' and not stops[self:peek().text] do self:statement() end
 self.blockDepth = self.blockDepth - 1
end

function D:Compile(source)
 if type(source) ~= 'string' or #source > 150000 then return nil, 'Debugger compiler: source size limit' end
 local original, failure = _G.loadstring(source, '=LuaWorkbench source')
 if not original then return nil, failure end
 local tokens = addon.Query.Editor:Tokenize(source, 30000)
 local items, line = {}, 1
 for _, token in ipairs(tokens) do
  if token.truncated then return nil, 'Debugger compiler: token budget' end
  token.line = line
  local _, count = token.text:gsub('\n', ''); line = line + count
  if token.kind ~= 'space' and token.kind ~= 'newline' and token.kind ~= 'comment' then items[#items + 1] = token end
 end
 local serial, helper = 1, '__LuaWorkbenchDebug1'
 while source:find(helper, 1, true) do serial = serial + 1; helper = '__LuaWorkbenchDebug' .. serial end
 local parser = setmetatable({ items=items, index=1, steps=0, depth=0, blockDepth=0, scopes={}, edits={}, generated=0,
  eof={kind='eof',text='',start=#source+1,finish=#source,line=line}, helper=helper, serial=0, frame=helper .. '_frame0', lines={} }, P)
 local ok, problem = pcall(function()
  parser:scope()
  parser:insert(1, 'local ' .. parser.frame .. '=' .. helper .. '("enter",1); ')
  parser:chunk({})
  if parser:peek().kind ~= 'eof' then error('Debugger compiler: incomplete parse', 0) end
  parser:insert(#source + 1, '\n' .. helper .. '("leave",' .. parser.frame .. ');')
 end)
 if not ok then return nil, problem end
 table.sort(parser.edits, function(a,b) return a.start == b.start and a.order < b.order or a.start < b.start end)
 local parts, position = {}, 1
 for _, edit in ipairs(parser.edits) do
  if edit.start < position then return nil, 'Debugger compiler: overlapping edits' end
  parts[#parts + 1] = source:sub(position, edit.start - 1); parts[#parts + 1] = edit.text
  position = math.max(edit.finish + 1, edit.start)
 end
 parts[#parts + 1] = source:sub(position)
 local instrumented = table.concat(parts)
 local compiled, compilerError = _G.loadstring(instrumented, '=LuaWorkbench debugger')
 if not compiled then return nil, compilerError end
 local lineMap = {}; for index = 1, line do lineMap[index] = index end; lineMap[line + 1] = line
 return instrumented, { helperName=helper, lines=parser.lines, lineMap=lineMap, tailCallsPreserved=false }
end

end
rm.LuaWorkbenchModules.Debugger=function(_,addon)
local D, P, C, L = {}, addon.DebugProbe, addon.Query.Console, addon.L
addon.Debugger = D
for name, method in pairs(P) do if type(method) == 'function' then D[name] = method end end
D.queue, D.breakpoints, D.breakpointSources, D.generation, D.dropped = {}, {}, {}, 0, 0
local function secret(value) return _G.issecretvalue and _G.issecretvalue(value) end

function D:Refresh()
 if addon.DebugUI then addon.DebugUI:Refresh() end
end

local function lineStarts(source)
 local starts = { 0 }
 for offset in source:gmatch('()\n') do starts[#starts + 1] = offset end
 return starts
end
local function lineAt(starts, offset)
 local low, high = 1, #starts
 while low < high do
  local middle = math.floor((low + high + 1) / 2)
  if starts[middle] <= offset then low = middle else high = middle - 1 end
 end
 return low
end

function D:RemapBreakpoints(points, previous, source, edit)
 local mapped = {}
 if next(points) == nil then return mapped end
 if previous == source or type(previous) ~= 'string' then
  for line in pairs(points) do mapped[line] = true end
  return mapped
 end
 -- Removing a single newline joins two surviving lines; it is not deletion
 -- of the lower line's breakpoint, even when that line was empty.
 local joinAt = edit and edit.joinAt
 if type(joinAt) == 'number' and edit.oldSource == previous and joinAt >= 0
  and previous:sub(joinAt+1,joinAt+1) == '\n'
  and source == previous:sub(1,joinAt)..previous:sub(joinAt+2) then
  local joinedLine = lineAt(lineStarts(previous), joinAt)
  for line in pairs(points) do mapped[line > joinedLine and line-1 or line] = true end
  return mapped
 end
 local prefix, oldLength, newLength = 0, #previous, #source
 local limit = math.min(oldLength, newLength)
 while prefix < limit and previous:byte(prefix + 1) == source:byte(prefix + 1) do prefix = prefix + 1 end
 local suffix = 0
 while suffix < limit - prefix and previous:byte(oldLength - suffix) == source:byte(newLength - suffix) do suffix = suffix + 1 end
 -- A native Enter amid identical blank lines is otherwise indistinguishable
 -- from insertion at the end of their common prefix. The pre-key cursor pins it.
 local cursor = edit and edit.oldCursor
 if type(cursor) == 'number' and cursor >= 0 and cursor <= oldLength and newLength > oldLength
  and (not edit.oldSource or edit.oldSource == previous)
  and previous:sub(1, cursor) == source:sub(1, cursor)
  and previous:sub(cursor + 1) == source:sub(cursor + newLength - oldLength + 1) then
  prefix, suffix = cursor, oldLength - cursor
 end
 local oldEnd, newEnd = oldLength - suffix, newLength - suffix
 local oldStarts, newStarts = lineStarts(previous), lineStarts(source)
 local deletedFirst, deletedLast
 if #newStarts < #oldStarts then
  local function textAt(text, starts, line) return text:sub(starts[line] + 1, (starts[line + 1] or (#text + 1)) - 1) end
  local first = 1
  while first <= #newStarts and textAt(previous, oldStarts, first) == textAt(source, newStarts, first) do first = first + 1 end
  local oldLast, nextLast = #oldStarts, #newStarts
  while nextLast >= first and textAt(previous, oldStarts, oldLast) == textAt(source, newStarts, nextLast) do oldLast, nextLast = oldLast - 1, nextLast - 1 end
  if nextLast < first then deletedFirst, deletedLast = first, oldLast end
 end
 local oldFirst, newFirst = lineAt(oldStarts, prefix), lineAt(newStarts, prefix)
 local newLast = lineAt(newStarts, newEnd)
 local unique, counts = {}, {}
 for line = newFirst, newLast do
  local text = source:sub(newStarts[line] + 1, (newStarts[line + 1] or (#source + 1)) - 1):match('^%s*(.-)%s*$')
  if text ~= '' then counts[text] = (counts[text] or 0) + 1; unique[text] = line end
 end
 for line in pairs(points) do
  -- A whole removed line cannot retain a breakpoint on its deleted code.
  if not (deletedFirst and line >= deletedFirst and line <= deletedLast) then
  if not oldStarts[line] then mapped[math.max(1, line + #newStarts - #oldStarts)] = true
  else
   local finish = (oldStarts[line + 1] or (#previous + 1)) - 1
   local text = previous:sub(oldStarts[line] + 1, finish)
   local anchor = oldStarts[line] + #(text:match('^%s*') or '')
   local destination
   if anchor < prefix then destination = lineAt(newStarts, anchor)
   elseif anchor >= oldEnd then destination = lineAt(newStarts, math.max(0, anchor + newLength - oldLength))
   else
    local trimmed = text:match('^%s*(.-)%s*$')
    if trimmed ~= '' and counts[trimmed] == 1 then destination = unique[trimmed]
    elseif newEnd == prefix and prefix <= oldStarts[line] and oldEnd >= (oldStarts[line + 1] or oldLength) then
     destination = nil -- The complete anchored line was deleted.
    else destination = math.min(newLast, newFirst + math.max(0, line - oldFirst)) end
   end
   if destination then mapped[math.max(1, destination)] = true end
  end
  end
 end
 return mapped
end

function D:PersistBreakpoints(id)
 local db = addon.Workspace and addon.Workspace.db
 if not db then return end
 db.debugBreakpoints = db.debugBreakpoints or {}
 local points = self.breakpoints[id]
 if points and next(points) then
  local record = db.debugBreakpoints[id]
  if type(record) ~= 'table' then record = {}; db.debugBreakpoints[id] = record end
  record.source, record.points = self.breakpointSources[id] or '', points
 else db.debugBreakpoints[id] = nil end
end

function D:GetBreakpoints(id, source, edit)
 if not id then return {} end
 local db = addon.Workspace and addon.Workspace.db
 if db ~= self.breakpointDB then self.breakpointDB, self.loadedBreakpointRecords = db, {} end
 self.loadedBreakpointRecords = self.loadedBreakpointRecords or {}
 if db and not self.loadedBreakpointRecords[id] then
  self.loadedBreakpointRecords[id] = true
  local record = db.debugBreakpoints and db.debugBreakpoints[id]
  if type(record) == 'table' and type(record.source) == 'string' and type(record.points) == 'table' then
   local points = {}
   for line, enabled in pairs(record.points) do
    if type(line) == 'number' and line >= 1 and line == math.floor(line) and enabled == true then points[line] = true end
   end
   self.breakpoints[id], self.breakpointSources[id] = points, record.source
  end
 end
 if source and self.breakpointSources[id] and self.breakpointSources[id] ~= source then
  self.breakpoints[id] = self:RemapBreakpoints(self.breakpoints[id] or {}, self.breakpointSources[id], source, edit)
  self.breakpointRevision = (self.breakpointRevision or 0) + 1
 end
 if source then self.breakpointSources[id] = source end
 local points = self.breakpoints[id]
 if not points then points = {}; self.breakpoints[id] = points end
 self:PersistBreakpoints(id)
 return points
end

function D:RuntimeBreakpoints(id, source)
 local points = self:GetBreakpoints(id)
 if not source or source == self.breakpointSources[id] then return points end
 local snapshot = self.sources and self.sources[id]
 if snapshot and snapshot.runtimePoints and snapshot.pointRevision == self.breakpointRevision and snapshot.pointSource == self.breakpointSources[id] then return snapshot.runtimePoints end
 local mapped = self:RemapBreakpoints(points, self.breakpointSources[id], source)
 if snapshot then snapshot.runtimePoints, snapshot.pointRevision, snapshot.pointSource = mapped, self.breakpointRevision, self.breakpointSources[id] end
 return mapped
end

function D:RemoveBreakpoints(id)
 if not id then return end
 self.breakpoints[id], self.breakpointSources[id] = nil, nil
 if self.loadedBreakpointRecords then self.loadedBreakpointRecords[id] = nil end
 local db = addon.Workspace and addon.Workspace.db
 if db and db.debugBreakpoints then db.debugBreakpoints[id] = nil end
 self.breakpointRevision = (self.breakpointRevision or 0) + 1
end

function D:ToggleBreakpoint(id, line, source)
 if not id or type(line) ~= 'number' or line < 1 then return false end
 if self.armed and self.sources and self.sources[id] and source ~= self.sources[id].source then self:Stop() end
 local points = self:GetBreakpoints(id, source)
 points[line] = not points[line] or nil
 self.breakpointRevision = (self.breakpointRevision or 0) + 1
 self:PersistBreakpoints(id)
 self:Refresh()
 return points[line] == true
end

function D:Stop()
 self.startupOwnedId, self.startupTrigger = nil, nil
 self:CleanupCallbacks()
 self.generation = self.generation + 1
 self.failedYieldPending, self.budgetExceeded = nil, nil
 if self.events then self.events:UnregisterAllEvents() end
 self.thread, self.paused, self.running, self.armed = nil, nil, nil, nil
 self.queue, self.held = {}, nil
 self:ClearEvaluation(); self:CaptureVariables(nil)
 self.frames, self.environment, self.compiled, self.metadata, self.mode = nil, nil, nil, nil, nil
 self.line, self.depth, self.status, self.budgetPending, self.protectedDepth = nil, nil, nil, nil, nil
 self.sources, self.currentSourceId, self.activeContext = nil, nil, nil
 self.hookSourceId, self.hookEnvironment, self.environmentBuiltinSets, self.helperRegistry = nil, nil, nil, nil
 self:Refresh()
end

function D:Fail(value)
 if self.activeContext then self.activeContext.loading, self.activeContext.chain = {}, {} end
 P.Fail(self, value)
 if C.SetStatus then C:SetStatus(self.status, true) end
 self.frames, self.environment = nil, nil
end

function D:Hook(operation, ...)
 -- Functions retained by the script may run later from Blizzard callbacks or
 -- the terminal. Only the owned execution coroutine may suspend.
 if self.evaluating or not self.armed or coroutine.running() ~= self.thread then
  if operation == 'return' then return select(2, ...) end
  return
 end
 if self.budgetExceeded then error(L.debuggerBudgetExceeded, 0) end
 if self.protectedDepth then
  if operation == 'step' then
   self.instructions = self.instructions + 1
   if self.instructions > 1000000 then self.budgetExceeded = true; error(L.debuggerBudgetExceeded, 0) end
  end
  if operation == 'return' then return select(2, ...) end
  return
 end
 if self.failedYieldPending then error(L.debugUnsupportedYield, 0) end
 if operation == 'enter' then
  local frame = { depth = #self.frames + 1, sourceId = self.hookSourceId or self.scriptId, environment = self.hookEnvironment or self.environment }
  self.frames[#self.frames + 1] = frame
  return frame
 elseif operation == 'leave' or operation == 'return' then
  local frame = ...
  if frame then for index = #self.frames, frame.depth, -1 do self.frames[index] = nil end end
  if operation == 'return' then return select(2, ...) end
  return
 end
 local line, bindings, frame = ...
 self.instructions = self.instructions + 1
 self.slice = self.slice + 1
 if self.instructions > 1000000 then self.budgetExceeded = true; error(L.debuggerBudgetExceeded, 0) end
 if self.slice >= 1000 then
  self.slice = 0
  self.failedYieldPending = true
  coroutine.yield(self.budgetToken)
  self.failedYieldPending = nil
 end
 local depth = frame and frame.depth or 1
 for index = #self.frames, depth + 1, -1 do self.frames[index] = nil end
 local sourceId = frame and frame.sourceId or self.scriptId
 self.environment = frame and frame.environment or self.environment
 local stop = self:RuntimeBreakpoints(sourceId, self.sources[sourceId].source)[line] or self.mode == 'into'
  or (self.mode == 'over' and depth <= (self.stepDepth or 1))
 if not stop then return end
 self.line, self.depth, self.currentSourceId = line, depth, sourceId
 self.status = L.debugPaused .. ': ' .. line
 self.invocationEnvironment = self.environment
 self.capturedValues, self.evalToken, self.evaluationEnvironment = {}, {}, nil
 -- Include globals assigned in this script's environment, retaining lexical
 -- locals when the same name is shadowed.
 for name in pairs(self.environment) do
  if not secret(name) and type(name) == 'string' and name:match('^[%a_][%w_]*$') and not (self.environmentBuiltinSets[self.environment] or {})[name] and not bindings[name] then
   local key = name
   bindings[key] = { get = function() return rawget(self.environment, key) end,
    set = function(value) rawset(self.environment, key, value) end }
  end
 end
 self.checkpointBindings, self.liveBindings, self.evalOverlay, self.evalWritten = bindings, nil, nil, nil
 self.failedYieldPending = true
 coroutine.yield(self.checkpoint)
 self.failedYieldPending = nil
end

function D:Resume(...)
 local thread, generation = self.thread, self.generation
 local ok, value = coroutine.resume(thread, ...)
 if self.thread ~= thread or generation ~= self.generation then return end
 if not ok then self:Fail(value)
 elseif coroutine.status(thread) == 'dead' and self.budgetExceeded then self:Fail(L.debuggerBudgetExceeded)
 elseif coroutine.status(thread) == 'dead' and self.failedYieldPending then self:Fail(L.debugUnsupportedYield)
 elseif coroutine.status(thread) == 'dead' then
  -- Stepping belongs to this invocation, never to the next queued event.
  self.mode, self.stepDepth = 'continue', nil
  self.thread, self.paused, self.frames = nil, nil, nil
  self:CaptureVariables(nil); self:ClearEvaluation()
  self.status = self.callbacks and #self.callbacks > 0 and L.debugWaitingCallbacks or L.debugProbeFinished
 elseif not secret(value) and value == self.checkpoint then
  self.paused = true
  local valid, bindings = pcall(self.ValidateBindings, self)
  if valid then
   self.liveBindings = bindings
   self.evaluating = self.evalToken
   pcall(self.RefreshBoundVariables, self, self.evalToken, bindings)
   self.evaluating = nil
  else self:Fail(L.debugProbeBindingsError) end
 elseif not secret(value) and value == self.budgetToken then
  if not (_G.C_Timer and _G.C_Timer.After) then self:Fail(L.debuggerBudgetExceeded)
  else
   self.budgetPending = true
   _G.C_Timer.After(0, function()
    if generation ~= self.generation or self.thread ~= thread then return end
    self.budgetPending = nil; self:Resume(); self:Pump()
   end)
  end
 else self:Fail(L.debugProbeError) end
 self:Refresh()
end

function D:StartInvocation(item)
 local workspace = addon.Workspace
 if workspace and workspace.db and workspace.db.clearOnRun and workspace.db.clearOnRun[self.scriptId] then C:Clear() end
 local context = item.context or { cache = {}, loading = {}, chain = {} }
 self.activeContext = context
 local source = self.sources[item.sourceId or self.scriptId]
 local environment = item.environment or self:MakeEnvironment(source, context, item.event)
 if item.callback then environment.event = item.args[2] end
 local chunk, failure = item.callback
 if not chunk then
  chunk, failure = _G.loadstring(source.compiled, '=LuaWorkbench debugger [' .. tostring(source.id) .. ']')
  if not chunk then self:Fail(failure); return end
  _G.setfenv(chunk, environment)
 end
 self.failedYieldPending, self.budgetExceeded = nil, nil
 self.environment, self.frames, self.instructions, self.slice = environment, {}, 0, 0
 self.thread = coroutine.create(chunk)
 self:Resume(unpack(item.args, 1, item.args.n))
end

function D:MakeEnvironment(source, context, event)
 local generation = self.generation
 local function output(...)
  if generation ~= self.generation then return end
  if self.evaluating then self:TerminalWrite(...) else C:Write(...) end
 end
 local function devtools(value, startKey)
  if generation ~= self.generation then return end
  if self.evaluating then self:TerminalDump(value, startKey) else C:Dump(value, startKey) end
 end
 local function dump(...)
  local count = select('#', ...)
  for index = 1, count do local value = select(index, ...); devtools(value, count > 1 and ('arg[' .. index .. ']') or nil) end
 end
 local environment = setmetatable({ addon = addon, editor = addon, event = event,
  print = output, dump = dump, DevTools_Dump = devtools,
 }, { __index = _G })
 environment.requireHelper = function(name) return self:LoadHelper(context, name, event, generation) end
 environment[source.metadata.helperName] = function(operation, ...)
  if operation == 'method' then
   local receiver, method = ...
   local original = receiver[method]
   return function(...)
    if generation ~= self.generation or not self.armed then return original(receiver, ...) end
    return self:InstallCallback(receiver, method, original, source.id, environment, context, ...)
   end
  end
  if generation ~= self.generation then
   if operation == 'return' then return select(2, ...) end
   return
  end
  self.hookSourceId, self.hookEnvironment = source.id, environment
  return self:Hook(operation, ...)
 end
 local function pack(...) return { n = select('#', ...), ... } end
 local function protectedCall(api, ...)
  local previous, chainDepth = self.protectedDepth, #context.chain
  self.protectedDepth = (previous or 0) + 1
  local results = pack(_G.pcall(api, ...))
  self.protectedDepth = previous
  -- A caught helper initialization error must not poison later imports.
  while #context.chain > chainDepth do
   local id = table.remove(context.chain); context.loading[id] = nil
  end
  if not results[1] then error(results[2], 0) end
  return unpack(results, 2, results.n)
 end
 environment.pcall = function(...) return protectedCall(_G.pcall, ...) end
 environment.xpcall = function(...) return protectedCall(_G.xpcall, ...) end
 local builtins = {}
 for name in pairs(environment) do builtins[name] = true end
 self.environmentBuiltinSets[environment] = builtins
 return environment
end

function D:LoadHelper(context, name, event, generation)
 if generation ~= self.generation or not self.armed then error(L.debugProbeNotPaused, 0) end
 local _, key = addon.Helpers:Normalize(name)
 if not key then error(L.helperInvalidName, 0) end
 local module = self.helperRegistry[key]
 if module == false then error(L.helperDuplicate .. ' ' .. name, 0) end
 if not module then error(L.helperMissing .. ' ' .. name, 0) end
 if module.blockedSelf then error(L.helperCycle .. ' ' .. module.name, 0) end
 if context.cache[module.id] then return context.cache[module.id] end
 if context.loading[module.id] then error(L.helperCycle .. ' ' .. module.name, 0) end
 if not module.compiled then
  local compiled, metadata = addon.DebugCompiler:Compile(module.source)
  if not compiled then error(L.helperLoadError .. ' ' .. module.name .. ': ' .. metadata, 0) end
  module.compiled, module.metadata = compiled, metadata
  self:RuntimeBreakpoints(module.id, module.source)
 end
 local chunk, failure = _G.loadstring(module.compiled, '=LuaWorkbench debugger helper [' .. module.name .. ']')
 if not chunk then error(failure, 0) end
 local environment = self:MakeEnvironment(module, context, event)
 _G.setfenv(chunk, environment)
 context.loading[module.id] = true; context.chain[#context.chain + 1] = module.id
 -- Deliberately no protected call here: helper breakpoints must be able to
 -- suspend the same owned coroutine. Resume owns the error boundary.
 local value = chunk()
 table.remove(context.chain); context.loading[module.id] = nil
 if secret(value) or type(value) ~= 'table' then error(L.helperMustReturnTable .. ' ' .. module.name, 0) end
 context.cache[module.id] = value
 return value
end

function D:InstallCallback(receiver, method, original, sourceId, environment, context, ...)
 local function pack(...) return { n = select('#', ...), ... } end
 local arguments = pack(...)
 local event, callback = arguments[1], arguments[2]
 if arguments.n < 2 or secret(event) or secret(callback) or event ~= 'OnEvent' or (callback ~= nil and type(callback) ~= 'function') then return original(receiver, ...) end
 if method ~= 'SetScript' and method ~= 'HookScript' then return original(receiver, ...) end
 if not callback and method == 'HookScript' then return original(receiver, ...) end
 if type(receiver.GetScript) ~= 'function' then return original(receiver, ...) end
 local generation = self.generation
 local record = { receiver = receiver, method = method, callback = callback, sourceId = sourceId, environment = environment, context = context }
 if method == 'SetScript' then record.previous = receiver:GetScript(event) end
 record.wrapper = callback and function(...)
  if generation ~= self.generation or not self.armed or not record.callback then return end
  if #self.queue >= 50 then self.dropped = self.dropped + 1; self:Refresh(); return end
  self.queue[#self.queue + 1] = { callback = record.callback, sourceId = record.sourceId, environment = record.environment,
   context = record.context, args = { n = select('#', ...), ... } }
  self:Pump(); self:Refresh()
 end
 arguments[2] = record.wrapper
 local results = pack(original(receiver, unpack(arguments, 1, arguments.n)))
 self.callbacks[#self.callbacks + 1] = record
 return unpack(results, 1, results.n)
end

function D:CleanupCallbacks()
 for index = #(self.callbacks or {}), 1, -1 do
  local record = self.callbacks[index]
  if record.method == 'SetScript' then
   local ok, current = pcall(record.receiver.GetScript, record.receiver, 'OnEvent')
   if ok and current == record.wrapper then pcall(record.receiver.SetScript, record.receiver, 'OnEvent', record.previous) end
  end
  record.callback, record.environment, record.context, record.receiver, record.previous = nil, nil, nil, nil, nil
 end
 self.callbacks = {}
end

function D:CurrentSource() return self.sources and self.sources[self.currentSourceId or self.scriptId] end

function D:Start(id, source, eventList, managedEvents)
 self:Stop()
 if C.SetStatus then C:SetStatus(nil) end
 local compiled, metadata = addon.DebugCompiler:Compile(source)
 if not compiled then self:Fail(metadata); return false end
 self.scriptId, self.source, self.compiled, self.metadata = id, source, compiled, metadata
 self.sources = { [id] = { id = id, name = addon.Workspace.db and addon.Workspace.db.snippets and addon.Workspace.db.snippets[id] and addon.Workspace.db.snippets[id].name or tostring(id), source = source, compiled = compiled, metadata = metadata } }
 self.currentSourceId, self.helperRegistry = id, {}
 self.environmentBuiltinSets = setmetatable({}, { __mode = 'k' })
 local db = addon.Workspace and addon.Workspace.db
 if db and addon.Helpers then
  for helperId, options in pairs(db.helperModules or {}) do
   local _, key = addon.Helpers:Normalize(options.name)
   local saved = db.snippets[helperId]
   if options.enabled and key and saved then
    local module = { id = helperId, name = options.name, source = addon.Workspace:NormalizeSource(saved.source) }
    if helperId == id then module.blockedSelf = true else self.sources[helperId] = module end
    if self.helperRegistry[key] ~= nil then self.helperRegistry[key] = false else self.helperRegistry[key] = module end
   end
  end
 end
 self.eventSet = {}
 for _, name in ipairs(eventList or {}) do
  local event = addon.Automation:ValidateEvent(name)
  if not event then self:Fail(L.invalidEvent); return false end
  self.eventSet[event] = true
 end
 self.checkpoint, self.budgetToken = {}, {}
 self.dropped, self.terminalLines = 0, {}
 local points = self:GetBreakpoints(id, source)
 local hasValidPoint = false
 for line in pairs(points) do if metadata.lines[line] then hasValidPoint = true; break end end
 self.mode = hasValidPoint and 'continue' or 'into'
 if self.terminal then self.terminal.output:SetText(''); self.terminal.input:SetText('') end
 if not self.events then
  self.events = CreateFrame('Frame')
  self.events:SetScript('OnEvent', function(_, event, ...) self:Enqueue(event, ...) end)
 end
 if not managedEvents then
  for event in pairs(self.eventSet) do
   local ok, result = pcall(self.events.RegisterEvent, self.events, event)
   if not ok or result == false then self.events:UnregisterAllEvents(); self:Fail(L.invalidEvent); return false end
  end
 end
 self.armed, self.status = true, L.debugProbeWaiting
 if not next(self.eventSet) then self:Enqueue(nil) end
 self:Refresh()
 return true
end

-- Only one saved script can own the next startup session.
function D:ScheduleStartup(id, event, persistent)
 local workspace = addon.Workspace
 if event ~= 'ADDON_LOADED' and event ~= 'PLAYER_LOGIN' then return false end
 if not workspace.db.snippets[id] then C:SetStatus(L.saveBeforeAutoRun, true); return false end
 workspace.db.startupDebug = { id = id, event = event, persistent = persistent == true }
 C:SetStatus(L.debugScheduleMenu .. ': ' .. workspace.db.snippets[id].name .. ' / ' .. event)
 return true
end

function D:RestoreStartup()
 local workspace = addon.Workspace
 local plan = workspace.db.startupDebug
 if plan == nil then return end
 if type(plan) ~= 'table' or (plan.event ~= 'ADDON_LOADED' and plan.event ~= 'PLAYER_LOGIN')
  or type(plan.id) ~= 'string' or not workspace.db.snippets[plan.id] then
  workspace.db.startupDebug = nil
  return
 end
 local saved = workspace.db.snippets[plan.id]
 -- Consume before compiling or running, so a failed once-only session cannot loop on reload.
 if plan.persistent ~= true then workspace.db.startupDebug = nil end
 if addon.DebugUI then addon.DebugUI.drawerOpen = true end
 workspace:Show(false)
 workspace:Select(plan.id)
 workspace:Minimize()
 if C.input then C.input:ClearFocus() end
 local started = self:Start(plan.id, workspace:NormalizeSource(saved.source), { plan.event }, true)
 -- Even compile failure must not fall back to an uninstrumented automatic run.
 self.startupOwnedId = plan.id
 if started then self.startupTrigger = plan.event end
 self:Refresh()
end

function D:DispatchStartup(event, startup, ...)
 if not self.armed or event ~= self.startupTrigger then return end
 if event == 'ADDON_LOADED' and not startup then return end
 self.startupTrigger = nil
 return self:Enqueue(event, ...)
end

function D:Enqueue(event, ...)
 if not self.armed or (event ~= nil and not self.eventSet[event]) then return false end
 if #self.queue >= 50 then self.dropped = self.dropped + 1; self:Refresh(); return false end
 self.queue[#self.queue + 1] = { event = event, args = { n = select('#', ...), ... } }
 self:Pump(); self:Refresh()
 return true
end

function D:Advance(mode)
 if self.evaluating or not self.paused or not self.thread then return false end
 self.mode, self.stepDepth, self.paused = mode, self.depth, nil
 self:ClearEvaluation(); self:Resume(); self:Pump()
 return true
end
function D:Continue() return self:Advance('continue') end
function D:StepInto() return self:Advance('into') end
function D:StepOver() return self:Advance('over') end
function D:Step() return self:StepOver() end

function D:ResolveVariable(path)
 if not self.paused or type(path) ~= 'string' or not path:match('^[%a_][%w_%.]*$') or path:find('%.%.') or path:sub(-1) == '.' then return nil, false end
 local head = path:match('^[%a_][%w_]*')
 local binding = self.liveBindings and self.liveBindings[head]
 local value
 if binding then
  local ok; ok, value = pcall(binding.get)
  if not ok then return nil, false end
 elseif self.evalWritten and self.evalWritten[head] then value = self.evalOverlay[head]
 else
  value = self.environment and rawget(self.environment, head)
  if not secret(value) and value == nil then value = rawget(_G, head) end
  if not secret(value) and value == nil then return nil, false end
 end
 for key in path:sub(#head + 1):gmatch('%.([%a_][%w_]*)') do
  if secret(value) or type(value) ~= 'table' then return nil, false end
  local ok; ok, value = pcall(rawget, value, key)
  if not ok then return nil, false end
 end
 return value, true
end

function D:BuildPanel() if addon.DebugUI then addon.DebugUI:ShowDrawer() end end
function D:ShowTerminal() if addon.DebugUI then addon.DebugUI:ShowDrawer() end end
function D:ShowSnapshot() if addon.DebugUI then addon.DebugUI:ShowLocation() end end

function D:SourceChanged(id, source, edit)
 if not id then return end
 self:GetBreakpoints(id, source, edit)
 if self.armed and self.sources and self.sources[id] and self.sources[id].source ~= source then self:Stop() end
 self:Refresh()
end

-- Keep inspector collection independent of pooled UI rows. Nil locals need a
-- record of their own rather than a values table, which would discard them.
function D:VariableRecord(name, value)
 return { name = name, value = P:FormatScalar(value), preview = P:FormatPreview(value),
  hasSecretText = secret(value) and (type(value) == 'string' or type(value) == 'number'), secretText = value }
end

function D:CaptureVariables(values)
 self.variables = {}
 if secret(values) or type(values) ~= 'table' then return end
 local key, records = nil, {}
 while true do
  local ok, name, value = pcall(next, values, key)
  if not ok or secret(name) or name == nil then break end
  key = name
  if type(name) == 'string' then records[#records + 1] = self:VariableRecord(name, value) end
 end
 table.sort(records, function(a, b) return a.name < b.name end)
 for index = 1, math.min(#records, 200) do self.variables[index] = records[index] end
end

function D:RefreshBoundVariables(token, bindings, overlay, written)
 local names, known = {}, {}
 local function collect(source)
  if secret(source) or type(source) ~= 'table' then return end
  local key
  while true do
   local ok, name = pcall(next, source, key)
   if not ok or secret(name) or name == nil then break end
   key = name
   if type(name) == 'string' and not known[name] then known[name] = true; names[#names + 1] = name end
  end
 end
 collect(bindings); collect(written); collect(self.capturedValues)
 table.sort(names)
 local records = {}
 for index = 1, math.min(#names, 200) do
  local name, value = names[index], nil
  local binding = rawget(bindings, name)
  if binding then
   local ok; ok, value = pcall(binding.get)
   if not ok then value = L.debugProbeError end
  elseif written and rawget(written, name) then value = rawget(overlay, name)
  elseif not secret(self.capturedValues) and type(self.capturedValues) == 'table' then value = rawget(self.capturedValues, name) end
  if self.evalToken ~= token or not self.paused then return end
  records[#records + 1] = self:VariableRecord(name, value)
 end
 self.variables = records
end

function D:Evaluate(source)
 local result = P.Evaluate(self, source)
 self:Refresh()
 return result
end

end
rm.LuaWorkbenchModules.DebugUI=function(_,addon)
local W, UI, L, C = addon.Workspace, addon.UI, addon.L, addon.Query.Console
local U = { gutterButtons = {} }
addon.DebugUI = U

-- Temporary opt-in hover diagnostics. Never collect source, names or values.
function U:TraceHover(reason, ...)
 local trace = self.hoverTrace
 if not trace then return end
 local fields = { reason }
 for index = 1, select('#', ...) do
  local value = select(index, ...)
  if _G.issecretvalue and _G.issecretvalue(value) then fields[#fields + 1] = '<secret>'
  elseif type(value) == 'boolean' then fields[#fields + 1] = value and '1' or '0'
  elseif type(value) == 'number' then fields[#fields + 1] = string.format('%.2f', value)
  elseif value == nil then fields[#fields + 1] = '-'
  else fields[#fields + 1] = '?' end
 end
 local text = table.concat(fields, ' ')
 local now = _G.GetTime and _G.GetTime() or 0
 local last = trace.rows[#trace.rows]
 if last and last.text == text then last.count, last.last = last.count + 1, now
 else
  trace.rows[#trace.rows + 1] = { text = text, count = 1, first = now, last = now }
  if #trace.rows > 200 then table.remove(trace.rows, 1); trace.dropped = trace.dropped + 1 end
 end
end

function U:HoverTraceCommand(message)
 local command = (message or ''):match('^%s*(.-)%s*$'):lower()
 if command == 'on' then
  self.hoverTrace = { rows = {}, dropped = 0 }
  self:TraceHover('enabled', addon.Debugger.paused == true)
 elseif command == 'off' then self.hoverTrace = nil
 elseif command == 'dump' then
  local trace = self.hoverTrace
  self.hoverTrace = nil -- Freeze the report before writing to the output UI.
  C:Write('HoverTrace v5 rows=' .. (trace and #trace.rows or 0) .. ' dropped=' .. (trace and trace.dropped or 0))
  if trace then
   for _, row in ipairs(trace.rows) do C:Write(string.format('%.2f-%.2f x%d %s', row.first, row.last, row.count, row.text)) end
  end
  return
 else command = 'on | off | dump' end
 C:SetStatus(L.debugTitle .. ': /lwhover ' .. command)
end

if not addon.embedded then
_G.SLASH_LUAWORKBENCHHOVER1 = '/lwhover'
_G.SlashCmdList.LUAWORKBENCHHOVER = function(message) U:HoverTraceCommand(message) end
