function U:UpdateVariables()
 local D = addon.Debugger
 if not self.variableContent or self.renderedVariables == D.variables then return end
 self.renderedVariables = D.variables
 self:TraceHover('inspector-rebuild')
 for index, item in ipairs(D.variables or {}) do
  local row = D.variableRows[index]
  if not row then
   row = CreateFrame('Button', nil, self.variableContent)
   row:SetPoint('TOPLEFT', 0, -(index - 1) * 22); row:SetPoint('RIGHT', 0, 0); row:SetHeight(22)
   row.text = UI:Text(row, '', 11); row.text:SetAllPoints(); row.text:SetWordWrap(false)
   row:SetScript('OnEnter', function() self:ValueTooltip(row, row.preview, row.hasSecretText, row.secretText, row.secretLabel) end)
   row:SetScript('OnLeave', function()
    self:TraceHover('inspector-leave', row:IsMouseOver(), row:IsShown(), row:GetWidth(), row:GetHeight())
    self:HideTooltip(row, 'inspector-leave')
   end)
   D.variableRows[index] = row
  end
  row.text:SetText((item.name .. ' = ' .. item.value):gsub('|', '||'))
  row.preview = (item.name .. ' = ' .. item.preview):gsub('|', '||')
  row.secretLabel = item.name:gsub('|', '||') .. ' = |cff88ff88<secret>|r'
  row.hasSecretText, row.secretText = item.hasSecretText, item.secretText
  row.variableName = item.name
  row:RegisterForClicks('LeftButtonUp', 'RightButtonUp')
  row:SetScript('OnClick', function(_, button)
   if button == 'RightButton' and addon.Inspector and addon.Inspector:Readable(row.secretText) then
    W:OpenMenu(row, { { text = L.inspectorTitle, action = function() addon.Inspector:Show(row.secretText, row.variableName) end } })
   end
  end)
  row:Show()
 end
 for index = #(D.variables or {}) + 1, #D.variableRows do
  local row = D.variableRows[index]; row:Hide(); row.secretText, row.hasSecretText = nil, nil
 end
 self.variableContent:SetHeight(math.max(1, #(D.variables or {}) * 22))
 self.variableScroll:UpdateScrollChildRect()
end

function U:APITooltip(owner, text)
 self:HideTooltip(nil, 'api-show')
 if not self.apiTooltip then
  local panel = CreateFrame('Frame', nil, UIParent)
  self.apiTooltip = panel
  panel:SetFrameStrata('TOOLTIP'); panel:SetClampedToScreen(true); panel:EnableMouse(false)
  UI:Background(panel, UI.colors.background); UI:Border(panel, { 0.45, 0.5, 0.6, 1 })
  panel.text = UI:Text(panel, '', 12)
  panel.text:SetPoint('TOPLEFT', 8, -8)
  panel.text:SetJustifyH('LEFT'); panel.text:SetJustifyV('TOP'); panel.text:SetNonSpaceWrap(true)
  panel.text:SetSpacing(2)
 end
 local panel = self.apiTooltip
 local label = panel.text
 label:SetHeight(0); label:SetWidth(0); label:SetWordWrap(false); label:SetText(text or '')
 local availableWidth = math.max(40, UIParent:GetWidth() - 32)
 local width = math.min(420, availableWidth, math.max(220, label:GetStringWidth() + 16))
 label:SetWordWrap(true); label:SetWidth(width - 16)
 local height = math.min(label:GetStringHeight() + 16, math.max(32, UIParent:GetHeight() - 32))
 label:SetHeight(height - 16); panel:SetSize(width, height)
 local x, y = GetCursorPosition(); local scale = UIParent:GetEffectiveScale()
 panel:ClearAllPoints(); panel:SetPoint('BOTTOMLEFT', UIParent, 'BOTTOMLEFT', x / scale + 16, y / scale + 20)
 panel:Show()
 self.tooltipOwner, self.tooltipVisible, self.tooltipAPI = owner, true, true
end

function U:ValueTooltip(owner, text, hidden, value, secretLabel)
 if self.apiTooltip then self.apiTooltip:Hide() end
 local key = hidden and 'secretValueTooltip' or 'plainValueTooltip'
 local tooltip = self[key]
 if not tooltip then
  if hidden then
   tooltip = CreateFrame('GameTooltip', (not addon.embedded and 'LuaWorkbenchDebugValueTooltip' or nil), UIParent, 'GameTooltipTemplate')
  else
   tooltip = CreateFrame('Frame', nil, UIParent)
   tooltip:SetFrameStrata('TOOLTIP')
   UI:Background(tooltip, UI.colors.background); UI:Border(tooltip, { 0.7, 0.55, 0.25, 1 })
   tooltip.text = UI:Text(tooltip, '', 12)
   tooltip.text:SetPoint('TOPLEFT', 8, -8)
   tooltip.text:SetJustifyH('LEFT'); tooltip.text:SetJustifyV('TOP')
   tooltip.text:SetNonSpaceWrap(true)
  end
  self[key] = tooltip
  tooltip:SetClampedToScreen(true); tooltip:EnableMouse(false)
  tooltip:HookScript('OnShow', function() self:TraceHover('tooltip-show') end)
  tooltip:HookScript('OnHide', function() self:TraceHover('tooltip-hide') end)
 end
 if self.valueTooltip and self.valueTooltip ~= tooltip then self.valueTooltip:Hide() end
 self.valueTooltip = tooltip
 self.tooltipAPI = nil
 self:TraceHover('show-request', owner == C.input.editBox, hidden == true)
 self.tooltipOwner = owner
 if owner ~= C.input.editBox then self.hoverPath, self.hoverToken = nil, nil end
 if hidden then tooltip:SetOwner(owner, 'ANCHOR_NONE'); tooltip:ClearLines() end
 -- Keep the popup clear of the pointer and independent of other UI tooltips.
 local x, y = GetCursorPosition(); local scale = UIParent:GetEffectiveScale()
 tooltip:ClearAllPoints(); tooltip:SetPoint('BOTTOMLEFT', UIParent, 'BOTTOMLEFT', x / scale + 16, y / scale + 20)
 if hidden then
  addon.DebugProbe:SecretTooltip(tooltip, secretLabel, value)
 else
  local label = tooltip.text
  label:SetHeight(0); label:SetWidth(0); label:SetWordWrap(false)
  label:SetText((text or ''):gsub('<secret>', '|cff88ff88<secret>|r'))
  label:SetTextColor(0.85, 0.9, 1)
  local width = math.min(480, math.max(40, UIParent:GetWidth() - 32), math.max(220, label:GetStringWidth() + 16))
  label:SetWordWrap(true); label:SetWidth(width - 16)
  local height = math.min(label:GetStringHeight() + 16, math.max(32, UIParent:GetHeight() - 32))
  label:SetHeight(height - 16); tooltip:SetSize(width, height)
 end
 tooltip:Show(); self.tooltipVisible = true
 self:TraceHover('shown', tooltip:IsShown(), tooltip:IsVisible(), tooltip:GetAlpha(), tooltip:GetEffectiveAlpha())
end

function U:HideTooltip(owner, reason)
 if owner and self.tooltipOwner ~= owner then return end
 if self.valueTooltip and self.valueTooltip:IsShown() then self:TraceHover(reason or 'hide-unspecified'); self.valueTooltip:Hide() end
 if self.apiTooltip then self.apiTooltip:Hide() end
 self.tooltipVisible, self.tooltipOwner, self.hoverPath, self.hoverToken, self.tooltipAPI = nil, nil, nil, nil, nil
end

function U:Layout()
 if not self.toolbar then return end
 local D, input = addon.Debugger, C.input
 local active = D.armed == true
 self.toolbar:SetShown(active)
 local find = W.findBar and W.findBar:IsShown()
 local top = (find and 96 or 56) + (active and 32 or 0)
 input.scrollBG:SetPoint('TOPLEFT', input.frame, 'TOPLEFT', 6, -top)
 if W.findBar then W.findBar:SetPoint('TOPRIGHT', input.frame, 'TOPRIGHT', -10, active and -88 or -56) end
 local height = math.min(200, math.max(100, input.frame:GetHeight() * 0.42))
 local drawer = active and self.drawerOpen and input.frame:GetHeight() - top - height >= 55
 self.dock:SetShown(drawer == true)
 self.dock:SetHeight(height)
 self.terminalOutput.frame:SetWidth(math.max(180, input.frame:GetWidth() * 0.62 - 16))
 input.scrollBG:SetPoint('BOTTOMRIGHT', input.frame, 'BOTTOMRIGHT', -16, drawer and height + 8 or 8)
end

function U:Refresh()
 if not self.toolbar then return end
 local D = addon.Debugger
 local active = D.armed == true
 local canStop = active or D.startupOwnedId ~= nil
 self.playButton:SetShown(not canStop); self.stopButton:SetShown(canStop)
 UI:ButtonColor(W.debugButton, active and { 0.4, 0.88, 0.58, 1 } or { 1, 0.7, 0.3, 1 })
 if self.layoutArmed ~= D.armed then self.layoutArmed = D.armed; W:Layout() end
 self.status:SetText(((D.status or L.debugTitle) .. '  ·  ' .. string.format(L.debugProbeQueue, #D.queue)):gsub('|', '||'))
 if D.dropped > 0 then self.status:SetText(self.status:GetText() .. '  ·  ' .. string.format(L.debugProbeOverflow, D.dropped)) end
 for index = 1, 3 do self.buttons[index]:SetEnabled(D.paused == true) end
 self.buttons[6]:SetEnabled(D.paused == true)
 self.terminalInput:SetEnabled(D.paused == true)
 self:UpdateVariables(); self:Layout(); self:UpdateMinibar(); C:UpdateLineNumbers()
 if not D.paused then if not self.tooltipAPI then self:HideTooltip(nil, 'not-paused') end; if self.snapshot then self.snapshot:Hide() end end
 if D.paused and self.pauseToken ~= D.evalToken then
  self.pauseToken = D.evalToken
  if W.window:IsShown() and not W.minimized then self:ShowLocation(false) end
 end
end

function U:ShowDrawer()
 self.drawerOpen = true
 self:ShowLocation(); self:Layout()
 if self.terminalInput then self.terminalInput:SetFocus() end
end

function U:CurrentSource()
 local D = addon.Debugger
 return D.CurrentSource and D:CurrentSource() or { id = D.scriptId, source = D.source }
end

function U:ShowSourceSnapshot(record, offset, focus)
 if not self.snapshot then
  local panel = CreateFrame('Frame', nil, W.window); self.snapshot = panel
  panel:SetSize(math.min(640, UIParent:GetWidth() - 32), math.min(420, UIParent:GetHeight() - 32))
  panel:SetPoint('CENTER'); panel:SetFrameLevel(W.window:GetFrameLevel() + 55); panel:EnableMouse(true)
  UI:MovablePanel(panel, 'debugSnapshot'); panel:RestorePanelPosition()
  UI:Background(panel, UI.colors.panel); UI:Border(panel, { 0.28, 0.34, 0.43, 1 })
  self.snapshotTitle = UI:Text(panel, '', 12)
  self.snapshotTitle:SetPoint('TOPLEFT', 12, -12); self.snapshotTitle:SetPoint('RIGHT', -40, 0)
  local close = UI:Button(panel, 'close', _G.CLOSE, function() panel:Hide() end); close:SetPoint('TOPRIGHT', -4, -4)
  local hint = UI:Text(panel, L.debugSnapshotHelp, 11)
  hint:SetPoint('TOPLEFT', 12, -38); hint:SetPoint('TOPRIGHT', -12, -38); hint:SetHeight(42); hint:SetWordWrap(true)
  local input = UI:Editor(panel, L.debugSnapshot, true); self.snapshotInput = input
  input.frame:SetPoint('TOPLEFT', 8, -82); input.frame:SetPoint('BOTTOMRIGHT', -8, 8)
  -- Use the syntax renderer without attaching the editable input handlers.
  local overlay = input.editBox:CreateFontString(nil, 'OVERLAY')
  overlay:SetJustifyH('LEFT'); overlay:SetJustifyV('TOP'); overlay:SetWordWrap(true); overlay:SetNonSpaceWrap(true)
  input.queryEditor = { overlay = overlay }; input.editBox:SetTextColor(0, 0, 0, 0)
  input.editBox:HookScript('OnUpdate', function(_, elapsed)
   addon.Query.Editor:Paint(input); self:PaintSnapshotLine(); self:HoverUpdate(elapsed, input, self.snapshotRecord)
  end)
  input.editBox:HookScript('OnKeyDown', function(_, key) self:Shortcut(key) end)
  input.editBox:HookScript('OnKeyUp', function(_, key) self:KeyUp(key) end)
  panel:HookScript('OnHide', function() input:ClearFocus(); self:HideTooltip(input.editBox, 'snapshot-hidden') end)
 end
 self.snapshotRecord = record
 self.snapshotLine = addon.Debugger.line
 self.snapshotTitle:SetText((L.debugSnapshot .. ': ' .. (record.name or tostring(record.id))):gsub('|', '||'))
 self.snapshotInput:SetText(record.source)
 addon.Query.Editor:Paint(self.snapshotInput); self:PaintSnapshotLine()
 self.snapshot:Show()
 addon.Navigation:Position(self.snapshotInput, offset, focus)
 local last = (record.source:find('\n', offset + 1, true) or (#record.source + 1)) - 1
 self.snapshotInput:HighlightText(offset, last)
end

function U:PaintSnapshotLine()
 local input, record = self.snapshotInput, self.snapshotRecord
 if not input or not record or not self.snapshotLine then return end
 local box = input.editBox
 if not self.snapshotMeasure then
  self.snapshotMeasure = box:CreateFontString(nil, 'OVERLAY')
  self.snapshotMeasure:SetWordWrap(true); self.snapshotMeasure:SetNonSpaceWrap(true); self.snapshotMeasure:Hide()
  self.snapshotHighlight = box:CreateTexture(nil, 'BACKGROUND')
  self.snapshotHighlight:SetColorTexture(1, 0.7, 0.15, 0.15)
 end
 local font, size, flags = box:GetFont()
 local width, spacing = box:GetWidth(), box:GetSpacing()
 local cache = self.snapshotMeasureCache
 if cache and cache.record == record and cache.line == self.snapshotLine and cache.font == font and cache.size == size and cache.flags == flags and cache.width == width and cache.spacing == spacing then return end
 self.snapshotMeasureCache = { record = record, line = self.snapshotLine, font = font, size = size, flags = flags, width = width, spacing = spacing }
 local measure, offset, height, line = self.snapshotMeasure, 0, size + spacing, 1
 measure:SetFont(font, size, flags); measure:SetSpacing(spacing); measure:SetWidth(math.max(1, width))
 for text in (record.source .. '\n'):gmatch('(.-)\n') do
  measure:SetText(text ~= '' and text:gsub('|', '||') or ' ')
  height = math.max(size + spacing, measure:GetStringHeight())
  if line == self.snapshotLine then break end
  offset, line = offset + height, line + 1
 end
 self.snapshotHighlight:ClearAllPoints(); self.snapshotHighlight:SetPoint('TOPLEFT', box, 'TOPLEFT', 0, -offset)
 self.snapshotHighlight:SetSize(width, height); self.snapshotHighlight:Show()
end

function U:ShowLocation(focus)
 local D, record = addon.Debugger, self:CurrentSource()
 if not record or not record.id or not record.source then return end
 W:Show(focus ~= false)
 local offset = 0
 for _ = 2, D.line or 1 do local stop = record.source:find('\n', offset + 1, true); if not stop then break end; offset = stop end
 local displayed = W.current == record.id and C.source or nil
 local stored = W.db.drafts[record.id] or W.db.snippets[record.id]
 if not displayed and stored then displayed = W:NormalizeSource(stored.source) end
 if displayed ~= record.source then self:ShowSourceSnapshot(record, offset, focus); return end
 if self.snapshot then self.snapshot:Hide() end
 if W.current ~= record.id then W:Select(record.id) end
 addon.Navigation:Position(C.input, offset, focus)
end

function U:UpdateMinibar()
 local bar, D = W.minibar, addon.Debugger
 if not bar then return end
 if not self.mini then
  self.mini = UI:Action(bar, 'debug', L.debugPaused, L.debugShow, function()
   C.input:ClearFocus()
   if self.terminalInput then self.terminalInput:ClearFocus() end
   if self.snapshotInput then self.snapshotInput:ClearFocus() end
   self:ShowLocation(false)
  end)
  self.mini:SetPoint('TOPLEFT', bar, 'BOTTOMLEFT', 0, -2); self.mini:SetPoint('RIGHT', bar, 'RIGHT', 0, 0)
  UI:Background(self.mini, { 0.28, 0.18, 0.07, 1 })
 end
 self.mini:SetShown(D.paused == true)
end

function U:SourceChanged(source)
 local D = addon.Debugger
 if W.selecting then return end
 local registered = D.sources and D.sources[W.current]
 local stopped = D.armed and ((registered and registered.source ~= source) or (D.scriptId == W.current and source ~= D.source))
 local state = C.input and C.input.queryEditor
 local edit = state and state.breakpointEdit
 if state then state.breakpointEdit = nil end
 if edit and edit.expectedSource and edit.expectedSource ~= source then edit = nil end
 if W.current then D:SourceChanged(W.current, source, edit) end
 if stopped then C:SetStatus(L.debugSourceChanged, true) end
 self:HideTooltip(nil, 'source-changed')
end

function U:Shortcut(key)
 local D = addon.Debugger
 if not W.window or not W.window:IsShown() then return false end
 if IsControlKeyDown() or (_G.IsAltKeyDown and IsAltKeyDown()) or (_G.IsMetaKeyDown and _G.IsMetaKeyDown()) then return false end
 local focused = W.window:IsMouseOver() or C.input.editBox:HasFocus() or (self.terminalInput and self.terminalInput:HasFocus()) or (self.snapshot and self.snapshot:IsShown() and self.snapshotInput.editBox:HasFocus())
 if not focused then return false end
 if key == 'F9' and not IsShiftKeyDown() then
  if self.snapshot and self.snapshot:IsShown() and self.snapshotInput.editBox:HasFocus() then
   if not self.held then
    self.held = key
    local record = self.snapshotRecord
    D:ToggleBreakpoint(record.id, C:GetLinePosition(record.source, self.snapshotInput.editBox:GetCursorPosition()), record.source)
   end
   return true
  end
  if not self.held then self.held = key; self:ToggleLine(C:GetLinePosition(C.source, C.input.editBox:GetCursorPosition())) end
  return true
 end
 if not D.armed then return false end
 local action
 if key == 'F5' then action = IsShiftKeyDown() and D.Stop or D.Continue
 elseif key == 'F10' and not IsShiftKeyDown() then action = D.StepOver
 elseif key == 'F11' and not IsShiftKeyDown() then action = D.StepInto end
 if not action then return false end
 if not self.held then self.held = key; action(D) end
 return true
end

function U:KeyUp(key) if self.held == key then self.held = nil end end

function U:UpdateGutter(state, visible)
 local D = addon.Debugger
 local registered = D.armed and D.sources and D.sources[W.current]
 local differentDraft = registered and registered.source ~= C.source
 local points = W.current and not differentDraft and D:GetBreakpoints(W.current, C.source) or {}
 local record = self:CurrentSource()
 local paused = D.paused and record and record.id == W.current and record.source == C.source and D.line
 for index, entry in ipairs(visible) do
  local button = self.gutterButtons[index]
  if not button then
   button = CreateFrame('Button', nil, state.gutter); self.gutterButtons[index] = button
   button:SetFrameLevel(state.gutter:GetFrameLevel() + 3)
   button.dot = UI:Dot(button, 7); button.dot:SetColorTexture(1, 0.3, 0.3, 1)
   button.arrow = UI:Text(button, '>', 12); button.arrow:SetPoint('RIGHT', button.dot, 'LEFT', -3, 0); button.arrow:SetTextColor(1, 0.8, 0.2)
   button:SetScript('OnClick', function() self:ToggleLine(button.line) end)
   UI:Tooltip(button, L.debugBreakpoint)
  end
  button.line = entry.line
  button:ClearAllPoints(); button:SetPoint('TOPLEFT', state.gutter, 'TOPLEFT', 0, entry.y)
  button:SetSize(state.gutter:GetWidth(), entry.height); button:Show()
  -- Line numbers are top-aligned; spacing and wrapped-line height do not
  -- belong to the glyph centre used for the marker.
  button.dot:ClearAllPoints()
  button.dot:SetPoint('RIGHT', button, 'TOPRIGHT', -2 - state.numberWidth - 5, -entry.textHeight / 2)
  button.dot:SetShown(points[entry.line] == true); button.arrow:SetShown(paused == entry.line)
 end
 for index = #visible + 1, #self.gutterButtons do self.gutterButtons[index]:Hide() end
 if self.pausedLine then
  local position = paused and state.positions[paused]
  self.pausedLine:SetShown(position ~= nil)
  if position then
   self.pausedLine:ClearAllPoints(); self.pausedLine:SetPoint('TOPLEFT', C.input.editBox, 'TOPLEFT', 0, -position.offset)
   self.pausedLine:SetWidth(C.input.editBox:GetWidth()); self.pausedLine:SetHeight(position.height)
  end
 end
end

-- Resolve only names and raw dotted fields; hovering never evaluates Lua expressions.
function U:HoverPath(source, position)
 if self.tokenSource ~= source then self.tokenSource, self.hoverTokens = source, addon.Query.Editor:Tokenize(source) end
 local tokens = self.hoverTokens
 for index, token in ipairs(tokens) do
  if position >= token.start and position <= token.finish and (token.kind == 'identifier' or token.kind == 'call') then
   local first = index
   while first > 2 and tokens[first - 1].text == '.' and (tokens[first - 2].kind == 'identifier' or tokens[first - 2].kind == 'call') do first = first - 2 end
   local path = source:sub(tokens[first].start, token.finish)
   return path
  end
 end
end

function U:HoverUpdate(elapsed, target, record)
 if addon.Inspector and addon.Inspector.picking then
  self:HideTooltip(nil, 'frame-picker'); return
 end
 local D, input = addon.Debugger, target or C.input
 record = record or (D.paused and self:CurrentSource())
 local source = target and record and record.source or C.source
 local matches = record and (target or record.id == W.current) and record.source == source
 -- A scroll child's geometric bounds may extend behind the inspector.
 if self.tooltipOwner and self.tooltipOwner ~= input.editBox and self.tooltipOwner:IsMouseOver() then self:TraceHover('other-owner'); return end
 local knowledge = addon.KnowledgeBase and addon.KnowledgeBase.panel
 if knowledge and knowledge:IsShown() and knowledge:IsMouseOver() then self:HideTooltip(input.editBox, 'knowledge-base'); return end
 local debugHover = D.paused and matches
 local apiHover = addon.APIHelp and addon.APIHelp:Enabled() and addon.APIHelp.ready
 if (not debugHover and not apiHover) or not input.editBox:IsMouseOver() or not input.scrollFrame:IsMouseOver() then
  self:TraceHover('gate', D.paused == true, matches ~= nil and matches ~= false, input.editBox:IsMouseOver(), input.scrollFrame:IsMouseOver())
  self:HideTooltip(input.editBox, 'code-gate')
  return
 end
 self.hoverElapsed = (self.hoverElapsed or 0) + elapsed
 if self.hoverElapsed < 0.1 then return end
 self.hoverElapsed = 0
 local state = input.queryEditor
 local font = state and state.overlay
 if not font or state.renderSource ~= source then return end
 if #source > 20000 and addon.Analysis and not addon.Analysis.cache[source] then
  self:HideTooltip(input.editBox, 'analysis-pending'); return
 end
 if type(font.CalculateScreenAreaFromCharacterSpan) ~= 'function' then self:TraceHover('missing-area-api'); return end
 local actual, size, flags = font:GetFont()
 local width, spacing = font:GetWidth(), font:GetSpacing()
 local layout = input.debugHitLayout
 local changed = not layout or layout.font ~= actual or layout.size ~= size or layout.flags ~= flags
  or layout.width ~= width or layout.spacing ~= spacing or layout.source ~= source
 if changed then
  input.debugHitLayout = { font = actual, size = size, flags = flags, width = width, spacing = spacing, source = source }
  self:HideTooltip(input.editBox, 'code-layout')
  return -- Let the visible font layout settle after a change.
 end
 local x, y = GetCursorPosition(); local scale = font:GetEffectiveScale()
 local sourcePosition = addon.Query.Editor:HoverSourcePosition(input, x / scale, y / scale)
 local path = sourcePosition and self:HoverPath(source, sourcePosition)
 local apiName = apiHover and sourcePosition and addon.APIHelp:Paths(source)[sourcePosition]
 if self.hoverTrace then
  self:TraceHover('glyph-hit', sourcePosition, sourcePosition and C:GetLinePosition(source, sourcePosition - 1), x / scale, y / scale)
 end
 if not path and not apiName then self:HideTooltip(input.editBox, 'code-no-token'); return end
 local hoverKey = tostring(sourcePosition) .. ":" .. (apiName or path or "")
 local visibleTooltip = self.tooltipAPI and self.apiTooltip or self.valueTooltip
 if self.hoverPath == hoverKey and self.hoverToken == D.evalToken and self.tooltipOwner == input.editBox and visibleTooltip and visibleTooltip:IsShown() then return end
 local value, found
 if debugHover and path then value, found = D:ResolveVariable(path) end
 self:TraceHover('resolve', found == true)
 if apiName and (not found or (not (_G.issecretvalue and _G.issecretvalue(value)) and type(value) == 'function')) then
  self:APITooltip(input.editBox, addon.APIHelp:FullDescription(apiName, true))
  self.hoverPath, self.hoverToken = hoverKey, D.evalToken
  return
 end
 if not found then self:HideTooltip(input.editBox, 'code-unresolved'); return end
 local hidden = _G.issecretvalue and _G.issecretvalue(value)
 local name = path:gsub('|', '||')
 self:ValueTooltip(input.editBox, name .. ' = ' .. D:FormatPreview(value):gsub('|', '||'), hidden and (type(value) == 'string' or type(value) == 'number'), value, name .. ' = |cff88ff88<secret>|r')
 self.hoverPath, self.hoverToken = hoverKey, D.evalToken
end

end
rm.LuaWorkbenchModules.APIHelp=function(_,addon)
local A = { index = {}, text = {}, revision = 0 }
addon.APIHelp = A
local L = addon.L

function A:Enabled()
 local db = addon.Workspace and addon.Workspace.db
 return db and db.options.apiHelp ~= false
end

function A:Refresh()
 self.source, self.paths = nil, nil
 self.revision = self.revision + 1
 local editor, console = addon.Query.Editor, addon.Query.Console
 editor.colorRevision = (editor.colorRevision or 0) + 1
 if console.input then editor:Paint(console.input) end
 if addon.DebugUI then addon.DebugUI:HideTooltip(nil, 'api-settings') end
end

function A:Load(force)
 if (not force and not self:Enabled()) or self.ready or self.loading then return end
 -- Avoid first-load work during combat. A later editor opening retries failed loads.
 if _G.InCombatLockdown and _G.InCombatLockdown() then self.pending = true; self.pendingForce = force; return end
 self.loading = true
 local docs = _G.APIDocumentation
 if not docs or not docs.functions or #docs.functions == 0 then
  local loader = _G.C_AddOns and _G.C_AddOns.LoadAddOn or _G.LoadAddOn
  if loader then pcall(loader, 'Blizzard_APIDocumentationGenerated') end
  docs = _G.APIDocumentation
 end
 if docs and type(docs.functions) == 'table' and #docs.functions > 0 then
  for _, info in ipairs(docs.functions) do
   local namespace = info.System and info.System.Namespace
   local name = namespace and namespace ~= '' and (namespace .. '.' .. info.Name) or info.Name
   -- Widget methods without a global namespace cannot be resolved from an arbitrary object.
   local value = _G
   for part in name:gmatch('[%w_]+') do
    if type(value) ~= 'table' then value = nil; break end
    value = rawget(value, part)
   end
   if not (_G.issecretvalue and _G.issecretvalue(value)) and type(value) == 'function' then self.index[name] = info end
  end
  self:Catalog(docs)
  self.ready = true
 else
  addon.Query.Console:SetStatus(L.apiUnavailable, true)
 end
 self.loading, self.pending = nil, nil
 self:Refresh()
end

-- Keep documentation separate from globals eligible for editor highlighting.
function A:Catalog(docs)
 self.catalog, self.aliases, self.byInfo = {}, {}, {}
 local function alias(key, name)
  if not key or key == '' then return end
  if self.aliases[key] == nil then self.aliases[key] = name
  elseif self.aliases[key] ~= name then self.aliases[key] = false end
 end
 local function add(info, kind, name)
  if self.byInfo[info] then return end
  if self.catalog[name] then name = (info.System and info.System.Name or kind) .. '.' .. name end
  self.catalog[name] = { info = info, kind = kind, name = name }
  self.byInfo[info] = name
  alias(name, name); alias(info.Name, name)
  return name
 end
 for _, info in ipairs(docs.systems or {}) do
  local name = add(info, 'apiSystems', info.Namespace or info.Name)
  if info.Type == 'ScriptObject' then alias(info.Name:gsub('API$', ''), name) end
 end
 for _, info in ipairs(docs.tables or {}) do
  local enum = info.Type == 'Enumeration'
  add(info, enum and 'apiEnums' or (info.Type == 'Structure' and 'apiStructures' or (info.Type == 'CallbackType' and 'apiCallbacks' or (info.Type == 'Constants' and 'apiConstants' or 'apiOther'))), enum and ('Enum.' .. info.Name) or info.Name)
 end
 for _, info in ipairs(docs.functions or {}) do
  local system = info.System
  local namespace = system and system.Namespace
  local object = system and system.Type ~= 'System' and system.Type ~= nil
  local name = namespace and namespace ~= '' and (namespace .. '.' .. info.Name)
   or object and (system.Name:gsub('API$', '') .. ':' .. info.Name) or info.Name
  add(info, 'apiFunctions', name)
 end
 for _, info in ipairs(docs.events or {}) do add(info, 'apiEvents', info.LiteralName or info.Name) end
 for _, info in ipairs(docs.callbacks or {}) do add(info, 'apiCallbacks', info.Name) end
 self.text = {}
end

function A:Reference(name, context)
 if self.catalog and self.catalog[name] then return name end
 local match = self.aliases and self.aliases[name]
 if match then return match end
 -- Resolve duplicate type names within their documented system only.
 local owner = context and (context.System or context)
 if owner then
  for _, info in ipairs(owner.Tables or {}) do
   if info.Name == name then return self.byInfo[info] end
  end
 end
end

function A:Link(name, label)
 return '|Hlwapi:' .. name .. '|h' .. label .. '|h'
end

function A:SetEnabled(enabled)
 addon.Workspace.db.options.apiHelp = enabled
 if enabled then self:Load() end
 self:Refresh()
end

-- Resolve documented global names statically. Never execute hovered code.
function A:Paths(source, force)
 if (not force and not self:Enabled()) or not self.ready then return {} end
 if self.source == source and self.paths then return self.paths end
 local analysis = addon.Analysis:Get(source)
 local paths, blocked, chain, root, previous, declaration = {}, {}, nil, nil, nil, nil
 for _, token in ipairs(analysis.tokens) do
  if token.kind ~= 'space' and token.kind ~= 'newline' and token.kind ~= 'comment' then
   if token.kind == 'identifier' or token.kind == 'call' then
    if previous and previous.text == '.' and chain then
     chain = chain .. '.' .. token.text
    elseif previous and (previous.text == '.' or previous.text == ':') then
     chain, root = nil, nil
    else
     root = token
     declaration = previous and previous.text == 'function'
     chain = token.semanticKind == 'globalVariable' and not token.definition and not analysis.globals[token.text] and token.text or nil
    end
    if chain and root and not token.definition then
     local name = chain:gsub('^_G%.', '')
     if self.index[name] and not analysis.globals[name] then
      paths[token.start] = name
      if declaration then blocked[name] = true end
     end
    end
   elseif token.text ~= '.' then
    if token.text == '=' and chain then blocked[chain:gsub('^_G%.', '')] = true end
    chain, root = nil, nil
   end
   previous = token
  end
 end
 for position, name in pairs(paths) do if blocked[name] then paths[position] = nil end end
 self.source, self.paths = source, paths
 return paths
end

function A:AtCursor(source, cursor)
 self:Load(true)
 local paths = self:Paths(source, true)
 for _, token in ipairs(addon.Analysis:Get(source).tokens) do
  if cursor >= token.start - 1 and cursor <= token.finish and paths[token.start] then return paths[token.start] end
 end
end

-- Only static documentation metadata is formatted here, never runtime values.
function A:MetadataValue(value, key)
 if type(value) == 'string' then return value end
 if type(value) == 'boolean' or type(value) == 'number' then return tostring(value) end
 if type(value) ~= 'table' then return '?' end
 local values = {}
 for _, item in ipairs(value) do
  local label
  if key == 'SecretArgumentsAddAspect' or key == 'SecretReturnsForAspect' then
   for name, number in pairs(_G.Enum and _G.Enum.SecretAspect or {}) do
    if type(number) == 'number' and number == item then label = 'Enum.SecretAspect.' .. name; break end
   end
  end
  values[#values + 1] = label or (type(item) ~= 'table' and self:MetadataValue(item, key) or '?')
 end
 return '{ ' .. table.concat(values, ', ') .. ' }'
end

function A:RestrictionKeys(info)
 local keys = {}
 for key, value in pairs(info) do
  if type(key) == 'string' and type(value) ~= 'function' and
   (key:find('Secret', 1, true) or key:find('Restrict', 1, true) or key:find('Secure', 1, true) or key:find('Protected', 1, true)) then
   keys[#keys + 1] = key
  end
 end
 table.sort(keys)
 return keys
end

function A:FullDescription(name, rich, links)
 if not rich and self.text[name] then return self.text[name] end
 local entry = self.catalog and self.catalog[name]
 local info = entry and entry.info or self.index[name]
 if not info then return end
 local function color(text, kind)
  text = text:gsub('|', '||')
  if not rich then return text end
  return '|c' .. (kind == 'heading' and 'ffe6c07b' or addon.Query.Editor:Color(kind)) .. text .. '|r'
 end
 local function reference(label, target)
  local text = color(label, 'blizzardFunction')
  local destination = target or self:Reference(label, info)
  return rich and links and destination and self:Link(destination, text) or text
 end
 local args = {}
 for _, field in ipairs(info.Arguments or {}) do args[#args + 1] = color(field.Name, 'parameter') .. ((field.Nilable or field.Default ~= nil) and '?' or '') end
 local callable = not entry or entry.kind == 'apiFunctions' or entry.kind == 'apiCallbacks'
 local lines = { color(entry and entry.kind == 'apiCallbacks' and L.apiCallbacks or (callable and L.apiFunction or L[entry.kind]), 'heading'), color(name, 'blizzardFunction') .. (callable and ('(' .. table.concat(args, ', ') .. ')') or '') }
 if info.System and self.byInfo and self.byInfo[info.System] then
  lines[#lines + 1] = reference(info.System.Namespace or info.System.Name, self.byInfo[info.System])
 end
 local function documentation(values)
  for _, detail in ipairs(values or {}) do lines[#lines + 1] = detail:gsub('|', '||') end
 end
 local function fields(title, values, arguments)
  if not values or #values == 0 then return end
  lines[#lines + 1] = ''; lines[#lines + 1] = color(title, 'heading')
  for _, field in ipairs(values) do
   local typeName = field.Type == 'bool' and 'boolean' or field.Type or '?'
   local line = color(field.Name, 'parameter') .. ': ' .. reference(typeName) .. (field.InnerType and ('<' .. reference(field.InnerType) .. '>') or '') .. (field.Nilable and (' || ' .. color('nil', 'literal')) or '')
   if field.EnumValue ~= nil then line = line .. ' = ' .. color(tostring(field.EnumValue), 'number') end
   if field.Value ~= nil then line = line .. ' = ' .. color(self:MetadataValue(field.Value), 'literal') end
   if field.Mixin then line = line .. ' (' .. reference(field.Mixin) .. ')' end
   local notes = {}
   if arguments and (field.Nilable or field.Default ~= nil) then notes[#notes + 1] = L.apiOptional end
   if field.Default ~= nil then
    local value = self:MetadataValue(field.Default)
    if type(field.Default) == 'string' then value = string.format('%q', field.Default) end
    notes[#notes + 1] = L.apiDefault .. ': ' .. color(value, 'literal')
   end
   if #notes > 0 then line = line .. ' (' .. table.concat(notes, ', ') .. ')' end
   lines[#lines + 1] = line
   for _, key in ipairs(self:RestrictionKeys(field)) do
    lines[#lines + 1] = '  ' .. color(key, 'parameter') .. ': ' .. color(self:MetadataValue(field[key], key), 'literal')
   end
   documentation(field.Documentation)
  end
 end
 if info.Documentation and #info.Documentation > 0 then lines[#lines + 1] = ''; documentation(info.Documentation) end
 fields(L.apiArguments, info.Arguments, true); fields(L.apiReturns, info.Returns, false)
 fields(L.apiFields, info.Fields, false); fields(L.apiPayload, info.Payload, false)
 for _, group in ipairs({ {'Functions', 'apiFunctions'}, {'Tables', 'apiTypes'}, {'Events', 'apiEvents'}, {'Callbacks', 'apiCallbacks'} }) do
  if info[group[1]] and #info[group[1]] > 0 then
   lines[#lines + 1] = ''; lines[#lines + 1] = color(L[group[2]], 'heading')
   for _, child in ipairs(info[group[1]]) do
    local target = self.byInfo and self.byInfo[child]
    lines[#lines + 1] = reference(child.LiteralName or child.Name, target)
   end
  end
 end
 -- Preserve additional static metadata without traversing mixin methods or parent cycles.
 local metadata = {}
 local excluded = {Name=true,Type=true,Namespace=true,LiteralName=true,loweredName=true,loweredNamespaceName=true}
 for key, value in pairs(info) do
  if not excluded[key] and (type(value) == 'string' or type(value) == 'number' or type(value) == 'boolean')
   and not (key:find('Secret') or key:find('Restrict') or key:find('Secure') or key:find('Protected')) then metadata[#metadata + 1] = key end
 end
 table.sort(metadata)
 for _, key in ipairs(metadata) do lines[#lines + 1] = color(key, 'parameter') .. ': ' .. color(self:MetadataValue(info[key], key), 'literal') end
 local restrictions = self:RestrictionKeys(info)
 if #restrictions > 0 then
  lines[#lines + 1] = ''; lines[#lines + 1] = color(L.apiRestrictions, 'heading')
  for _, key in ipairs(restrictions) do
   lines[#lines + 1] = color(key, 'parameter') .. ': ' .. color(self:MetadataValue(info[key], key), 'literal')
  end
 end
 local text = table.concat(lines, '\n')
 if not rich then self.text[name] = text end
 return text
end

-- Search only needs static words, not a fully formatted article for every entry.
-- Do not traverse documentation parent links or injected mixin methods.
function A:SearchText(name)
 local entry = self.catalog and self.catalog[name]
 local info = entry and entry.info or self.index[name]
 if not info then return '' end
 local words = { name, entry and L[entry.kind] or L.apiFunction }
 local function collect(value)
  if value.Name then words[#words + 1] = value.Name .. ':' end
  if value.Type then words[#words + 1] = value.Type == 'bool' and 'boolean' or value.Type end
  for _, line in ipairs(value.Documentation or {}) do words[#words + 1] = line end
  for key, item in pairs(value) do
   if key ~= 'Name' and key ~= 'Type' and key ~= 'Nilable' and key ~= 'loweredName' and key ~= 'loweredNamespaceName'
    and (type(item) == 'string' or type(item) == 'number' or type(item) == 'boolean') then
    words[#words + 1] = key .. ': ' .. tostring(item)
   elseif type(item) == 'table' and (key:find('Secret') or key:find('Restrict')) then
    words[#words + 1] = key .. ': ' .. self:MetadataValue(item, key)
   end
  end
  if value.Nilable then words[#words + 1] = 'nil' end
  if value.Default ~= nil then words[#words + 1] = L.apiDefault end
 end
 collect(info)
 if info.System then words[#words + 1] = info.System.Namespace or info.System.Name or '' end
 for _, group in ipairs({ {'Arguments', L.apiArguments}, {'Returns', L.apiReturns}, {'Fields', L.apiFields}, {'Payload', L.apiPayload} }) do
  local fields = info[group[1]]
  if fields and #fields > 0 then
   words[#words + 1] = group[2]
   for _, field in ipairs(fields) do
    collect(field)
    if group[1] == 'Arguments' and (field.Nilable or field.Default ~= nil) then words[#words + 1] = L.apiOptional end
   end
  end
 end
 for _, group in ipairs({ 'Functions', 'Tables', 'Events', 'Callbacks' }) do
  for _, child in ipairs(info[group] or {}) do words[#words + 1] = child.LiteralName or child.Name end
 end
 return table.concat(words, ' '):lower()
end

function A:Preview(name)
 local text = self:FullDescription(name, true)
 if not text then return end
 local lines = {}
 for line in (text .. '\n'):gmatch('(.-)\n') do
  if #lines == 18 then lines[#lines + 1] = '…'; break end
  lines[#lines + 1] = line
 end
 return table.concat(lines, '\n')
end

function A:Description(name)
 local text = self:FullDescription(name)
 if not text then return end
 if #text > 2200 then
  local ending = 2200
  while text:byte(ending + 1) and text:byte(ending + 1) >= 128 and text:byte(ending + 1) < 192 do ending = ending - 1 end
  text = text:sub(1, ending) .. '\n…'
 end
 return text
end

A.events = CreateFrame('Frame')
A.events:RegisterEvent('PLAYER_REGEN_ENABLED')
A.events:SetScript('OnEvent', function()
 if A.pending and addon.Workspace.window and addon.Workspace.window:IsShown() then
  A:Load(A.pendingForce); A.pendingForce = nil
  if addon.KnowledgeBase and addon.KnowledgeBase.panel and addon.KnowledgeBase.panel:IsShown() then addon.KnowledgeBase:Search() end
 end
end)

end
rm.LuaWorkbenchModules.KnowledgeBase=function(_,addon)
local K = {}
addon.KnowledgeBase = K
local UI, L, A = addon.UI, addon.L, addon.APIHelp

function K:BuildIndex()
 if self.entries then self:ScheduleIndex(); return end
 if not A.ready then return end
 local catalog, names = A.catalog or A.index, {}
 for name in pairs(catalog) do names[#names + 1] = name end
 table.sort(names)
 self.entries = {}
 for _, name in ipairs(names) do
  local entry = catalog[name]
  self.entries[#self.entries + 1] = { name = name, kind = entry.kind or 'apiFunctions', lower = name:lower() }
 end
 if self.panel then
  self.indexing, self.nextIndex = true, 1
  self:ScheduleIndex()
 else
  for _, entry in ipairs(self.entries) do entry.body = A:SearchText(entry.name) end
 end
end

function K:IndexStatus()
 if self.indexing and self.panel then
  self.panel.status:SetText(string.format(L.apiIndexing, self.nextIndex - 1, #self.entries))
 end
end

function K:ScheduleIndex()
 if not self.indexing or self.indexTimer or not self.panel or not self.panel:IsShown() then return end
 local entries = self.entries
 self.indexTimer = entries
 C_Timer.After(0, function()
  if self.indexTimer ~= entries then return end
  self.indexTimer = nil
  if self.entries ~= entries or not self.panel:IsShown() then return end
  local clock = _G.debugprofilestop
  local started = clock and clock()
  -- Yield between batches; also bound work on clients without a profiling clock.
  for _ = 1, 100 do
   local entry = entries[self.nextIndex]
   if not entry then break end
   entry.body = A:SearchText(entry.name)
   self.nextIndex = self.nextIndex + 1
   if started and clock() - started >= 2 then break end
  end
  if self.nextIndex > #entries then
   self.indexing = nil
   -- A pending user query owns the next refresh. Otherwise retain navigation.
   if not self.panel.delay then self:Search(true) end
  else
   self:IndexStatus(); self:ScheduleIndex()
  end
 end)
end

function K:Find(query)
 self:BuildIndex()
 query = query:lower():match('^%s*(.-)%s*$')
 local compact, words = query:gsub('%s+', ''), {}
 for word in query:gmatch('%S+') do words[#words + 1] = word end
 -- Entries are already alphabetic. Stable score buckets avoid sorting and
 -- allocating a new result record for every match on every keystroke.
 local buckets = { {}, {}, {}, {} }
 for _, entry in ipairs(self.entries or {}) do
  if not self.category or entry.kind == self.category then
   local nameMatch = entry.lower:find(compact, 1, true)
   local found = true
   if not nameMatch then
    found = not self.indexing and entry.body ~= nil
    if found then
     for _, word in ipairs(words) do if not entry.body:find(word, 1, true) then found = false; break end end
    end
   end
   if found then
    local rank = entry.lower == compact and 1 or (nameMatch == 1 and 2 or (nameMatch and 3 or 4))
    local bucket = buckets[rank]; bucket[#bucket + 1] = entry
   end
  end
 end
 local matches = {}
 for _, bucket in ipairs(buckets) do
  for _, entry in ipairs(bucket) do matches[#matches + 1] = entry end
 end
 return matches
end

function K:Select(name, navigating)
 local panel = self.panel
 if not navigating then self.history = {} end
 if addon.DebugUI then addon.DebugUI:HideTooltip(panel.detailContent, 'knowledge-selection') end
 panel.selected = name
 panel.detail:SetText(A:FullDescription(name, true, true) or '')
 if panel.back then panel.back:SetShown(self.history and #self.history > 0 or false) end
 self:LayoutDetail()
 panel.detailScroll:SetVerticalScroll(0); panel.detailScroll.bar:SetValue(0)
 for _, row in ipairs(panel.rows) do
  row.selected:SetShown(row.name == name)
 end
end

function K:Follow(link)
 local name = type(link) == 'string' and link:match('^lwapi:(.+)$')
 if not name or not A.catalog[name] or name == self.panel.selected then return end
 self.history = self.history or {}
 self.history[#self.history + 1] = { name = self.panel.selected, scroll = self.panel.detailScroll:GetVerticalScroll() }
 self:Select(name, true)
end

function K:Back()
 local previous = self.history and table.remove(self.history)
 if not previous then return end
 self:Select(previous.name, true)
 self.panel.detailScroll:SetVerticalScroll(previous.scroll); self.panel.detailScroll.bar:SetValue(previous.scroll)
end

function K:Categories(owner)
 local items = {}
 local categories = { 'apiFunctions', 'apiSystems', 'apiStructures', 'apiEnums', 'apiEvents', 'apiCallbacks', 'apiConstants', 'apiOther' }
 table.sort(categories, function(a, b) return L[a]:lower() < L[b]:lower() end)
 table.insert(categories, 1, 'apiAll')
 for _, key in ipairs(categories) do
  local category = key
  items[#items + 1] = { text = L[key], selected = (self.category or 'apiAll') == key, action = function()
   self.category = category ~= 'apiAll' and category or nil
   self.panel.category.text:SetText(L[category]); self:Search()
  end }
 end
 addon.Workspace:OpenMenu(owner, items)
 self.menuOpen = true
end

function K:LayoutDetail()
 local panel = self.panel
 panel.detailContent:SetWidth(math.max(1, panel.detailScroll:GetWidth()))
 panel.detail:SetJustifyV('TOP')
 panel.detail:SetHeight(0)
 panel.detail:SetWidth(math.max(1, panel.detailScroll:GetWidth() - 12))
 local height = math.max(1, panel.detail:GetStringHeight())
 panel.detail:SetHeight(height)
 panel.detailContent:SetHeight(height + 12)
 panel.detailScroll:UpdateScrollChildRect()
end

function K:Search(preserve)
 local panel = self.panel
 if not panel then return end
 panel.delay = nil
 if not preserve then self.history = {}; if panel.back then panel.back:Hide() end end
 local listOffset = preserve and panel.list:GetVerticalScroll() or 0
 local matches = self:Find(panel.search:GetText())
 local shown = math.min(#matches, 100)
 panel.status:SetText(not A.ready and (A.pending and L.apiPending or L.apiUnavailable) or string.format(L.apiResults, #matches, shown))
 for index = 1, shown do
  local row = panel.rows[index]
  if not row then
   row = CreateFrame('Button', nil, panel.content)
   row:SetHeight(26); row:SetPoint('LEFT'); row:SetPoint('RIGHT')
   row.selected = UI:Background(row, { 0.12, 0.24, 0.38, 1 })
   local hover = row:CreateTexture(nil, 'HIGHLIGHT'); hover:SetAllPoints(); hover:SetColorTexture(1, 1, 1, 0.07)
   row.text = UI:Text(row, '', 11); row.text:SetPoint('LEFT', 6, 0); row.text:SetPoint('RIGHT', -6, 0); row.text:SetWordWrap(false)
   row:RegisterForClicks('LeftButtonUp', 'RightButtonUp')
   row:SetScript('OnClick', function(_, button)
    self:Select(row.name)
    if button == 'RightButton' then self:CopyMenu(row, row.name) end
   end)
   panel.rows[index] = row
  end
  row.name = matches[index].name
  row:ClearAllPoints(); row:SetPoint('TOPLEFT', 0, -(index - 1) * 28); row:SetPoint('RIGHT')
  row.text:SetText(row.name); row.selected:SetShown(row.name == panel.selected); row:Show()
 end
 for index = shown + 1, #panel.rows do panel.rows[index]:Hide() end
 panel.content:SetHeight(math.max(1, shown * 28)); panel.list:SetVerticalScroll(listOffset); panel.list.bar:SetValue(listOffset)
 panel.list:UpdateScrollChildRect()
 self:IndexStatus()
 if preserve and panel.selected then return end
 if shown > 0 then self:Select(matches[1].name)
 else panel.selected = nil; panel.detail:SetText(A.ready and L.noResults or panel.status:GetText()); self:LayoutDetail() end
end

function K:Show(name)
 if addon.DebugUI then addon.DebugUI:HideTooltip(nil, 'knowledge-base') end
 addon.Workspace:HidePanels(self.panel)
 A:Load(true)
 if not self.panel then self:Create() end
 if name then self.category = nil; self.panel.category.text:SetText(L.apiAll); self.panel.search:SetText(name) end
 self.panel:Show(); self:Search()
 if name then self:Select(name) end
 if addon.Query.Console.input then addon.Query.Console.input:ClearFocus() end
 self.panel.search:SetFocus()
end

function K:PositionDefault()
 local panel, W = self.panel, addon.Workspace
 if W.db.panelPositions and W.db.panelPositions.knowledgeBase then return end
 local parentScale = UIParent:GetEffectiveScale()
 local panelRatio = panel:GetEffectiveScale() / parentScale
 local windowRatio = W.window:GetEffectiveScale() / parentScale
 local right, top = W.window:GetRight(), W.window:GetTop()
 local width, height = panel:GetWidth() * panelRatio, panel:GetHeight() * panelRatio
 panel:ClearAllPoints()
 if right and top and right * windowRatio + 12 >= 12
  and right * windowRatio + 12 + width <= UIParent:GetWidth() - 12 then
  local desiredTop = math.max(height + 12, math.min(UIParent:GetHeight() - 12, top * windowRatio))
  panel:SetPoint('TOPLEFT', W.window, 'TOPRIGHT', 12 / panelRatio, (desiredTop - top * windowRatio) / panelRatio)
 else
  panel:SetPoint('CENTER', UIParent, 'CENTER')
 end
end

function K:RestoreSize()
 local panel = self.panel
 local ratio = UIParent:GetEffectiveScale() / panel:GetEffectiveScale()
 local maxWidth = math.max(1, (UIParent:GetWidth() - 32) * ratio)
 local maxHeight = math.max(1, (UIParent:GetHeight() - 32) * ratio)
 local minWidth, minHeight = math.min(480, maxWidth), math.min(280, maxHeight)
 panel:SetResizeBounds(minWidth, minHeight, maxWidth, maxHeight)
 local sizes = addon.Workspace.db.panelSizes
 local saved = sizes and sizes.knowledgeBase
 panel:SetSize(math.max(minWidth, math.min(maxWidth, saved and saved.width or 680)), math.max(minHeight, math.min(maxHeight, saved and saved.height or 430)))
end

function K:StopSizing()
 local panel, db = self.panel, addon.Workspace.db
 if not panel.sizing then return end
 panel.sizing = nil; panel:StopMovingOrSizing()
 db.panelSizes = db.panelSizes or {}
 db.panelSizes.knowledgeBase = { width = panel:GetWidth(), height = panel:GetHeight() }
 local x, y = panel:GetCenter()
 if x and y then
  local ratio = panel:GetEffectiveScale() / UIParent:GetEffectiveScale()
  db.panelPositions = db.panelPositions or {}
  db.panelPositions.knowledgeBase = { x = x * ratio - UIParent:GetWidth() / 2, y = y * ratio - UIParent:GetHeight() / 2 }
 end
 panel:RestorePanelPosition()
end

function K:Create()
 local W = addon.Workspace
 local panel = CreateFrame('Frame', (not addon.embedded and 'LuaWorkbenchKnowledgeBase' or nil), W.window)
 self.panel = panel
 if not addon.embedded then _G.UISpecialFrames[#_G.UISpecialFrames + 1] = (not addon.embedded and 'LuaWorkbenchKnowledgeBase' or nil) end
 local ratio = UIParent:GetEffectiveScale() / panel:GetEffectiveScale()
 panel:SetSize(math.min(680, (UIParent:GetWidth() - 30) * ratio), math.min(430, (UIParent:GetHeight() - 40) * ratio))
 panel:SetPoint('CENTER'); panel:SetFrameLevel(W.window:GetFrameLevel() + 50); panel:EnableMouse(true)
 UI:MovablePanel(panel, 'knowledgeBase'); panel:RestorePanelPosition()
 panel:SetResizable(true)
 panel:HookScript('OnShow', function() self:RestoreSize(); self:PositionDefault() end)
 self:RestoreSize(); self:PositionDefault()
 UI:Background(panel, UI.colors.panel); UI:Border(panel, { 0.25, 0.3, 0.38, 1 })
 local title = UI:Text(panel, L.knowledgeBase, 15); title:SetPoint('TOPLEFT', 14, -14)
 local close = UI:Button(panel, 'close', _G.CLOSE, function() panel:Hide() end); close:SetPoint('TOPRIGHT', -6, -7)
 panel.search = CreateFrame('EditBox', nil, panel)
 panel.search:SetPoint('TOPLEFT', 14, -44); panel.search:SetPoint('TOPRIGHT', -190, -44); panel.search:SetHeight(28)
 panel.search:SetFontObject(ChatFontNormal); panel.search:SetAutoFocus(false); panel.search:SetTextInsets(7, 7, 0, 0)
 UI:Background(panel.search, UI.colors.hover); UI:Tooltip(panel.search, L.apiSearch)
 panel.search:SetScript('OnTextChanged', function() panel.delay = 0.15 end)
 UI:SearchClear(panel.search, function() self:Search() end)
 panel.search:SetScript('OnEnterPressed', function() self:Search(); panel.search:ClearFocus() end)
 panel.search:SetScript('OnEscapePressed', function() panel.search:ClearFocus(); panel:Hide() end)
 panel.category = CreateFrame('Button', nil, panel)
 panel.category:SetPoint('TOPLEFT', panel.search, 'TOPRIGHT', 8, 0); panel.category:SetPoint('TOPRIGHT', -14, -44); panel.category:SetHeight(28)
 UI:Background(panel.category, UI.colors.hover)
 panel.category.text = UI:Text(panel.category, L[self.category or 'apiAll'], 11)
 panel.category.text:SetPoint('LEFT', 7, 0); panel.category.text:SetPoint('RIGHT', -16, 0)
 panel.category.text:SetWordWrap(false)
 local arrow = UI:Text(panel.category, 'v', 10); arrow:SetPoint('RIGHT', -5, 0)
 panel.category:SetScript('OnClick', function() self:Categories(panel.category) end)
 panel.back = UI:Button(panel, 'previous', L.navigationBack, function() self:Back() end)
 panel.back:SetPoint('RIGHT', close, 'LEFT', -6, 0); panel.back:Hide()
 -- Leave both title buttons outside the mouse-enabled drag surface.
 panel.dragHandle:SetPoint('TOPRIGHT', panel.back, 'TOPLEFT', -4, 7)
 panel.status = UI:Text(panel, '', 10); panel.status:SetPoint('BOTTOMLEFT', 14, 12); panel.status:SetPoint('RIGHT', -14, 0)
 panel.list = UI:Scroll(panel); panel.list:SetPoint('TOPLEFT', 14, -85); panel.list:SetPoint('BOTTOMLEFT', 14, 35); panel.list:SetWidth(math.floor(panel:GetWidth() * 0.38))
 panel.content = CreateFrame('Frame', nil, panel.list); panel.content:SetSize(panel.list:GetWidth(), 1); panel.list:SetScrollChild(panel.content)
 panel.rows = {}
 panel.detailScroll = UI:Scroll(panel); panel.detailScroll:SetPoint('TOPLEFT', panel.list, 'TOPRIGHT', 25, 0); panel.detailScroll:SetPoint('BOTTOMRIGHT', -25, 35)
 panel.detailContent = CreateFrame('Frame', nil, panel.detailScroll); panel.detailContent:SetSize(1, 1); panel.detailScroll:SetScrollChild(panel.detailContent)
 panel.detail = UI:Text(panel.detailContent, '', 12); panel.detail:SetPoint('TOPLEFT', 6, -6); panel.detail:SetWordWrap(true)
 panel.detailContent:EnableMouse(true)
 panel.detailContent:SetHyperlinksEnabled(true)
 panel.detailContent:SetScript('OnHyperlinkClick', function(_, link, _, button)
  if button == 'LeftButton' then self:Follow(link) end
 end)
 panel.detailContent:SetScript('OnHyperlinkEnter', function(_, link)
  local name = type(link) == 'string' and link:match('^lwapi:(.+)$')
  if name and A.catalog[name] and addon.DebugUI then
   addon.DebugUI:APITooltip(panel.detailContent, A:Preview(name))
  end
 end)
 panel.detailContent:SetScript('OnHyperlinkLeave', function()
  if addon.DebugUI then addon.DebugUI:HideTooltip(panel.detailContent, 'knowledge-link-leave') end
 end)
 panel.detailContent:SetScript('OnMouseUp', function(_, button)
  if button == 'RightButton' and panel.selected then self:CopyMenu(panel.detailContent, panel.selected) end
 end)
 panel.detail:SetSpacing(4)
 panel.detailScroll:SetScript('OnSizeChanged', function() self:LayoutDetail() end)
 panel:SetScript('OnUpdate', function(_, elapsed)
  if panel.delay then panel.delay = panel.delay - elapsed; if panel.delay <= 0 then self:Search() end end
 end)
 panel:SetScript('OnHide', function() panel.search:ClearFocus(); panel.delay = nil
  if self.copyPanel then self.copyPanel:Hide() end
  if self.menuOpen and W.contextMenu then W.contextMenu:Hide(); self.menuOpen = nil end
  if addon.DebugUI then addon.DebugUI:HideTooltip(panel.detailContent, 'knowledge-hidden') end
  self:StopSizing()
 end)
 panel:SetScript('OnSizeChanged', function()
  panel.list:SetWidth(math.floor(panel:GetWidth() * 0.38))
  panel.content:SetWidth(panel.list:GetWidth())
  self:LayoutDetail()
  if self.copyPanel then self.copyPanel:SetWidth(math.min(440, panel:GetWidth() - 24)) end
 end)
 local grip = CreateFrame('Button', nil, panel)
 panel.resizeGrip = grip
 grip:SetSize(18, 18); grip:SetPoint('BOTTOMRIGHT', -2, 2)
 grip:SetNormalTexture('Interface\\ChatFrame\\UI-ChatIM-SizeGrabber-Up')
 grip:SetHighlightTexture('Interface\\ChatFrame\\UI-ChatIM-SizeGrabber-Highlight')
 grip:SetPushedTexture('Interface\\ChatFrame\\UI-ChatIM-SizeGrabber-Down')
 grip:SetScript('OnMouseDown', function(_, button)
  if button == 'LeftButton' then panel.sizing = true; panel:StartSizing('BOTTOMRIGHT') end
 end)
 grip:SetScript('OnMouseUp', function() self:StopSizing() end)
end

function K:CopyMenu(owner, name)
 if not (A.catalog and A.catalog[name] or A.index[name]) then return end
 GameTooltip:Hide()
 self.menuOpen = true
 addon.Workspace:OpenMenu(owner, { { text = L.apiCopyName, action = function() self.menuOpen = nil; self:CopyFunction(name) end } })
end

function K:CopyFunction(name)
 if not (A.catalog and A.catalog[name] or A.index[name]) then return end
 -- Addons use selectable text; the native clipboard API has restricted access.
 if not self.copyPanel then
  local panel = CreateFrame('Frame', (not addon.embedded and 'LuaWorkbenchCopyFunction' or nil), self.panel)
  self.copyPanel = panel
  panel:SetSize(math.min(440, self.panel:GetWidth() - 24), 130); panel:SetPoint('CENTER')
  panel:SetFrameLevel(self.panel:GetFrameLevel() + 20); panel:EnableMouse(true); panel:SetClampedToScreen(true)
  UI:Background(panel, UI.colors.background); UI:Border(panel, { 0.25, 0.3, 0.38, 1 })
  local title = UI:Text(panel, L.apiCopyName, 14); title:SetPoint('TOPLEFT', 14, -14)
  local close = UI:Button(panel, 'close', _G.CLOSE, function() panel:Hide() end); close:SetPoint('TOPRIGHT', -5, -5)
  local box = CreateFrame('EditBox', nil, panel); panel.box = box
  box:SetPoint('TOPLEFT', 14, -45); box:SetPoint('TOPRIGHT', -14, -45); box:SetHeight(28)
  box:SetFontObject(ChatFontNormal); box:SetAutoFocus(false); box:SetTextInsets(7, 7, 0, 0)
  UI:Background(box, UI.colors.hover)
  box:SetScript('OnEscapePressed', function() panel:Hide() end)
  box:SetScript('OnEnterPressed', function() panel:Hide() end)
  panel:SetScript('OnHide', function() box:ClearFocus() end)
  local hint = UI:Text(panel, L.copyOutputHint, 11)
  hint:SetPoint('TOPLEFT', 14, -86); hint:SetPoint('TOPRIGHT', -14, -86); hint:SetWordWrap(true)
  if not addon.embedded then _G.UISpecialFrames[#_G.UISpecialFrames + 1] = (not addon.embedded and 'LuaWorkbenchCopyFunction' or nil) end
 end
 self.panel.search:ClearFocus()
 self.copyPanel:Show(); self.copyPanel.box:SetText(name)
 self.copyPanel.box:SetFocus(); self.copyPanel.box:HighlightText()
end

end
rm.LuaWorkbenchModules.Inspector=function(_,addon)
local I = { refs = {}, serial = 0 }
addon.Inspector = I
local W, UI, L, C = addon.Workspace, addon.UI, addon.L, addon.Query.Console

function I:Secret(value) return _G.issecretvalue and _G.issecretvalue(value) or false end

function I:Widget(value)
 if self:Secret(value) then return false end
 if not (_G.C_Widget and _G.C_Widget.IsWidget) then return false end
 local ok, widget = pcall(_G.C_Widget.IsWidget, value)
 if not ok or self:Secret(widget) or not widget then return false end
 local access, allowed = pcall(function() return value:CanBeAccessedInContext() end)
 return access and not self:Secret(allowed) and allowed == true
end

function I:Readable(value)
 if self:Secret(value) then return false end
 if _G.C_Widget and _G.C_Widget.IsWidget then
  local ok, widget = pcall(_G.C_Widget.IsWidget, value)
  if not ok or self:Secret(widget) then return false end
  if widget then return self:Widget(value) end
 end
 return true
end

function I:Call(value, method)
 if not self:Widget(value) then return nil end
 local ok, result = pcall(function() return value[method](value) end)
 if ok and not self:Secret(result) then return result end
end

function I:Text(value)
 if self:Secret(value) then return '<secret>' end
 if not self:Readable(value) then return '<restricted>' end
 local kind = type(value)
 if kind == 'string' then return value end
 if kind == 'number' or kind == 'boolean' or kind == 'nil' then return tostring(value) end
 local name = self:Call(value, 'GetDebugName')
 return type(name) == 'string' and name or '<' .. kind .. '>'
end

function I:Literal(value)
 if self:Secret(value) then return nil end
 local kind = type(value)
 if kind == 'string' then return string.format('%q', value) end
 if kind == 'boolean' then return tostring(value) end
 if kind == 'number' and value == value and value ~= math.huge and value ~= -math.huge then return tostring(value) end
end

function I:Ref(id) return self.refs[id] end

-- Debug names are hints, not executable expressions. Resolve only raw fields.
function I:GlobalPath(value, name)
 if type(name) ~= 'string' or not name:match('^[%a_][%w_%.]*$') or name:find('..', 1, true) or name:sub(-1) == '.' then return nil end
 local object, path = _G, '_G'
 for key in name:gmatch('[^.]+') do
  if not key:match('^[%a_][%w_]*$') or not self:Readable(object) or type(object) ~= 'table' then return nil end
  local ok, field = pcall(rawget, object, key)
  if not ok or self:Secret(field) then return nil end
  object = field
  -- Bracket notation also handles identifiers that are Lua keywords.
  path = path .. '[' .. string.format('%q', key) .. ']'
 end
 if rawequal(object, value) then return path end
end

function I:Path(value)
 if not self:Readable(value) then return nil end
 local name = self:Call(value, 'GetName')
 if type(name) == 'string' and rawequal(rawget(_G, name), value) then return '_G[' .. string.format('%q', name) .. ']' end
 local globalPath = self:GlobalPath(value, name) or self:GlobalPath(value, self:Call(value, 'GetDebugName'))
 if globalPath then return globalPath end
 if type(value) ~= 'table' and not self:Widget(value) then return self:Literal(value) end
 for id, item in pairs(self.refs) do if rawequal(item, value) then return 'editor.Inspector:Ref(' .. string.format('%q', id) .. ')' end end
 self.serial = self.serial + 1
 local id = 'object' .. self.serial
 self.refs[id] = value
 return 'editor.Inspector:Ref(' .. string.format('%q', id) .. ')'
end

function I:Node(label, value, path, parent)
 local expandable = self:Readable(value) and (type(value) == 'table' or self:Widget(value))
 if expandable then
  local globalPath = self:GlobalPath(value, self:Call(value, 'GetName')) or self:GlobalPath(value, self:Call(value, 'GetDebugName'))
  path = globalPath or path or self:Path(value)
 end
 local ancestor, cycle = parent, false
 while expandable and ancestor do
  if rawequal(ancestor.value, value) then cycle = true; break end
  ancestor = ancestor.parent
 end
 return { label = label, value = value, path = path, parent = parent, expandable = expandable and not cycle, cycle = cycle }
end

function I:Expand(node)
 if node.children then return end
 node.children = {}
 if not node.expandable then return end
 local function add(label, value, path)
  node.children[#node.children + 1] = self:Node(label, value, path, node)
 end
 if self:Widget(node.value) then
  for _, method in ipairs({ 'GetName', 'GetObjectType', 'IsShown', 'IsVisible', 'GetWidth', 'GetHeight', 'GetScale', 'GetAlpha', 'GetFrameStrata', 'GetFrameLevel', 'GetParent' }) do
   local value = self:Call(node.value, method)
   if value ~= nil then add(method .. '()', value, node.path and node.path .. ':' .. method .. '()') end
  end
  local points = self:Call(node.value, 'GetNumPoints')
  if type(points) == 'number' then
   for index = 1, math.min(points, 20) do
    local ok, values = pcall(function() return { node.value:GetPoint(index) } end)
    if ok then add('GetPoint(' .. index .. ')', values) end
   end
  end
  for _, method in ipairs({ 'GetChildren', 'GetRegions' }) do
   local ok, values = pcall(function() return { node.value[method](node.value) } end)
   if ok then add(method .. '()', values) end
  end
 end
 if type(node.value) == 'table' then
  local key, count = nil, 0
  while count < 500 do
   local ok, nextKey, value = pcall(next, node.value, key)
   if not ok or self:Secret(nextKey) or nextKey == nil then break end
   key, count = nextKey, count + 1
   local literal = self:Literal(key)
   add(self:Text(key), value, node.path and literal and node.path .. '[' .. literal .. ']')
  end
  if count == 500 then add(L.inspectorLimit, nil) end
 end
 table.sort(node.children, function(a, b) return a.label:lower() < b.label:lower() end)
end

function I:Rows()
 local rows, query = {}, (self.panel.search:GetText() or ''):lower()
 local function visit(node, depth)
  local match = query == '' or (node.label .. ' ' .. self:Text(node.value)):lower():find(query, 1, true)
  if match then rows[#rows + 1] = { node = node, depth = depth } end
  if node.open and node.children and depth < 20 then
   for _, child in ipairs(node.children) do if #rows >= 1000 then break end; visit(child, depth + 1) end
  end
 end
 if self.root then visit(self.root, 0) end
 return rows
end

function I:RowText(node)
 local function color(text, kind)
  return '|c' .. addon.Query.Editor:Color(kind) .. text:gsub('|', '||') .. '|r'
 end
 local hidden, kind = self:Secret(node.value), type(node.value)
 local object = not hidden and (kind == 'table' or self:Widget(node.value))
 local valueKind = hidden and 'comment' or object and 'blizzardFunction'
  or kind == 'string' and 'string' or kind == 'number' and 'number'
  or (kind == 'boolean' or kind == 'nil') and 'literal' or kind == 'function' and 'functionName' or 'identifier'
 local labelKind = node.label:match('%(.*%)$') and 'functionName' or object and 'blizzardFunction' or 'globalVariable'
 return color(node.expandable and (node.open and '- ' or '+ ') or '  ', 'comment')
  .. color(node.label, labelKind) .. color(' = ', 'operator')
  .. color(self:Text(node.value):sub(1, 180), valueKind) .. (node.cycle and color(' [<]', 'comment') or '')
end

function I:Tooltip(row)
 local node = row.node
 local hidden = self:Secret(node.value) and (type(node.value) == 'number' or type(node.value) == 'string')
 addon.DebugUI:ValueTooltip(row, self:RowText(node), hidden, node.value, node.label:gsub('|', '||') .. ' = |cff88ff88<secret>|r')
end

function I:Render()
 if not self.panel then return end
 self.rows = self:Rows()
 local scroll, content = self.panel.scroll, self.panel.content
 content:SetHeight(math.max(1, #self.rows * 22))
 local first = math.floor(scroll:GetVerticalScroll() / 22)
 for index = 1, math.min(80, math.ceil(scroll:GetHeight() / 22) + 2) do
  local row = self.buttons[index]
  if not row then
   row = CreateFrame('Button', nil, content); self.buttons[index] = row
   row:SetHeight(22); row:RegisterForClicks('LeftButtonUp', 'RightButtonUp')
   row.text = UI:Text(row, '', 11); row.text:SetAllPoints(); row.text:SetJustifyH('LEFT'); row.text:SetWordWrap(false)
   row:SetScript('OnClick', function(_, button)
    local node = row.node
    if button == 'RightButton' then self:Menu(row, node)
    elseif node.cycle or node.label == 'GetParent()' then self:Navigate(node.value, self:Text(node.value))
    elseif node.expandable then node.open = not node.open; if node.open then self:Expand(node) end; self:Render() end
   end)
   row:SetScript('OnEnter', function() self:Tooltip(row) end)
   row:SetScript('OnLeave', function() addon.DebugUI:HideTooltip(row) end)
  end
  local item = self.rows[first + index]
  if item then
   row.node = item.node
   row:ClearAllPoints(); row:SetPoint('TOPLEFT', item.depth * 12, -(first + index - 1) * 22); row:SetPoint('RIGHT')
   local node = item.node
   row.text:SetText(self:RowText(node))
   row:Show()
  else row:Hide() end
 end
 local visible = math.min(80, math.ceil(scroll:GetHeight() / 22) + 2)
 for index = visible + 1, #self.buttons do self.buttons[index]:Hide() end
end

function I:Copy(text)
