function I:StopPicking()
 self.picking = nil
 if self.pickerDriver then self.pickerDriver:Hide() end
 if self.picker then self.picker:Hide() end
 if self.highlight then self.highlight:Hide() end
 self.selected, self.highlightTarget = nil, nil
end

function I:Pick()
 if self.picking then self:StopPicking(); return end
 local loader = _G.C_AddOns and _G.C_AddOns.LoadAddOn or _G.LoadAddOn
 if not loader or not loader('Blizzard_DebugTools') or not _G.KeyCommand_Create then C:SetStatus(L.developerToolUnavailable, true); return end
 C.input:ClearFocus()
 addon.DebugUI:HideTooltip(nil, 'frame-picker')
 if self.panel then self.panel:Hide() end
 if not self.picker then
  local picker = CreateFrame('GameTooltip', (not addon.embedded and 'LuaWorkbenchFramePicker' or nil), UIParent, 'SharedTooltipTemplate'); self.picker = picker
  picker:SetFrameStrata('TOOLTIP'); picker:EnableMouse(false); picker:SetClampedToScreen(true)
  self.highlight = CreateFrame('Frame', nil, UIParent); self.highlight:SetFrameStrata('TOOLTIP'); self.highlight:EnableMouse(false)
  UI:Border(self.highlight, { 1, 0.8, 0.1, 1 })
  picker.commands = {
   _G.KeyCommand_Create(function() self.delta = 1 end, _G.KeyCommand.RUN_ON_DOWN, _G.KeyCommand_CreateKey('LALT')),
   _G.KeyCommand_Create(function() self.delta = -1 end, _G.KeyCommand.RUN_ON_DOWN, _G.KeyCommand_CreateKey('RALT')),
   _G.KeyCommand_Create(function() local value = self.selected; if value then self:Show(value) end end, _G.KeyCommand.RUN_ON_UP, _G.KeyCommand_CreateKey('CTRL')),
   _G.KeyCommand_Create(function() self:StopPicking() end, _G.KeyCommand.RUN_ON_DOWN, _G.KeyCommand_CreateKey('ESCAPE')),
  }
  self.pickerDriver = CreateFrame('Frame', nil, UIParent)
  self.pickerDriver:Hide()
  self.pickerDriver:SetScript('OnUpdate', function(_, elapsed)
   _G.KeyCommand_Update(picker.commands)
   if not self.picking then return end
   self.elapsed = (self.elapsed or 0) + elapsed
   if self.elapsed < 0.1 and not self.delta then return end
   self.elapsed = 0
   self:UpdatePicker()
  end)
 end
 self.picker:SetOwner(UIParent, 'ANCHOR_NONE'); self.picker:ClearAllPoints(); self.picker:SetPoint('BOTTOMLEFT', UIParent, 'BOTTOMLEFT', 24, 100)
 self.elapsed, self.delta, self.picking = 0, nil, true
 self:UpdatePicker()
 if self.picking then self.pickerDriver:Show() end
end

function I:UpdatePicker()
 local picker = self.picker
 -- These visible regions must not become candidates in their own frame stack.
 -- Hide/query/show runs synchronously, before the next rendered frame.
 picker:Hide()
 self.highlight:Hide()
 picker:SetOwner(UIParent, 'ANCHOR_NONE')
 picker:ClearAllPoints(); picker:SetPoint('BOTTOMLEFT', UIParent, 'BOTTOMLEFT', 24, 100)
 local ok, value = pcall(picker.SetFrameStack, picker, false, true, self.delta or 0)
 self.delta = nil
 if not ok then
  self:StopPicking()
  C:SetStatus(L.developerToolUnavailable, true)
  C:Write(L.inspectorTitle, C:Format(value))
  return
 end
 self.selected = not self:Secret(value) and value or nil
 picker:AddLine(L.inspectorPickHelp, 1, 0.8, 0.3, true)
 picker:Show()
 if self:Widget(self.selected) then
  local anchored = pcall(function()
   if not rawequal(self.highlightTarget, self.selected) then
    self.highlight:ClearAllPoints(); self.highlight:SetAllPoints(self.selected)
    self.highlightTarget = self.selected
   end
   self.highlight:Show()
  end)
  if not anchored then self.highlightTarget = nil; self.highlight:Hide() end
 else self.highlightTarget = nil end
end

end
rm.LuaWorkbenchModules.Autocomplete=function(_,addon)
local A = { limit = 8 }
addon.Autocomplete = A
local E, UI, L = addon.Query.Editor, addon.UI, addon.L

function A:Enabled(input)
 return input == addon.Query.Console.input and addon.Workspace.db.options.autocomplete ~= false and not E:IsReadOnly(input)
end

function A:Names()
 local api = addon.APIHelp
 if self.revision == api.revision then return self.names end
 local names, seen, kinds = {}, {}, {}
 for name in pairs(api.index) do
  seen[name], kinds[name] = true, 'blizzardFunction'
  local namespace = name:match('^([%w_]+)%.')
  if namespace then seen[namespace] = true end
 end
 for name,entry in pairs(api.catalog or {}) do
  if entry.kind == 'apiEnums' and name:match('^Enum%.[%a_][%w_]*$') then
   seen.Enum, seen[name], kinds.Enum, kinds[name] = true, true, 'identifier', 'identifier'
   for _,field in ipairs(entry.info.Fields or {}) do
    if type(field.Name) == 'string' and field.Name:match('^[%a_][%w_]*$') then
     local member=name..'.'..field.Name
     seen[member], kinds[member]=true,'identifier'
    end
   end
  end
 end
 for name in pairs(seen) do names[#names + 1] = name end
 table.sort(names)
 self.names, self.nameKinds, self.revision = names, kinds, api.revision
 return names
end

function A:Visible(analysis, cursor)
 local names = {}
 for _, def in ipairs(analysis.definitions) do
  local scope = def.scope
  local position = def.position0 or def.visible0
  if position < cursor and (def.visible0 or position) <= cursor
   and scope and scope.start0 <= cursor and (not scope.finish0 or cursor < scope.finish0) then
   local old = names[def.name]
   if not old or (old.position0 or old.visible0) < position then names[def.name] = def end
  end
 end
 for name, definitions in pairs(analysis.globals) do
  if not names[name] then
   for _, def in ipairs(definitions) do if def.position0 < cursor then names[name] = def end end
  end
 end
 return names
end

function A:Context(source, cursor, quick)
 if #source > 100000 then return end
 local prefix = source:sub(1, cursor):match('([%a_][%w_%.:]*)$') or ''
 -- Automatic completion needs declarations before the active name, not the
 -- unchanged document after it. The prefix analysis stays cached as it grows.
 local analysisSource, analysisCursor = source, cursor
 if quick and #source > 20000 then
  analysisCursor = cursor - #prefix
  analysisSource = source:sub(1, analysisCursor)
 end
 local analysis = addon.Analysis:Get(analysisSource)
 if analysis.limited then return end
 local inString=false
 for _, token in ipairs(analysis.tokens) do
  if analysisCursor >= token.start and analysisCursor <= token.finish and (token.kind == 'comment' or token.kind == 'string') then
   if analysisCursor < token.finish or token.closed ~= true then
    if token.kind == 'comment' then return end
    inString=true
   end
  end
 end
 local previous = source:sub(cursor - #prefix, cursor - #prefix)
 if not inString and (previous == ':' or previous == '.') then return end
 return { source=source, cursor=cursor, prefix=prefix, start=cursor-#prefix, analysis=analysis, visible=self:Visible(analysis, analysisCursor), inString=inString }
end

function A:Alias(context, name)
 local definition = context.visible[name]
 if not definition then return end
 local namespace
 for _,entry in ipairs(definition.apiAliases or {}) do
  if entry.position0 <= (context.lookupCursor or context.cursor) then namespace = entry.namespace end
 end
 return namespace or nil
end

-- Read only values established before the caret; aliases share table identity.
function A:HelperValue(value, cursor)
 local seen={}
 for _=1,8 do
  if not (value and value.module) then return value,cursor end
  if seen[value.module] then return end
  seen[value.module]=true
  local module=addon.Helpers:Resolve(value.module)
  if not module then return end
  local source=addon.Workspace:NormalizeSource(module.source)
  local analysis=addon.Analysis:Get(source)
  value,cursor=analysis.exportValue,#source+1
 end
end

function A:Value(context, path)
 local root = path:match('^[%a_][%w_]*')
 local definition = root and context.visible[root]
 local value
 for _,entry in ipairs(definition and definition.completionValues or {}) do
  if entry.position0 <= (context.lookupCursor or context.cursor) then value=entry.value end
 end
 local valueCursor
 value,valueCursor=self:HelperValue(value,context.lookupCursor or context.cursor)
 if value and value.completionInvalidated0 and value.completionInvalidated0 <= valueCursor then return end
 for name in path:sub(root and #root+1 or 1):gmatch('[%.:]([%a_][%w_]*)') do
  local history=value and value.completionMembers and value.completionMembers[name]
  value=nil
  for _,entry in ipairs(history or {}) do if entry.position0 <= valueCursor then value=entry.value end end
  value,valueCursor=self:HelperValue(value,valueCursor)
 end
 if value and value.completionInvalidated0 and value.completionInvalidated0 <= valueCursor then return end
 return value or nil,valueCursor
end

function A:Suggest(context, manual)
 if context.inString then return {} end
 local prefix, found = context.prefix, {}
 if prefix == '' and not manual then return found end
 if #prefix < 2 and not manual and not prefix:find('.', 1, true) then return found end
 local function add(name, kind)
  if name:sub(1, #prefix) == prefix and name ~= prefix then found[#found + 1] = { name=name, kind=kind } end
 end
 local path, separator = prefix:match('^(.*)([%.:])[%w_]*$')
 if path then
  local owner,valueCursor=self:Value(context,path)
  for name,history in pairs(owner and owner.completionMembers or {}) do
   local value
   for _,entry in ipairs(history) do if entry.position0 <= valueCursor then value=entry.value end end
   if value and (separator ~= ':' or value.parameters) then
    add(path..separator..name,value.parameters and 'functionName' or 'identifier')
   end
  end
  table.sort(found,function(a,b) return a.name<b.name end)
 end
 local namespace = prefix:match('^([%w_]+)[%.:]')
 local alias = namespace and self:Alias(context,namespace)
 local lookup = alias and (alias..prefix:sub(#namespace+1)) or prefix
 if not namespace then
  for name, def in pairs(context.visible) do add(name, def.kind) end
  table.sort(found, function(a,b) return a.name < b.name end)
 end
 if alias or not namespace or not context.visible[namespace] then
  local names = self:Names()
  local lo, hi = 1, #names + 1
  while lo < hi do local mid = math.floor((lo + hi) / 2); if names[mid] and names[mid] < lookup then lo = mid + 1 else hi = mid end end
  for index = lo, #names do
   local name = names[index]
   if name:sub(1, #lookup) ~= lookup then break end
   local root = name:match('^([%w_]+)%.')
   local parent=lookup:match('^(.*%.)')
   local direct=not parent or not name:sub(#parent+1):find('.',1,true)
   if direct then
    if alias then add(namespace..name:sub(#alias+1), self.nameKinds[name] or 'identifier')
    elseif not context.visible[name] and not (root and context.visible[root]) then add(name, self.nameKinds[name] or 'identifier') end
   end
   if #found >= self.limit then break end
  end
 end
 while #found > self.limit do table.remove(found) end
 return found
end

function A:Signature(context)
 local stack, tokens = {}, {}
 for _, token in ipairs(context.analysis.tokens) do
  if token.start > context.cursor then break end
  if token.kind ~= 'space' and token.kind ~= 'newline' and token.kind ~= 'comment' and token.kind ~= 'string' then
   local text = token.text
   if text == '(' or text == '{' or text == '[' then
    local name = ''
    if text == '(' then
     local index = #tokens
     if tokens[index] and tokens[index].text:match('^[%a_][%w_]*$') then
      name = tokens[index].text; index = index - 1
      while tokens[index] and (tokens[index].text == '.' or tokens[index].text == ':') and tokens[index-1] do name = tokens[index-1].text .. tokens[index].text .. name; index = index-2 end
      if tokens[index] and (tokens[index].text == ':' or tokens[index].text == 'function') then name = '' end
     end
    end
    stack[#stack + 1] = { opening=text, name=name, argument=1, position0=token.start-1 }
   elseif text == ')' or text == '}' or text == ']' then table.remove(stack)
   elseif text == ',' and stack[#stack] then stack[#stack].argument = stack[#stack].argument + 1 end
   tokens[#tokens+1] = token
  end
 end
 for index = #stack, 1, -1 do
  local call = stack[index]
  local own=self:Value(context,call.name)
  if own and own.parameters then
   local args={}
   if own.method then args[1]='self' end
   for _,name in ipairs(own.parameters) do args[#args+1]=name end
   if call.name:find(':',1,true) then table.remove(args,1) end
   for n,name in ipairs(args) do
    args[n]='|c'..E:Color(n==call.argument and 'functionName' or 'parameter')..name..'|r'
   end
   return call.name..'('..table.concat(args,', ')..')', call.position0
  end
  local root = call.name:match('^[%w_]+')
  local alias = root and self:Alias(context,root)
  local canonical = alias and (alias..call.name:sub(#root+1)) or call.name
  local info = addon.APIHelp.index[canonical]
  if info and (alias or not context.visible[root]) then
   local args = {}
   for n, arg in ipairs(info.Arguments or {}) do
    local text = arg.Name .. ((arg.Nilable or arg.Default ~= nil) and '?' or '') .. ': ' .. (arg.Type == 'bool' and 'boolean' or arg.Type or '?')
    if arg.Default ~= nil then text = text .. ' = ' .. tostring(arg.Default) end
    args[#args+1] = '|c' .. E:Color(n == call.argument and 'functionName' or 'parameter') .. text:gsub('|','||') .. '|r'
   end
   return call.name .. '(' .. table.concat(args, ', ') .. ')', call.position0
  end
 end
end

function A:RestoreArrows()
 if self.arrowBox then self.arrowBox:SetAltArrowKeyMode(self.savedArrowMode); self.arrowBox = nil end
 self.arrowKey, self.arrowOrigin = nil, nil
end

function A:Hide()
 self.keySource, self.keyCursor = nil, nil
 self:RestoreArrows()
 if self.panel then self.panel:Hide() end
 if self.signaturePanel then self.signaturePanel:Hide() end
 self.context, self.items, self.input, self.pending = nil, nil, nil, nil
end

function A:Build()
 if self.panel then return end
 local panel = CreateFrame('Frame', nil, UIParent); self.panel = panel
 panel:SetFrameStrata('TOOLTIP'); panel:SetClampedToScreen(true); panel:EnableMouse(false)
 UI:Background(panel, UI.colors.panel); UI:Border(panel, {0.3,0.4,0.5,1})
 self.rows = {}
 for index = 1, self.limit do
  local text = UI:Text(panel, '', 12); text:SetPoint('TOPLEFT', 8, -8-(index-1)*20); text:SetPoint('RIGHT', -8, 0); text:SetWordWrap(false)
  self.rows[index] = text
 end
 self.selection = panel:CreateTexture(nil, 'ARTWORK'); self.selection:SetColorTexture(0.15,0.3,0.48,1)
 self.hint = UI:Text(panel, '', 11); self.hint:SetWordWrap(true); self.hint:SetJustifyH('LEFT')
 local help=CreateFrame('Frame',nil,UIParent);self.signaturePanel=help
 help:SetFrameStrata('TOOLTIP');help:SetClampedToScreen(true);help:EnableMouse(false)
 UI:Background(help,UI.colors.panel);UI:Border(help,{0.3,0.4,0.5,1})
 self.signatureText=UI:Text(help,'',12)
 self.signatureText:SetPoint('TOPLEFT',8,-8);self.signatureText:SetWidth(504)
 self.signatureText:SetWordWrap(true);self.signatureText:SetJustifyH('LEFT')
 help:Hide()
end

function A:Draw()
 self:Build()
 local count = #self.items
 if count > 0 then
  if self.arrowBox ~= self.input.editBox then
   self:RestoreArrows()
   self.arrowBox = self.input.editBox
   self.savedArrowMode = self.arrowBox:GetAltArrowKeyMode() == true
  end
  self.arrowBox:SetAltArrowKeyMode(false)
 else self:RestoreArrows() end
 for index, row in ipairs(self.rows) do
  local item = self.items[index]
  local text = item and ('|c' .. E:Color(item.kind or 'identifier') .. item.name .. '|r') or ''
  if row:GetText() ~= text then row:SetText(text) end
  if row:IsShown() ~= (item ~= nil) then row:SetShown(item ~= nil) end
 end
 self.selection:ClearAllPoints(); self.selection:SetPoint('TOPLEFT', 4, -6-((self.selected or 1)-1)*20); self.selection:SetSize(412,20); self.selection:SetShown(count>0)
 self.hint:ClearAllPoints(); self.hint:SetPoint('TOPLEFT', 8, -10-count*20); self.hint:SetWidth(404)
 self.hint:SetText(L.autocompleteHelp)
 self.panel:SetSize(420, 20+count*20+self.hint:GetStringHeight())
 local input = self.input
 self.panel:ClearAllPoints(); self.panel:SetPoint('TOPLEFT', input.editBox, 'TOPLEFT', input.cursorX or 0, (input.cursorY or 0)-20)
 self.panel:SetShown(count>0)
 if self.signature then
  if self.signatureText:GetText() ~= self.signature then self.signatureText:SetText(self.signature) end
  self.signaturePanel:SetSize(520,16+self.signatureText:GetStringHeight())
  self.signaturePanel:ClearAllPoints()
  self.signaturePanel:SetPoint('BOTTOMLEFT',input.editBox,'TOPLEFT',input.cursorX or 0,(input.cursorY or 0)+4)
  self.signaturePanel:Show()
 else self.signaturePanel:Hide() end
end

function A:Update(input, manual, signatureOnly)
 if not self:Enabled(input) or not input.editBox:HasFocus() then self:Hide(); return end
 if not addon.APIHelp.ready and not self.loadTried then self.loadTried = true; addon.APIHelp:Load(true) end
 local context = self:Context(input:GetText(), input.editBox:GetCursorPosition(), not manual)
 if not context then self:Hide(); return end
 self.lastSource, self.lastCursor, self.lastScript = context.source, context.cursor, addon.Workspace.current
 self.pending = nil
 context.manual, context.apiRevision = manual, addon.APIHelp.revision
 self.input, self.context, self.selected = input, context, 1
 local previousCall=self.signatureCall
 self.items=signatureOnly and {} or self:Suggest(context,manual)
 self.signature,self.signatureCall=self:Signature(context)
 if signatureOnly and previousCall ~= self.signatureCall then self.signature=nil end
 if #self.items == 0 and not self.signature then self:Hide(); return end
 self:Draw()
end

-- Only refine the active identifier when both surrounding source regions match.
-- Reuse scope data at the original position, never shifted future declarations.
function A:Refine(input, source, cursor)
 local old = self.context
 if self.input ~= input or not old or old.apiRevision ~= addon.APIHelp.revision or self.lastScript ~= addon.Workspace.current
  or not self.panel or not self.panel:IsShown() or source == old.source then return false end
 local prefix = source:sub(1,cursor):match('([%a_][%w_%.:]*)$') or ''
 local start = cursor - #prefix
 if prefix == '' or start ~= old.start
  or prefix:match('^(.*[%.:])') ~= old.prefix:match('^(.*[%.:])')
  or source:sub(1,start) ~= old.source:sub(1,old.start)
  or source:sub(cursor+1) ~= old.source:sub(old.cursor+1) then return false end
 local selected = self.items and self.items[self.selected or 1]
 local name = selected and selected.name
 local context = {source=source,cursor=cursor,prefix=prefix,start=start,
  analysis=old.analysis,visible=old.visible,inString=old.inString,
  lookupCursor=old.lookupCursor or old.cursor,manual=old.manual,apiRevision=old.apiRevision}
 local items = self:Suggest(context, context.manual)
 if selected and name ~= prefix and name:sub(1,#prefix) == prefix then
  local present = false
  for _,item in ipairs(items) do if item.name == name then present=true;break end end
  if not present then items[math.min(#items+1,self.limit)] = selected end
 end
 self.context, self.items, self.selected = context, items, 1
 for index,item in ipairs(items) do if item.name == name then self.selected=index;break end end
 self.lastSource, self.lastCursor, self.pending = source,cursor,nil
 self.keySource, self.keyCursor = nil,nil
 if #items == 0 and not self.signature then self:Hide() else self:Draw() end
 return true
end

function A:RestoreCursor(input)
 local state=input.queryEditor
 if self.input ~= input or self.keyCursor == nil or not state or state.busy
  or input:GetText() ~= self.keySource then return end
 if input.editBox:GetCursorPosition() ~= self.keyCursor then
  state.busy=true
  input.editBox:SetCursorPosition(self.keyCursor)
  state.busy=nil
  state.actionCursor=self.keyCursor
 end
end

function A:Tick(input, elapsed)
 if not self:Enabled(input) or not input.editBox:HasFocus() then if self.input == input then self:Hide() end; return end
 self:RestoreCursor(input)
 local source, cursor = input:GetText(), input.editBox:GetCursorPosition()
 if source ~= self.lastSource or cursor ~= self.lastCursor or addon.Workspace.current ~= self.lastScript then
  if self:Refine(input,source,cursor) then return end
  self.pendingSuggestions=self.lastSource ~= nil and source ~= self.lastSource
   and self.lastScript == addon.Workspace.current
  local keepSignature=self.input == input and self.signaturePanel and self.signaturePanel:IsShown() and self.signature
   and self.lastScript == addon.Workspace.current
  self.lastSource, self.lastCursor, self.lastScript = source, cursor, addon.Workspace.current
  self.pending = 0
  if keepSignature then
   -- Keep parameter help during debounce, but never accept stale suggestions.
   self.context, self.items, self.selected=nil,{},1
   self:Draw()
  else
   self:Hide()
   if self.pendingSuggestions then self.pending=0 end
  end
 end
 if self.pending then
  self.pending = self.pending + elapsed
  if self.pending >= (#source > 20000 and 0.12 or 0.15) then self.pending = nil; self:Update(input, false, not self.pendingSuggestions) end
 end
end

function A:Accept(input)
 if self.context and input:GetText() ~= self.context.source then self:Refine(input,input:GetText(),input.editBox:GetCursorPosition()) end
 if self.input ~= input or not self.panel or not self.panel:IsShown() or not self.context or not self.items or not self.items[self.selected] then return false end
 local context, name = self.context, self.items[self.selected].name
 if input:GetText() ~= context.source or input.editBox:GetCursorPosition() ~= context.cursor or E:IsReadOnly(input) then self:Hide(); return false end
 local finish = context.cursor
 local suffix = context.source:sub(finish+1):match('^[%w_]*') or ''
 E:SetSource(input, context.source:sub(1, context.start) .. name .. context.source:sub(finish+#suffix+1), context.start+#name)
 self.lastSource, self.lastCursor, self.lastScript = input:GetText(), input.editBox:GetCursorPosition(), addon.Workspace.current
 self.keySource,self.keyCursor=nil,nil
 self:RestoreArrows()
 self:Update(input,false,true)
 return true
end

function A:Key(input, key)
 if not self:Enabled(input) then return end
 if self:Arrow(input, key, 'key') then return true end
 if key == 'SPACE' and _G.IsControlKeyDown and IsControlKeyDown() then
  addon.APIHelp:Load(true); self:Update(input, true)
  self.keySource, self.keyCursor = input:GetText(), input.editBox:GetCursorPosition()
  return true
 end
end

function A:Arrow(input, key, origin)
 if not self:Enabled(input) then return end
 if (key == 'UP' or key == 'DOWN') and self.input == input and self.context
  and input:GetText() ~= self.context.source then
  if not self:Refine(input,input:GetText(),input.editBox:GetCursorPosition()) then self:Hide();return end
 end
 if self.input == input and self.panel and self.panel:IsShown() and #self.items>0 and (key == 'UP' or key == 'DOWN')
  and not (_G.IsAltKeyDown and IsAltKeyDown()) and not (_G.IsShiftKeyDown and IsShiftKeyDown()) then
  origin = origin or 'native'
  -- Some EditBoxes dispatch both callbacks for one press; consume the second.
  if self.arrowKey == key and self.arrowOrigin and self.arrowOrigin ~= origin then
   self:RestoreCursor(input)
   self.arrowKey, self.arrowOrigin = nil, nil
   return true
  end
  self.arrowKey, self.arrowOrigin = key, origin
  self.selected = (self.selected-1+(key=='UP' and -1 or 1)) % #self.items+1
  self.keySource, self.keyCursor = self.context.source, self.context.cursor
  input.editBox:SetCursorPosition(self.keyCursor)
  self.lastSource, self.lastCursor, self.pending = self.keySource, self.keyCursor, nil
  self:Draw(); return true
 end
end

end
rm.LuaWorkbenchModules.EditorActions=function(_,addon)
local A = {}
addon.EditorActions = A
local E = addon.Query.Editor

function A:Bounds(source, cursor)
 local first = (source:sub(1, cursor):match('.*\n()') or 1) - 1
 local last = source:find('\n', cursor+1, true) or #source
 return first, last
end

function A:Move(source, cursor, direction, duplicate, selectionStart, selectionEnd, block)
 local first, last = self:Bounds(source, cursor)
 if selectionStart and selectionEnd and selectionStart ~= selectionEnd then
  local low, high = math.min(selectionStart, selectionEnd), math.max(selectionStart, selectionEnd)
  first = self:Bounds(source, low)
  local _, blockEnd = self:Bounds(source, high-1)
  last = blockEnd
 end
 if block then first, last = block.first, block.last end
 local hasNewline = last > first and source:sub(last, last) == '\n'
 if block then hasNewline = block.separated end
 local function bounds(at, separated)
  return {first=at, last=at+(last-first)-(hasNewline and 1 or 0)+(separated and 1 or 0), separated=separated}
 end
 local line = source:sub(first+1, hasNewline and last-1 or last)
 local column = cursor-first
 if duplicate then
  local at = direction < 0 and first or last
  local text = direction < 0 and (line .. '\n') or (hasNewline and (line .. '\n') or ('\n' .. line))
  local result = source:sub(1, at) .. text .. source:sub(at+1)
  local position = direction < 0 and (first+column) or (last+(hasNewline and 0 or 1)+column)
  return result, position, bounds(direction < 0 and first or (last+(hasNewline and 0 or 1)), direction < 0 or hasNewline)
 end
 if direction < 0 then
  if first == 0 then return source, cursor, bounds(first,hasNewline) end
  local previous = (source:sub(1, first-1):match('.*\n()') or 1)-1
  local above = source:sub(previous+1, first-1)
  return source:sub(1, previous) .. line .. '\n' .. above .. (hasNewline and '\n' or '') .. source:sub(last+1), previous+column, bounds(previous,true)
 end
 if not hasNewline then return source, cursor, bounds(first,hasNewline) end
 local nextEnd = source:find('\n', last+1, true) or #source
 local nextNewline = nextEnd > last and source:sub(nextEnd,nextEnd)=='\n'
 local below = source:sub(last+1, nextNewline and nextEnd-1 or nextEnd)
 return source:sub(1,first) .. below .. '\n' .. line .. (nextNewline and '\n' or '') .. source:sub(nextEnd+1), first+#below+1+column, bounds(first+#below+1,nextNewline)
end

function A:Selection(input)
 local state = input.queryEditor
 return state.selectionUnknown or (state.selectionStart and state.selectionEnd and state.selectionStart ~= state.selectionEnd)
end

function A:Cursor(input)
 local state, box = input.queryEditor, input.editBox
 if state.busy then return end
 local cursor = box:GetCursorPosition()
 if cursor ~= state.actionCursor and not state.actionLock then state.lineBlock = nil end
 if cursor == state.actionCursor and not state.mouseSelecting then return end
 if state.mouseSelecting then
  -- Mouse-down runs before the native EditBox places its cursor at the click.
  -- The first cursor callback supplies the actual start of a new mouse selection.
  if state.mouseAnchor == nil then state.mouseAnchor = cursor end
  state.selectionStart = state.mouseAnchor
  state.selectionEnd = cursor
  state.selectionUnknown = nil
 elseif _G.IsShiftKeyDown and IsShiftKeyDown() then
  state.selectionStart = state.selectionStart or state.actionCursor or cursor
  state.selectionEnd = cursor

 elseif not state.clipboard and not ((_G.IsControlKeyDown and IsControlKeyDown()) or (_G.IsMetaKeyDown and _G.IsMetaKeyDown())) then state.selectionStart, state.selectionEnd, state.selectionUnknown = nil, nil, nil end
 state.actionCursor = cursor
end

function A:BackwardRange(source, cursor, mode)
 local function previous(at)
  at = math.max(0, at-1)
  while at > 0 do
   local byte = source:byte(at+1)
   if not byte or byte < 128 or byte >= 192 then break end
   at = at-1
  end
  return at
 end
 if mode == 'character' then return previous(cursor) end
 local first = self:Bounds(source,cursor)
 if mode == 'line' then return first end
 if cursor == first then return previous(cursor) end
 local at = cursor
 while at > first and source:sub(at,at):match('[ \t]') do at=at-1 end
 if at == first then return first end
 local function word(pos)
  local byte = source:byte(pos)
  return byte and (byte >= 128 or source:sub(pos,pos):match('[%w_]') ~= nil)
 end
 local isWord = word(at)
 while at > first and not source:sub(at,at):match('[ \t]') and word(at) == isWord do at=previous(at) end
 return at
end

function A:BackwardWord(source, cursor)
 local target = self:BackwardRange(source,cursor,'word')
 local first = self:Bounds(source,cursor)
 local at = cursor
 while at > first and source:sub(at,at):match('[ \t]') do at=at-1 end
 local byte = source:byte(at)
 -- Backward navigation includes separators with the preceding word. Deletion
 -- keeps its own boundaries, and forward navigation still stops before a dot.
 if target > first and byte and byte < 128 and not source:sub(at,at):match('[%w_]') then
  local preceding = source:byte(target)
  if preceding and (preceding >= 128 or source:sub(target,target):match('[%w_]')) then
   target = self:BackwardRange(source,target,'word')
  end
 end
 return target
end

function A:ForwardWord(source, cursor)
 local _, last = self:Bounds(source,cursor)
 local finish = source:sub(last,last) == '\n' and last-1 or last
 if cursor >= finish then return math.min(#source,cursor+1) end
 local at = cursor
 while at < finish and source:sub(at+1,at+1):match('[ \t]') do at=at+1 end
 local function word(pos)
  local byte = source:byte(pos)
  return byte and (byte >= 128 or source:sub(pos,pos):match('[%w_]') ~= nil)
 end
 local isWord = word(at+1)
 while at < finish and not source:sub(at+1,at+1):match('[ \t]') and word(at+1) == isWord do at=at+1 end
 -- Starting on a separator includes the following word, but starting within
 -- a word still stops at its end so reversing a selection can leave punctuation.
 if not isWord then
  while at < finish and word(at+1) do at=at+1 end
 end
 return at
end

function A:RestoreNavigation(input)
 local state, box = input.queryEditor, input.editBox
 local range = state.navigationRange
 if not range or state.busy then return end
 if range.source ~= input:GetText() then
  state.navigationRange, state.navigationKey, state.actionLock = nil,nil,nil
  return
 end
 state.busy = true
 box:SetCursorPosition(range.target)
 if range.anchor then box:HighlightText(math.min(range.anchor,range.target),math.max(range.anchor,range.target))
 else box:HighlightText(0,0) end
 state.selectionStart, state.selectionEnd, state.selectionUnknown = range.anchor, range.anchor and range.target or nil, nil
 state.actionCursor = range.target
 state.busy = nil
end

function A:Navigate(input, key, line, extend)
 local state, box = input.queryEditor, input.editBox
 if extend and state.selectionUnknown then return end
 local source, cursor = input:GetText(), box:GetCursorPosition()
 local target
 if key == 'UP' or key == 'DOWN' then target = key == 'UP' and 0 or #source
 elseif line then
  local first,last = self:Bounds(source,cursor)
  target = key == 'LEFT' and first or (source:sub(last,last)=='\n' and last-1 or last)
 else target = key == 'LEFT' and self:BackwardWord(source,cursor) or self:ForwardWord(source,cursor) end
 local anchor = extend and (self:Selection(input) and state.selectionStart or cursor) or nil
 if addon.Autocomplete then
  addon.Autocomplete:Hide()
  addon.Autocomplete.keySource, addon.Autocomplete.keyCursor = nil,nil
 end
 state.lineBlock = nil
 state.actionLock, state.navigationKey = target,key
 state.navigationRange = {source=source,anchor=anchor,target=target}
 self:RestoreNavigation(input)
 return true
end

function A:Key(input, key)
 if input ~= addon.Query.Console.input then return end
 local state, box = input.queryEditor, input.editBox
 local ctrl = _G.IsControlKeyDown and IsControlKeyDown()
 local alt = _G.IsAltKeyDown and IsAltKeyDown()
 local shift = _G.IsShiftKeyDown and IsShiftKeyDown()
 local source, cursor = input:GetText(), box:GetCursorPosition()
 local meta = _G.IsMetaKeyDown and _G.IsMetaKeyDown()
 if _G.IsMacClient and _G.IsMacClient() and not ctrl and ((alt or meta) and (key=='LEFT' or key=='RIGHT') or meta and not alt and (key=='UP' or key=='DOWN')) then
  return self:Navigate(input,key,meta,shift)
 end
 if key == 'BACKSPACE' and _G.IsMacClient and _G.IsMacClient() and (ctrl or alt or meta)
  and not E:IsReadOnly(input) and not self:Selection(input) then
  local first = self:BackwardRange(source,cursor,meta and 'line' or (alt and 'word' or 'character'))
  local expected = source:sub(1,first)..source:sub(cursor+1)
  state.backwardDelete = {source=source, expected=expected, cursor=first}
  if source:sub(first+1,cursor) == '\n' then
   state.breakpointEdit = {oldSource=source,oldCursor=cursor,joinAt=first,expectedSource=expected}
  end
  if first ~= cursor then box:HighlightText(first,cursor) end
  if addon.Autocomplete then addon.Autocomplete:Hide() end
  return true
 end
 if alt and not ctrl and (key=='UP' or key=='DOWN') and not E:IsReadOnly(input) then
  if state.selectionUnknown then return end
  local first, last = state.selectionStart, state.selectionEnd
  local block = state.lineBlock
  if block and (block.source ~= source or block.actualCursor ~= cursor or block.selectionStart ~= first or block.selectionEnd ~= last) then block = nil end
  if block then first, last, cursor = block.logicalStart, block.logicalEnd, block.logicalCursor end
  local text, position, moved = self:Move(source,cursor,key=='UP' and -1 or 1,shift,first,last,block)
  E:SetSource(input,text,position)
  state.actionLock, state.actionCursor = math.min(position,#text), math.min(position,#text)
  if first and last and first ~= last then
   local delta = position-cursor
   state.selectionStart, state.selectionEnd = math.min(first+delta,#text), math.min(last+delta,#text)
   box:HighlightText(math.min(math.min(first,last)+delta,#text),math.min(math.max(first,last)+delta,#text))
   moved.source, moved.actualCursor = text, state.actionCursor
   moved.selectionStart, moved.selectionEnd = state.selectionStart, state.selectionEnd
   moved.logicalStart, moved.logicalEnd, moved.logicalCursor = first+delta, last+delta, position
   state.lineBlock = moved
  end
  if addon.Autocomplete then addon.Autocomplete:Hide() end
  return true
 end
 local nativeModifier = meta or (ctrl and not (_G.IsMacClient and _G.IsMacClient()))
 if not nativeModifier or alt then return end
 if key=='A' then state.selectionStart, state.selectionEnd=0,#source; return end
 if key=='C' or key=='X' then
  self.lineClipboard = nil
  if key=='X' and E:IsReadOnly(input) then return end
  if self:Selection(input) then
   -- Track native selection cuts so the consumed selection is cleared on key-up.
   if key=='X' then state.clipboard = {key=key, source=source, selection=true} end
   return
  end
  local first,last = self:Bounds(source,cursor)
  local text = source:sub(first+1,last)
  if text=='' then
   if key=='X' and first>0 and source:sub(-1)=='\n' then
    -- Select the preceding line break for native cut, including clipboard transfer.
    self.lineClipboard = '\n'
    state.clipboard = {key=key, source=source, cursor=cursor, first=first-1,last=first}
    box:HighlightText(first-1,first)
   end
   return
  end
  self.lineClipboard = text
  state.clipboard = {key=key, source=source, cursor=cursor, first=first,last=last}
  box:HighlightText(first,last)
 elseif key=='V' and not E:IsReadOnly(input) then
  state.nativePaste = true
  state.paste = {source=source,cursor=cursor,line=not self:Selection(input) and self.lineClipboard or nil}
 end
end

function A:Text(input, text)
 local state = input.queryEditor
 -- A native edit consumes its selection even while Command/Control stays held.
 -- Cursor callbacks alone cannot clear it because those modifiers preserve selections.
 if text ~= state.source then
  state.selectionStart, state.selectionEnd, state.selectionUnknown = nil,nil,nil
  state.actionCursor = input.editBox:GetCursorPosition()
 end
 local backward = state.backwardDelete
 if backward then
  state.backwardDelete = nil
  if state.source == backward.source then
   state.selectionStart, state.selectionEnd, state.selectionUnknown = nil,nil,nil
   state.actionCursor = backward.cursor
   return backward.expected, backward.cursor
  end
 end
 local paste = state.paste
 state.paste = nil
 if paste then
  local inserted = #text - #paste.source
  local payload = inserted >= 0 and text:sub(paste.cursor+1,paste.cursor+inserted)
  if paste.line and payload == paste.line and text == paste.source:sub(1,paste.cursor)..payload..paste.source:sub(paste.cursor+1) then
   local first = self:Bounds(paste.source,paste.cursor)
   payload = payload:gsub('\r\n','\n'):gsub('\r','\n')
   if payload:sub(-1) ~= '\n' then payload=payload..'\n' end
   return paste.source:sub(1,first)..payload..paste.source:sub(first+1), paste.cursor+#payload
  end
 end
 if text:find('\r',1,true) then
  local cursor=input.editBox:GetCursorPosition()
  return text:gsub('\r\n','\n'):gsub('\r','\n'), #(text:sub(1,cursor):gsub('\r\n','\n'):gsub('\r','\n'))
 end
 local clip=state.clipboard
 if clip and clip.key=='X' and not clip.selection and clip.first>0 and clip.last==#clip.source and clip.source:sub(-1)~='\n'
  and text==clip.source:sub(1,clip.first) then return text:sub(1,-2), math.max(0,clip.first-1) end
end

function A:KeyUp(input)
 local state, box = input.queryEditor, input.editBox
 if state.navigationKey then self:RestoreNavigation(input) end
 state.navigationKey, state.navigationRange = nil,nil
 local clip=state.clipboard
 local backward = state.backwardDelete
 state.backwardDelete = nil
 if backward then
  box:HighlightText(0,0)
  state.selectionStart, state.selectionEnd, state.selectionUnknown = nil,nil,nil
 end
 local pasted = state.nativePaste
 state.clipboard, state.paste, state.actionLock, state.nativePaste = nil,nil,nil,nil
 if clip and clip.key=='C' and input:GetText()==clip.source then
  box:HighlightText(0,0); box:SetCursorPosition(clip.cursor)
 elseif clip and clip.key=='X' and input:GetText()~=clip.source then
  -- Native cut consumed the prepared selection; it is no longer a user selection.
  box:HighlightText(0,0)
 end
 -- Native paste finishes with a caret, even when it replaces identical text.
 if pasted then box:HighlightText(0,0) end
 if pasted or (clip and (clip.key=='C' or input:GetText()~=clip.source)) then
  state.selectionStart, state.selectionEnd, state.selectionUnknown = nil, nil, nil
  state.actionCursor = box:GetCursorPosition()
 end
end

function A:Track(input)
 local box,state=input.editBox,input.queryEditor
 if state.selectionHook or not _G.hooksecurefunc then return end
 state.selectionHook=true
 _G.hooksecurefunc(box,'HighlightText',function(_,first,last)
  state.lineBlock = nil
  state.selectionStart,state.selectionEnd=first or 0,last and last>=0 and last or #box:GetText()
  state.selectionUnknown=nil
 end)
end

end
rm.LuaWorkbenchModules.Snippets=function(_,addon)
local S, UI, L = {}, addon.UI, addon.L
addon.Snippets = S

function S:Database()
 local db = addon.Workspace.db
 db.textSnippets = db.textSnippets or {}
 return db.textSnippets
end

function S:Save(id, name, source)
 name = tostring(name or ''):match('^%s*(.-)%s*$')
 if name == '' or not source or source == '' then return nil end
 local db = addon.Workspace.db
 if not id then
  db.textSnippetSerial = (db.textSnippetSerial or 0) + 1
  id = tostring(db.textSnippetSerial)
  while self:Database()[id] do
   db.textSnippetSerial = db.textSnippetSerial + 1
   id = tostring(db.textSnippetSerial)
  end
 end
 self:Database()[id] = { name = name, source = source }
 return id
end

function S:Delete(id) self:Database()[id] = nil end

function S:Entries(query)
 local entries = {}
 query = (query or ''):lower()
 for id, item in pairs(self:Database()) do
  if item.name:lower():find(query, 1, true) or item.source:lower():find(query, 1, true) then
   entries[#entries + 1] = { id = id, name = item.name, source = item.source }
  end
 end
 table.sort(entries, function(a, b) if a.name == b.name then return a.id < b.id end; return a.name < b.name end)
 return entries
end

function S:Capture(input)
 if not input then return nil end
 local box, source = input.editBox, input:GetText()
 local cursor = box:GetCursorPosition()
 return { input = input, source = source, start = cursor, finish = cursor, cursor = cursor, scriptId = addon.Workspace.current }
end

function S:Insert(text, target)
 target = target or self:Capture(addon.Query.Console.input)
 if target and addon.Query.Editor:IsReadOnly(target.input) then return false end
 if not target or target.scriptId ~= addon.Workspace.current or target.input:GetText() ~= target.source then
  addon.Query.Console:SetStatus(L.textSnippetTargetChanged, true)
  return false
 end
 local source = target.source:sub(1, target.start) .. text .. target.source:sub(target.finish + 1)
 addon.Query.Editor:SetSource(target.input, source, target.start + #text)
 target.input:SetFocus()
 return true
end

function S:OpenCodeMenu(input)
 if not input or input.readonly then return end
 local W, target = addon.Workspace, self:Capture(input)
 local function open(entries)
  W:OpenMenu(input.frame, entries)
  if _G.GetCursorPosition then
   local x, y = _G.GetCursorPosition()
   local scale = UIParent:GetEffectiveScale()
   W.contextMenu:ClearAllPoints(); W.contextMenu:SetPoint('TOPLEFT', UIParent, 'BOTTOMLEFT', x / scale, y / scale)
  end
 end
 local function valid()
  if target.scriptId == W.current and input:GetText() == target.source then return true end
  addon.Query.Console:SetStatus(L.textSnippetTargetChanged, true)
 end
 local entries = {
  { text = L.queryLuaFormat .. addon.ShortcutText(' (Shift+Alt+F)'), action = function() if valid() then addon.Query.Editor:FormatInput(input) end end },
  { text = L.textSnippetInsert, action = function()
   local items = {}
   for _, item in ipairs(self:Entries()) do
    local text = item.source
    items[#items + 1] = { text = item.name, action = function() self:Insert(text, target) end }
   end
   if #items == 0 then self:ShowLibrary(target) else open(items) end
  end },
  { text = L.helperModule, action = function()
   local items = {}
   for _, item in ipairs(addon.Helpers:Entries()) do
    local name = item.name
    items[#items + 1] = { text = name, action = function()
     self:Insert(addon.Helpers:ImportText(name, target.source, target.cursor), target)
    end }
   end
   if #items > 0 then open(items) else addon.Query.Console:SetStatus(L.helperMissing, true) end
  end },
 }
 if input == addon.Query.Console.input then
  entries[#entries + 1] = { text = L.goToDefinition .. ' (F12)', action = function() addon.Navigation:Go(target) end }
  if addon.Navigation:CanBack() then entries[#entries + 1] = { text = L.navigationBack .. addon.ShortcutText(' (Alt+Left)'), action = function() addon.Navigation:Back() end } end
 end
 open(entries)
end

function S:ShowLibrary(target)
 local W = addon.Workspace
 if not W.window then W:Show() end
 target = target or self:Capture(addon.Query.Console.input)
 W:HidePanels(self.panel)
 for _, key in ipairs({ 'optionsFrame', 'syntaxFrame', 'helpFrame', 'contextMenu' }) do
  if W[key] then W[key]:Hide() end
 end
 if addon.Diagnostics and addon.Diagnostics.panel then addon.Diagnostics.panel:Hide() end
 if addon.Automation and addon.Automation.panel then addon.Automation.panel:Hide() end
 if not self.panel then self:CreateLibrary() end
 local panel = self.panel
 panel.target = target
 panel.selected = nil
 panel.search:SetText('')
 panel.name:SetText('')
 panel.code:SetText('')
 panel.message:SetText('')
 panel.insert:SetShown(target ~= nil)
 panel.delete:SetShown(false)
 panel:Show()
 self:RefreshLibrary()
end

function S:RefreshLibrary()
 local panel = self.panel
 local entries = self:Entries(panel.search:GetText())
 for index, entry in ipairs(entries) do
  local button = panel.rows[index]
  if not button then
   button = CreateFrame('Button', nil, panel.content)
   button:SetHeight(30); button:SetPoint('LEFT', 0, 0); button:SetPoint('RIGHT', 0, 0)
   button.background = UI:Background(button, UI.colors.panel)
   local hover = button:CreateTexture(nil, 'HIGHLIGHT'); hover:SetAllPoints(); hover:SetColorTexture(1, 1, 1, 0.07)
   button.text = UI:Text(button, '', 12); button.text:SetPoint('LEFT', 8, 0); button.text:SetPoint('RIGHT', -8, 0); button.text:SetWordWrap(false)
   button:SetScript('OnClick', function()
    local item = self:Database()[button.id]
    if not item then return end
    panel.selected = button.id
    panel.name:SetText(item.name); panel.code:SetText(item.source); panel.message:SetText(''); panel.delete:SetShown(true)
    self:RefreshLibrary()
   end)
   panel.rows[index] = button
  end
  button.id = entry.id
  button:ClearAllPoints(); button:SetPoint('TOPLEFT', 0, -(index - 1) * 32); button:SetPoint('RIGHT', 0, 0)
  button.background:SetColorTexture(unpack(panel.selected == entry.id and { 0.12, 0.24, 0.38, 1 } or UI.colors.panel))
  button.text:SetText(entry.name:gsub('|', '||')); button:Show()
 end
 for index = #entries + 1, #panel.rows do panel.rows[index]:Hide() end
 panel.content:SetHeight(math.max(1, #entries * 32))
 panel.empty:SetShown(#entries == 0)
end

function S:CreateLibrary()
 local W = addon.Workspace
 local panel = CreateFrame('Frame', (not addon.embedded and 'LuaWorkbenchTextSnippets' or nil), W.window)
 self.panel = panel
 if not addon.embedded then _G.UISpecialFrames[#_G.UISpecialFrames + 1] = (not addon.embedded and 'LuaWorkbenchTextSnippets' or nil) end
 panel:SetSize(math.min(730, W.window:GetWidth() - 24), math.min(510, W.window:GetHeight() - 30))
 panel:SetPoint('CENTER'); panel:SetFrameLevel(W.window:GetFrameLevel() + 40); panel:EnableMouse(true)
 UI:MovablePanel(panel, 'textSnippets'); panel:RestorePanelPosition()
 UI:Background(panel, { 0.09, 0.11, 0.15, 1 }); UI:Border(panel, { 0.25, 0.3, 0.38, 1 })
 local title = UI:Text(panel, L.textSnippets, 15); title:SetPoint('TOPLEFT', 16, -15)
 local close = UI:Button(panel, 'close', _G.CLOSE, function() panel:Hide() end); close:SetPoint('TOPRIGHT', -6, -7)
 local function field(label, x, y, width)
  local text = UI:Text(panel, label, 11); text:SetPoint('TOPLEFT', x, y)
  local box = CreateFrame('EditBox', nil, panel); box:SetSize(width, 28); box:SetPoint('TOPLEFT', x, y - 18)
  box:SetFontObject(ChatFontNormal); box:SetAutoFocus(false); box:SetTextInsets(7, 7, 0, 0)
  UI:Background(box, UI.colors.hover)
  box:SetScript('OnEscapePressed', function() box:ClearFocus(); panel:Hide() end)
  return box
 end
 panel.search = field(L.textSnippetSearch, 14, -49, 205)
 panel.search:SetScript('OnTextChanged', function() self:RefreshLibrary() end)
 UI:SearchClear(panel.search)
 panel.name = field(L.textSnippetName, 234, -49, panel:GetWidth() - 248)
 panel.name:SetMaxLetters(120)
 local scroll = UI:Scroll(panel); scroll:SetPoint('TOPLEFT', 14, -102); scroll:SetPoint('BOTTOMLEFT', 14, 66); scroll:SetWidth(195)
 panel.content = CreateFrame('Frame', nil, scroll); panel.content:SetSize(195, 1); scroll:SetScrollChild(panel.content)
 panel.rows = {}
 panel.empty = UI:Text(panel.content, L.textSnippetEmpty, 11); panel.empty:SetPoint('TOPLEFT', 7, -8); panel.empty:SetWidth(180)
 panel.code = UI:Editor(panel, L.textSnippetCode)
 addon.Query.Editor:Attach(panel.code)
 W:ApplyOptions()
 panel.code.frame:SetPoint('TOPLEFT', 234, -102); panel.code.frame:SetPoint('BOTTOMRIGHT', -14, 72)
 panel.message = UI:Text(panel, '', 11); panel.message:SetPoint('BOTTOMLEFT', 234, 48); panel.message:SetPoint('RIGHT', -14, 0); panel.message:SetHeight(22)
 local new = UI:Button(panel, 'new', L.textSnippetNew, function()
  panel.selected = nil; panel.name:SetText(''); panel.code:SetText(''); panel.message:SetText(''); panel.delete:Hide(); panel.name:SetFocus(); self:RefreshLibrary()
 end); new:SetPoint('BOTTOMLEFT', 14, 16)
 panel.delete = UI:Button(panel, 'clear', L.textSnippetDelete, function()
  if not panel.selected then return end
  StaticPopup_Show('LUAWORKBENCH_DELETE_TEXT_SNIPPET', nil, nil, panel.selected)
 end); panel.delete:SetPoint('LEFT', new, 'RIGHT', 6, 0)
 local save = UI:Action(panel, 'save', L.textSnippetSave, L.textSnippetSave, function()
  local id = self:Save(panel.selected, panel.name:GetText(), panel.code:GetText())
  if not id then panel.message:SetText(L.textSnippetRequired); return end
  panel.selected = id; panel.delete:Show(); panel.message:SetText(''); self:RefreshLibrary()
 end); save:SetPoint('BOTTOMLEFT', 234, 14)
 panel.insert = UI:Action(panel, 'next', L.textSnippetInsert, L.textSnippetInsert, function()
  if panel.code:GetText() == '' then panel.message:SetText(L.textSnippetRequired); return end
  if self:Insert(panel.code:GetText(), panel.target) then panel:Hide() end
 end); panel.insert:SetPoint('BOTTOMRIGHT', -14, 14)
 panel:SetScript('OnHide', function() panel.name:ClearFocus(); panel.search:ClearFocus(); panel.code:ClearFocus() end)
 StaticPopupDialogs.LUAWORKBENCH_DELETE_TEXT_SNIPPET = {
  text = L.textSnippetDeleteConfirm, button1 = _G.DELETE, button2 = _G.CANCEL, timeout = 0, whileDead = true, hideOnEscape = true,
  OnAccept = function(_, id)
   self:Delete(id)
   if panel.selected == id then panel.selected = nil; panel.name:SetText(''); panel.code:SetText(''); panel.delete:Hide() end
   self:RefreshLibrary()
  end,
 }
end

end
rm.LuaWorkbenchModules.Automation=function(_,addon)
local W, UI, L, Console = addon.Workspace, addon.UI, addon.L, addon.Query.Console
local function pack(...) return { n = select('#', ...), ... } end
local A = { environments = {}, running = {}, initialized = false }
addon.Automation = A

function A:ValidateEvent(value)
 local event = (value or ''):match('^%s*(.-)%s*$'):upper()
 if not event:match('^[A-Z][A-Z0-9_]*$') then return nil end
 self.probe = self.probe or CreateFrame('Frame')
 local ok, result = pcall(self.probe.RegisterEvent, self.probe, event)
 self.probe:UnregisterAllEvents()
 if ok and result ~= false then return event end
end

function A:Options(id)
 local options = W.db.autoRun[id]
 if not options then options = {}; W.db.autoRun[id] = options end
 if not options.events then
  options.events = {}
  if type(options.event) == 'string' and options.event ~= '' then
   options.events[1] = { name = options.event, enabled = options.eventEnabled == true }
  end
 end
 options.event, options.eventEnabled = nil, nil
 return options
end

function A:HasEvent(options, event)
 for _, entry in ipairs(options.events or {}) do
  if entry.enabled and entry.name == event then return true end
 end
 return false
end

function A:Summary(id)
 local options = W.db.autoRun[id]
 if not options then return '' end
 local parts = {}
 if options.startup then parts[#parts + 1] = L.triggerStartup end
 if options.login then parts[#parts + 1] = L.triggerLogin end
 local count = 0
 for _, entry in ipairs(options.events or {}) do if entry.enabled then count = count + 1 end end
 if count > 0 then parts[#parts + 1] = string.format(L.triggerEvents, count) end
 return table.concat(parts, ' + ')
end

function A:Tooltip(id)
 local options = self:Options(id)
 local lines = { L.automaticRun }
 if options.startup then lines[#lines + 1] = L.runOnStartup end
 if options.login then lines[#lines + 1] = L.runOnLogin end
 for _, entry in ipairs(options.events) do if entry.enabled then lines[#lines + 1] = entry.name end end
 lines[#lines + 1] = '\n' .. (W.db.snippets[id] and L.savedCodeOnly or L.saveBeforeAutoRun)
 return table.concat(lines, '\n')
end

function A:Refresh()
 if not W.db then return end
 self.frame:UnregisterAllEvents()
 for _, event in ipairs({ 'ADDON_LOADED', 'PLAYER_LOGIN', 'PLAYER_LOGOUT' }) do self.frame:RegisterEvent(event) end
 for id in pairs(W.db.autoRun) do
  if not W.db.snippets[id] and not W.db.drafts[id] then
   W.db.autoRun[id], self.environments[id] = nil, nil
  else
   local options = self:Options(id)
   for _, entry in ipairs(options.events) do
    if entry.enabled then
     local event = self:ValidateEvent(entry.name)
     if event then
      entry.name = event
      if W.db.snippets[id] then self.frame:RegisterEvent(event) end
     else
      entry.enabled = false
      Console:Write(L.invalidEvent, entry.name)
     end
    end
   end
  end
 end
end

function A:Changed()
 self:Refresh()
 self:UpdateControls()
 W:RefreshTree()
end

function A:AddEvent(id, value)
 local event = self:ValidateEvent(value)
 if not event then return false, L.invalidEvent .. ' ' .. value end
 local options = self:Options(id)
 for _, entry in ipairs(options.events) do
  if entry.name == event then return false, L.eventAlreadyAdded end
 end
 options.events[#options.events + 1] = { name = event, enabled = true }
 self:Changed()
 return true
end

function A:RemoveEvent(id, index)
 table.remove(self:Options(id).events, index)
 self:Changed()
end

function A:Run(id, snippet, event, ...)
 -- The debugger owns event delivery for its snapshot; never run the saved script twice.
 if addon.Debugger and ((addon.Debugger.armed and addon.Debugger.scriptId == id) or addon.Debugger.startupOwnedId == id) then return end
 if self.running[id] or not snippet.source:find('%S') then return end
 self.running[id] = true
 if W.db.clearOnRun[id] then Console:Clear() end
 local prefix = '[' .. snippet.name .. '] '
 local environment = self.environments[id]
 if not environment then
  environment = setmetatable({ addon = addon, editor = addon,
  }, { __index = _G })
  self.environments[id] = environment
 end
 environment.print = function(...) Console:Write(prefix, ...) end
 environment.DevTools_Dump = function(value, startKey) Console:Dump(value, startKey, prefix) end
 environment.dump = function(...) Console:DumpArguments(prefix, ...) end
 environment.event = event
 environment.requireHelper = addon.Helpers:Loader({ print = environment.print, dump = environment.dump, DevTools_Dump = environment.DevTools_Dump, event = event })
 local chunk, message
 if _G.loadstring and _G.setfenv then
  chunk, message = _G.loadstring(W:NormalizeSource(snippet.source), '=LuaWorkbench[' .. snippet.name .. ']')
 else message = L.queryLuaUnavailable end
 local ok, stackTrace = false, nil
 if chunk then
  _G.setfenv(chunk, environment)
  -- A closure forwards event arguments on Lua 5.1, preserving nil arguments.
  local arguments = { n = select('#', ...), ... }
  local results = pack(xpcall(function() return chunk(unpack(arguments, 1, arguments.n)) end, function(value)
   if type(_G.debugstack) == 'function' then
    local captured, trace = pcall(_G.debugstack, 2, 20, 20)
    if captured then stackTrace = Console:Format(trace) end
   end
   return Console:Format(value)
  end))
  if results[1] and results.n > 1 then Console:Write(prefix .. 'return', unpack(results, 2, results.n)) end
  ok, message = results[1], results[2]
 end
 if not ok then
  addon.Diagnostics:Record(message, stackTrace, id, snippet.name, event)
  Console:Write(prefix .. L.queryLuaError, message)
 end
 Console:SetStatus(prefix .. (ok and L.queryLuaComplete or (L.queryLuaError .. ' ' .. Console:Format(message))), not ok)
 self.running[id] = nil
end

function A:Dispatch(event, startup, ...)
 local jobs = {}
 for id, snippet in pairs(W.db.snippets) do
  local options = W.db.autoRun[id]
  if options and ((startup and options.startup) or (event == 'PLAYER_LOGIN' and options.login)
   or self:HasEvent(options, event)) then
   jobs[#jobs + 1] = { id = id, name = snippet.name, source = snippet.source }
  end
 end
 table.sort(jobs, function(a, b) return a.id < b.id end)
 for _, job in ipairs(jobs) do self:Run(job.id, job, event, ...) end
end

function A:OnEvent(event, ...)
 local startup = event == 'ADDON_LOADED' and (...) == addonName
 if startup then
  if self.initialized then return end
  W:Initialize()
  self.initialized = true
  self:Refresh()
  W:UpdateMinimap()
  if addon.Debugger then addon.Debugger:RestoreStartup() end
 end
 if not self.initialized then return end
 if addon.Debugger then addon.Debugger:DispatchStartup(event, startup, ...) end
 self:Dispatch(event, startup, ...)
 if event == 'PLAYER_LOGOUT' then
  W:Capture(); W:SaveGeometry('window'); W:SaveGeometry('minibar')
  if W.db.options.restoreDrafts == false then W:DiscardSessionDrafts() end
 end
end

function A:SetOption(key, value)
 if not W.current then return end
 self:Options(W.current)[key] = value
 self:Changed()
end

function A:UpdateControls()
 if not self.controls or not W.current then return end
 local options = self:Options(W.current)
 local summary = self:Summary(W.current)
 self.summary:SetText(summary ~= '' and (L.automaticRun .. ': ' .. summary) or '')
 self.name:SetText(((W.currentName or L.newSnippet):gsub('|', '||')))
 if self.controlID ~= W.current then
  self.controlID = W.current
  self.controls.event:ClearFocus()
  self.controls.event:SetText('')
  self.error:SetText('')
  self.panel:Hide()
 end
 for _, key in ipairs({ 'startup', 'login' }) do self.controls[key]:SetChecked(options[key] == true) end
 W.clearOnRun:SetChecked(W.db.clearOnRun[W.current] == true)
 W:UpdateClearOnRunIndicator()
 self.notice:SetText(W.db.snippets[W.current] and L.savedCodeOnly or L.saveBeforeAutoRun)
 addon.Helpers:UpdateControls()
 if self.panel:IsShown() then self:UpdateEventRows() end
end

function A:UpdateEventRows()
 local events = self:Options(W.current).events
 for index, entry in ipairs(events) do
  local row = self.eventRows[index]
  if not row then
   row = UI:Check(self.content, '', function(button)
    local current = self:Options(W.current).events[index]
    current.enabled = button:GetChecked() == true
    self:Changed()
   end)
   row:SetHeight(28)
   row.remove = UI:Button(row, 'close', L.removeEvent, function() self:RemoveEvent(W.current, index) end)
   row.remove:SetPoint('RIGHT'); row.remove:SetSize(24, 24)
   row.label:SetPoint('RIGHT', -30, 0)
   self.eventRows[index] = row
  end
  row:SetPoint('TOPLEFT', 0, -self.eventsTop - (index - 1) * 30)
  row:SetPoint('TOPRIGHT', 0, -self.eventsTop - (index - 1) * 30)
  row.label:SetText(entry.name); row:SetChecked(entry.enabled == true); row:Show()
 end
 for index = #events + 1, #self.eventRows do self.eventRows[index]:Hide() end
 local y = self.eventsTop + #events * 30 + 16
 self.outputHeading:SetPoint('TOPLEFT', 0, -y)
 W.clearOnRun:SetPoint('TOPLEFT', 0, -y - 24)
 y = addon.Helpers:LayoutControls(y + 64)
 self.notice:SetPoint('TOPLEFT', 0, -y)
 self.content:SetHeight(y + self.notice:GetStringHeight() + 16)
 self.scroll:UpdateScrollChildRect()
end

function A:Toggle(owner)
 W:HidePanels(self.panel)
 if self.panel:IsShown() and self.owner == owner then self.panel:Hide(); return end
 if W.optionsFrame then W.optionsFrame:Hide() end
 if W.syntaxFrame then W.syntaxFrame:Hide() end
 if addon.Diagnostics.panel then addon.Diagnostics.panel:Hide() end
 if W.helpFrame then W.helpFrame:Hide() end
 if W.contextMenu then W.contextMenu:Hide() end
 Console.input:ClearFocus()
 self.owner = owner
 self.panel:SetSize(math.min(420, W.window:GetWidth() - 32), math.min(520, W.window:GetHeight() - 70))
 self.panel:ClearAllPoints(); self.panel:SetPoint('TOPLEFT', self.gear, 'BOTTOMLEFT', 0, -4)
 self.panel:RestorePanelPosition()
 self.content:SetWidth(self.panel:GetWidth() - 42)
 self:UpdateControls()
 self.panel:Show()
 self:UpdateEventRows()
 self.scroll:SetVerticalScroll(0)
end

